def _passed_tts_audio_integrity_evidence(source_text, path):
    return {
        'kind': 'ollmo.tts_audio_integrity_evidence',
        'version': 1,
        'policy_id': TTS_AUDIO_INTEGRITY_POLICY_ID,
        'authority': 'runtime_deterministic_audio_verification',
        'status': 'passed',
        'reason_code': 'TTS_AUDIO_INTEGRITY_PASSED',
        'materialization_eligible': True,
        'artifact_path': path,
        'source_sha256': hashlib.sha256(
            str(source_text).encode('utf-8')
        ).hexdigest(),
    }


class ResponsesApiTests(unittest.TestCase):
    def setUp(self):
        app.config["TESTING"] = True
        self._live_runtime_snapshots = {}
        for path in (Path("model_ports.json"), Path("state/runtime_status.json")):
            try:
                self._live_runtime_snapshots[path] = path.read_text(encoding="utf-8")
            except FileNotFoundError:
                self._live_runtime_snapshots[path] = None
        self._runtime_tmpdir = tempfile.TemporaryDirectory()
        self._runtime_registry_path = Path(self._runtime_tmpdir.name) / "model_ports.json"
        self._runtime_status_path = Path(self._runtime_tmpdir.name) / "runtime_status.json"
        self._response_frames_dir = Path(self._runtime_tmpdir.name) / "response_frames"
        self._chat_history_dir = Path(self._runtime_tmpdir.name) / "chat_history"
        self._ghost_preferences_path = Path(self._runtime_tmpdir.name) / "ghost_preferences.json"
        self._response_frames_dir.mkdir(parents=True, exist_ok=True)
        self._chat_history_dir.mkdir(parents=True, exist_ok=True)
        self._runtime_registry_path.write_text("[]\n", encoding="utf-8")
        self._runtime_status_path.write_text(
            json.dumps({"schema_version": 1, "updated_at": "test", "instances": {}}),
            encoding="utf-8",
        )

        def read_isolated_chat_history(instance_id, *args, **kwargs):
            if kwargs.get("history_dir") is None:
                kwargs["history_dir"] = self._chat_history_dir
            return read_chat_history(instance_id, *args, **kwargs)

        self._runtime_patchers = [
            patch("ollmo_webserver.CONFIG_FILE_NAME", str(self._runtime_registry_path)),
            patch("ollmo_webserver.RUNTIME_STATUS_PATH", self._runtime_status_path),
            patch("ollmo_webserver.RESPONSE_FRAMES_DIR", self._response_frames_dir),
            patch("ollmo_webserver.CHAT_HISTORY_DIR", self._chat_history_dir),
            patch("ollmo_webserver.GHOST_PREFERENCES_PATH", self._ghost_preferences_path),
            patch("ollmo_g.router.read_chat_history", side_effect=read_isolated_chat_history),
            patch(
                "ollmo_server.ghost_route_runtime.read_chat_history",
                side_effect=read_isolated_chat_history,
            ),
            patch("ollmo_webserver.load_running_instances", return_value=[]),
            patch("ollmo_core.registry.DEFAULT_REGISTRY_PATH", self._runtime_registry_path),
            patch("ollmo_core.status.DEFAULT_RUNTIME_STATUS_PATH", self._runtime_status_path),
        ]
        for patcher in self._runtime_patchers:
            patcher.start()
        self.client = app.test_client()
        _RESPONSE_LOOKUP.clear()
        _RESPONSE_LATE_FILL_IN_FLIGHT.clear()

    def _canonical_truth_for_payload(self, payload):
        response_id = str(
            (payload or {}).get("id") or (payload or {}).get("response_id") or ""
        ).strip()
        self.assertTrue(response_id, "wire payload did not expose a response id")
        response = self.client.get(f"/api/responses/{response_id}?view=truth")
        self.assertEqual(response.status_code, 200)
        return response.get_json()

    def test_route_history_reads_use_isolated_root_and_preserve_explicit_override(self):
        from ollmo_services import chat_history as chat_history_service
        from ollmo_server import ghost_route_runtime

        conversation_id = "responses_route_history_isolation"
        write_chat_history(
            conversation_id,
            [
                {"role": "user", "content": "Remember the copper lighthouse."},
                {"role": "assistant", "content": "The copper lighthouse is remembered."},
            ],
            history_dir=self._chat_history_dir,
        )
        real_history_path = chat_history_service._history_path
        observed_history_dirs = []

        def guarded_history_path(instance_id, history_dir=None):
            observed_history_dirs.append(history_dir)
            if history_dir is None or Path(history_dir).resolve() != self._chat_history_dir.resolve():
                raise AssertionError("route history reader escaped the isolated test root")
            return real_history_path(instance_id, history_dir)

        with patch(
            "ollmo_services.chat_history._history_path",
            side_effect=guarded_history_path,
        ):
            history_response = self.client.get(
                "/api/chat_history",
                query_string={"instance_id": conversation_id},
            )
            route_context = build_route_context(
                prompt="Continue with that lighthouse.",
                upload_filename="",
                file_path="",
                conversation_id=conversation_id,
                messages=[],
                runtime_manifest={},
                ghost_payload={},
                instances=[],
            )

        self.assertTrue(observed_history_dirs)
        self.assertEqual(history_response.status_code, 200)
        self.assertEqual(len(history_response.get_json()["messages"]), 2)
        self.assertTrue(route_context["recent_messages"])
        self.assertIn("copper lighthouse", route_context["recent_messages"][-1]["content"])

        explicit_history_dir = Path(self._runtime_tmpdir.name) / "explicit_chat_history"
        write_chat_history(
            "responses_explicit_history_override",
            [{"role": "assistant", "content": "Explicit history root."}],
            history_dir=explicit_history_dir,
        )
        explicit_history = ghost_route_runtime.read_chat_history(
            "responses_explicit_history_override",
            history_dir=explicit_history_dir,
        )
        self.assertEqual(explicit_history["messages"][0]["content"], "Explicit history root.")

    def tearDown(self):
        for patcher in reversed(getattr(self, "_runtime_patchers", [])):
            patcher.stop()
        tmpdir = getattr(self, "_runtime_tmpdir", None)
        if tmpdir is not None:
            tmpdir.cleanup()
        for path, content in getattr(self, "_live_runtime_snapshots", {}).items():
            if content is None:
                continue
            try:
                current = path.read_text(encoding="utf-8")
            except FileNotFoundError:
                current = None
            if current != content:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")

    def test_api_ghost_preferences_returns_defaults_when_missing(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            target = Path(tmpdir) / "ghost_preferences.json"
            with patch("ollmo_webserver.GHOST_PREFERENCES_PATH", target):
                response = self.client.get("/api/ghost_preferences")

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["preferences"], {})
        self.assertFalse(payload["expanded"])
        self.assertIsNone(payload["updated_at"])

    def test_response_bundle_artifacts_creates_bundle_and_registry_record(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            source_dir = root / "source"
            source_dir.mkdir()
            index_path = source_dir / "index.html"
            styles_path = source_dir / "styles.css"
            image_path = source_dir / "hero.png"
            index_path.write_text(
                '<!doctype html><link rel="stylesheet" href="styles.css"><img src="hero.png">',
                encoding="utf-8",
            )
            styles_path.write_text('body { background: url("hero.png"); }', encoding="utf-8")
            image_path.write_bytes(b"png")
            response_id = "resp_bundle_api"
            _RESPONSE_LOOKUP[response_id] = {
                "id": response_id,
                "status": "completed",
                "lifecycle_state": "completed",
                "expires_at_ts": time.time() + 3600,
                "response_payload": {
                    "id": response_id,
                    "status": "completed",
                    "output_text": "Artifacts are ready.",
                    "artifacts": [
                        {"type": "text", "path": str(index_path), "name": "index", "artifact_ref": "artifact:index"},
                        {"type": "text", "path": str(styles_path), "name": "styles", "artifact_ref": "artifact:styles"},
                        {"type": "image", "path": str(image_path), "name": "hero", "artifact_ref": "artifact:hero"},
                    ],
                },
            }
            registry_path = root / "artifact_registry.jsonl"
            with (
                patch("ollmo_webserver.ARTIFACT_BUNDLES_DIR", root / "bundles"),
                patch("ollmo_webserver.ARTIFACT_REGISTRY_LEDGER", registry_path),
            ):
                response = self.client.post(
                    f"/api/responses/{response_id}/bundle_artifacts",
                    json={"target_name": "customer_demo"},
                )

            self.assertEqual(response.status_code, 200)
            payload = response.get_json()
            bundle = payload["bundle"]
            self.assertEqual(bundle["status"], "bundled")
            self.assertTrue(Path(bundle["bundle_path"]).is_dir())
            self.assertTrue(Path(bundle["entrypoint"]).is_file())
            self.assertTrue(Path(bundle["manifest_path"]).is_file())
            registry_text = registry_path.read_text(encoding="utf-8")
            self.assertIn("response_artifact_bundle", registry_text)
            self.assertIn(response_id, registry_text)

    def test_response_bundle_artifacts_uses_canonical_truth_when_wire_handles_are_truncated(self):
        response_id = "resp_bundle_truncated_wire_handles"
        wire_payload = {
            "id": response_id,
            "status": "completed",
            "response_frame": {"frame_id": "frame-bundle-2", "frame_sequence": 2},
            "artifacts": [
                {"artifact_ref": f"artifact:{index}", "path": f"/tmp/{index}.txt"}
                for index in range(64)
            ],
            "wire_projection": {
                "source": "current_index_compact_ledger_frame",
                "public_projection_truncation": {
                    "truncated_collection_item_count": 1,
                },
            },
        }
        canonical_payload = {
            "id": response_id,
            "status": "completed",
            "response_frame": {"frame_id": "frame-bundle-2", "frame_sequence": 2},
            "artifacts": [
                {"artifact_ref": f"artifact:{index}", "path": f"/tmp/{index}.txt"}
                for index in range(65)
            ],
        }
        bounded_record = {
            "id": response_id,
            "status": "completed",
            "response_payload": wire_payload,
        }
        bundle_payload = {
            "status": "bundled",
            "bundle_id": "bundle:complete",
            "bundle_path": "/tmp/bundle-complete",
            "source_response_id": response_id,
        }
        with patch(
            "ollmo_webserver._get_bounded_response_lookup_record",
            return_value=(bounded_record, None, 200),
        ), patch(
            "ollmo_webserver._load_latest_response_state",
            return_value={"ok": True, "response_payload": canonical_payload},
        ) as mock_load_truth, patch(
            "ollmo_webserver._hydrate_bundle_payload_artifacts_from_registry",
            side_effect=lambda payload: payload,
        ), patch(
            "ollmo_webserver._bundle_response_artifacts",
            return_value=bundle_payload,
        ) as mock_bundle, patch(
            "ollmo_webserver._persist_response_artifact_bundle_record",
        ), patch(
            "ollmo_webserver._log_unified_event",
        ):
            response = self.client.post(
                f"/api/responses/{response_id}/bundle_artifacts",
                json={},
            )

        self.assertEqual(response.status_code, 200)
        mock_load_truth.assert_called_once()
        self.assertEqual(len(mock_bundle.call_args.args[0]["artifacts"]), 65)

    def test_response_bundle_artifacts_rejects_canonical_frame_cas_mismatch(self):
        response_id = "resp_bundle_frame_cas_mismatch"
        bounded_record = {
            "id": response_id,
            "status": "completed",
            "response_payload": {
                "id": response_id,
                "status": "completed",
                "response_frame": {"frame_id": "frame-live-2", "frame_sequence": 2},
                "artifacts": [{"artifact_ref": "artifact:new", "path": "/tmp/new.txt"}],
                "wire_projection": {
                    "source": "current_index_compact_ledger_frame",
                    "public_projection_truncation": {"truncated_collection_item_count": 1},
                },
            },
        }
        with patch(
            "ollmo_webserver._get_bounded_response_lookup_record",
            return_value=(bounded_record, None, 200),
        ), patch(
            "ollmo_webserver._load_latest_response_state",
            return_value={
                "ok": True,
                "response_payload": {
                    "id": response_id,
                    "status": "completed",
                    "response_frame": {"frame_id": "frame-durable-1", "frame_sequence": 1},
                    "artifacts": [{"artifact_ref": "artifact:old", "path": "/tmp/old.txt"}],
                },
            },
        ), patch("ollmo_webserver._bundle_response_artifacts") as mock_bundle:
            response = self.client.post(
                f"/api/responses/{response_id}/bundle_artifacts",
                json={},
            )

        self.assertEqual(response.status_code, 409)
        self.assertEqual(
            response.get_json()["error_detail"]["code"],
            "response_artifact_bundle_frame_binding_mismatch",
        )
        mock_bundle.assert_not_called()

    def test_response_lookup_hydrates_artifact_bundles_from_registry(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            bundle_dir = root / "bundles" / "20260526T181030Z_package_resp_bundle_lookup"
            bundle_dir.mkdir(parents=True)
            entrypoint = bundle_dir / "index.html"
            manifest_path = bundle_dir / "manifest.json"
            entrypoint.write_text("<!doctype html><title>Bundled</title>", encoding="utf-8")
            manifest_path.write_text("{}\n", encoding="utf-8")
            response_id = "resp_bundle_lookup"
            bundle_payload = {
                "status": "bundled",
                "bundle_id": "bundle:test_lookup",
                "bundle_path": str(bundle_dir),
                "entrypoint": str(entrypoint),
                "manifest_path": str(manifest_path),
                "source_response_id": response_id,
                "source_artifact_refs": ["artifact:index"],
                "link_check": {"status": "passed", "missing": []},
            }
            registry_path = root / "artifact_registry.jsonl"
            registry_path.write_text(
                json.dumps(
                    {
                        "kind": "ollmo.artifact_registry_record",
                        "artifact_ref": "bundle:test_lookup",
                        "artifact": {
                            "type": "bundle",
                            "kind": "response_artifact_bundle",
                            "artifact_ref": "bundle:test_lookup",
                            "path": str(bundle_dir),
                            "entrypoint": str(entrypoint),
                            "manifest_path": str(manifest_path),
                            "source_response_id": response_id,
                        },
                        "bundle": bundle_payload,
                        "source": {"kind": "response_artifact_bundle", "response_id": response_id},
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            _RESPONSE_LOOKUP[response_id] = {
                "id": response_id,
                "status": "completed",
                "lifecycle_state": "completed",
                "expires_at_ts": time.time() + 3600,
                "response_payload": {
                    "id": response_id,
                    "status": "completed",
                    "output_text": "Artifacts are bundled.",
                },
            }

            with patch("ollmo_webserver.ARTIFACT_REGISTRY_LEDGER", registry_path):
                response = self.client.get(f"/api/responses/{response_id}")

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["artifact_bundles"][0]["bundle_path"], str(bundle_dir))
        self.assertEqual(payload["artifactBundles"][0]["bundle_id"], "bundle:test_lookup")
        self.assertEqual(payload["artifactBundle"]["entrypoint"], str(entrypoint))

