    def test_response_lookup_hydrates_only_latest_openable_artifact_bundle(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            old_bundle_dir = root / "bundles" / "20260526T181030Z_package_resp_bundle_multi"
            latest_bundle_dir = root / "bundles" / "20260526T181232Z_package_resp_bundle_multi"
            old_bundle_dir.mkdir(parents=True)
            latest_bundle_dir.mkdir(parents=True)
            (old_bundle_dir / "index.html").write_text("<!doctype html><title>Old</title>", encoding="utf-8")
            (latest_bundle_dir / "index.html").write_text("<!doctype html><title>Latest</title>", encoding="utf-8")
            missing_bundle_dir = root / "bundles" / "20260526T181107Z_package_resp_bundle_multi"
            response_id = "resp_bundle_lookup_multi"
            registry_path = root / "artifact_registry.jsonl"

            records = []
            for bundle_id, bundle_dir in (
                ("bundle:test_old", old_bundle_dir),
                ("bundle:test_missing_middle", missing_bundle_dir),
                ("bundle:test_latest", latest_bundle_dir),
            ):
                records.append(
                    {
                        "kind": "ollmo.artifact_registry_record",
                        "artifact_ref": bundle_id,
                        "artifact": {
                            "type": "bundle",
                            "kind": "response_artifact_bundle",
                            "artifact_ref": bundle_id,
                            "path": str(bundle_dir),
                            "entrypoint": str(bundle_dir / "index.html"),
                            "source_response_id": response_id,
                        },
                        "bundle": {
                            "status": "bundled",
                            "bundle_id": bundle_id,
                            "bundle_path": str(bundle_dir),
                            "entrypoint": str(bundle_dir / "index.html"),
                            "source_response_id": response_id,
                        },
                        "source": {"kind": "response_artifact_bundle", "response_id": response_id},
                    }
                )
            registry_path.write_text(
                "".join(json.dumps(record) + "\n" for record in records),
                encoding="utf-8",
            )
            _RESPONSE_LOOKUP[response_id] = {
                "id": response_id,
                "status": "completed",
                "lifecycle_state": "completed",
                "expires_at_ts": time.time() + 3600,
                "response_payload": {
                    "id": response_id,
                    "status": "completed",
                    "output_text": "Artifacts have a latest bundle.",
                },
            }

            with patch("ollmo_webserver.ARTIFACT_REGISTRY_LEDGER", registry_path):
                response = self.client.get(f"/api/responses/{response_id}")

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(len(payload["artifact_bundles"]), 1)
        self.assertEqual(payload["artifact_bundles"][0]["bundle_id"], "bundle:test_latest")
        self.assertEqual(payload["artifact_bundles"][0]["bundle_path"], str(latest_bundle_dir))

    def test_chat_history_hydrates_artifact_bundles_from_registry(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            history_dir = root / "chat_history"
            bundle_dir = root / "bundles" / "20260526T181107Z_package_resp_bundle_history"
            bundle_dir.mkdir(parents=True)
            entrypoint = bundle_dir / "index.html"
            entrypoint.write_text("<!doctype html><title>Bundled history</title>", encoding="utf-8")
            response_id = "resp_bundle_history"
            conversation_id = "responses_workbench_bundle_history"
            registry_path = root / "artifact_registry.jsonl"
            registry_path.write_text(
                json.dumps(
                    {
                        "kind": "ollmo.artifact_registry_record",
                        "artifact_ref": "bundle:test_history",
                        "artifact": {
                            "type": "bundle",
                            "kind": "response_artifact_bundle",
                            "artifact_ref": "bundle:test_history",
                            "path": str(bundle_dir),
                            "entrypoint": str(entrypoint),
                            "source_response_id": response_id,
                        },
                        "bundle": {
                            "status": "bundled",
                            "bundle_id": "bundle:test_history",
                            "bundle_path": str(bundle_dir),
                            "entrypoint": str(entrypoint),
                            "source_response_id": response_id,
                            "link_check": {"status": "passed", "missing": []},
                        },
                        "source": {"kind": "response_artifact_bundle", "response_id": response_id},
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            write_chat_history(
                conversation_id,
                [{"role": "assistant", "content": "Artifacts are bundled.", "response_id": response_id}],
                history_dir=history_dir,
            )
            _RESPONSE_LOOKUP[response_id] = {
                "id": response_id,
                "status": "completed",
                "lifecycle_state": "completed",
                "expires_at_ts": time.time() + 3600,
                "response_payload": {
                    "id": response_id,
                    "status": "completed",
                    "output_text": "Artifacts are bundled.",
                },
            }

            with (
                patch("ollmo_webserver.CHAT_HISTORY_DIR", history_dir),
                patch("ollmo_webserver.ARTIFACT_REGISTRY_LEDGER", registry_path),
            ):
                response = self.client.get("/api/chat_history", query_string={"instance_id": conversation_id})

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        message = next(item for item in payload["messages"] if item.get("response_id") == response_id)
        self.assertEqual(message["artifact_bundles"][0]["bundle_id"], "bundle:test_history")
        self.assertEqual(message["artifact_bundles"][0]["bundle_path"], str(bundle_dir))

