    def test_late_fill_control_endpoint_cancels_pending_branch(self):
        response_id = "resp_cancel_pending_branch"
        branch = {
            "branch_id": "branch-image-1",
            "phase_id": "phase-2",
            "capability": "image_generation",
            "output_type": "image",
            "status": "pending",
        }
        response_payload = {
            "id": response_id,
            "mode": "chat",
            "status": "completed",
            "output_text": "Image branch is queued.",
            "late_fill": {
                "status": "pending",
                "expected_capability": "image_generation",
                "pending_capabilities": ["image_generation"],
                "pending_branches": [branch],
            },
        }
        _RESPONSE_LOOKUP[response_id] = {
            "id": response_id,
            "message_id": "msg_cancel_pending_branch",
            "instance_id": "chat-1",
            "model_name": "gemma4:e4b",
            "backend": "ollama",
            "capability": "chat",
            "mode": "chat",
            "status": "completed",
            "output_text": response_payload["output_text"],
            "response_payload": response_payload,
            "route_payload": {},
            "expires_at_ts": time.time() + 3600,
        }

        large_reason = "not-needed-bounded-reason-" + ("r" * (9 * 1024 * 1024))
        response = self.client.post(
            f"/api/responses/{response_id}/late_fill/control",
            json={"branch_id": "branch-image-1", "action": "cancel", "reason": large_reason},
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        late_fill = payload["response"]["late_fill"]
        self.assertEqual(late_fill["status"], "cancelled")
        self.assertEqual(late_fill["pending_branches"], [])
        self.assertEqual(late_fill["cancelled_branches"][0]["branch_id"], "branch-image-1")
        self.assertEqual(late_fill["cancelled_branches"][0]["status"], "cancelled")
        self.assertEqual(late_fill["cancelled_branches"][0]["execution_gate"]["action"], "skip")
        self.assertEqual(len(payload["control"]["reason"]), 32 * 1024)
        self.assertTrue(payload["control"]["reason_ref"]["preview_truncated"])
        self.assertEqual(payload["control"]["reason_ref"]["length_chars"], len(large_reason))
        self.assertLessEqual(len(response.data), 8 * 1024 * 1024)

