    def test_graph_closure_review_marks_graph_inadequate_for_missing_second_image(self):
        prompt = 'Describe two funny workshop scenes and then make two images of them.'
        phase_graph = {
            'current_phase_id': 'phase-1',
            'current_phase_capability': 'chat',
            'current_phase_resolution': 'graph_resolved',
            'mode': 'carried_phase_chain',
            'prompt': prompt,
            'prompt_intent': {
                'requests_visual_output': True,
                'text_preparation_before_visual_output': True,
                'requested_visual_output_count': 2,
            },
            'phases': [
                {
                    'phase_id': 'phase-1',
                    'capability': 'chat',
                    'output_type': 'text',
                    'status': 'completed',
                },
                {
                    'phase_id': 'phase-2',
                    'branch_id': 'branch-image_generation-1',
                    'capability': 'image_generation',
                    'output_type': 'image',
                    'depends_on': ['phase-1'],
                    'status': 'completed',
                },
            ],
        }

        review = _build_graph_closure_review(
            'Two image prompts are ready.',
            route_payload={'route_runtime': {'request_phase_graph': phase_graph}},
            request_payload={'ghost_route': True, 'prompt': prompt},
            artifact_payload={
                'output_text': 'Two image prompts are ready.',
                'runtime': {'request_phase_graph': phase_graph},
                'artifacts': [{'type': 'image', 'path': 'artifacts/images/one.png'}],
            },
        )

        self.assertEqual(review['status'], 'pending')
        self.assertEqual(review['reason'], 'graph/IR does not fully cover current user intent')
        adequacy = review['intent_graph_adequacy']
        self.assertEqual(adequacy['status'], 'pending')
        self.assertEqual(adequacy['expected_output_counts'], {'image': 2})
        self.assertEqual(adequacy['graph_output_counts'], {'image': 1})
        missing = next(
            item
            for item in review['checks']
            if item.get('check_kind') == 'intent_graph_adequacy'
        )
        self.assertEqual(missing['output_type'], 'image')
        self.assertEqual(missing['expected_count'], 2)
        self.assertEqual(missing['actual_count'], 1)
        self.assertEqual(missing['missing_count'], 1)
        self.assertEqual(review['counts']['pending'], 1)

