    @patch("ollmo_webserver._invoke_internal_api_json_route")
    @patch("ollmo_webserver._resolve_ghost_auto_route")
    def test_canonical_responses_direct_batch_parallelizes_across_shared_engine_and_preserves_order(
        self,
        mock_resolve_ghost_route,
        mock_invoke,
    ):
        resolve_calls = []

        def resolve_route_side_effect(data, upload=None, excluded_instance_ids=None, **kwargs):
            excluded = list(excluded_instance_ids or [])
            resolve_calls.append(excluded)
            instance_id = "flux-2" if excluded else "flux-1"
            return (
                {
                    "instance_id": instance_id,
                    "instance": {
                        "instance_id": instance_id,
                        "model": f"x/{instance_id}:latest",
                        "backend": "ollama",
                        "capability": "image_generation",
                        "port": 11435 if instance_id == "flux-1" else 11436,
                    },
                    "capability": "image_generation",
                    "route_source": "ghost_carried",
                    "route_reason": "image-generation cue",
                    "route_confidence": 0.92,
                    "route_reuse_last_artifact": False,
                    "route_artifact_path": None,
                    "route_runtime": {
                        "request_phase_graph": {
                            "current_phase_capability": "image_generation",
                            "downstream_branch_ids": [],
                            "prompt_intent": {
                                "requests_visual_output": True,
                                "requested_visual_output_count": 2,
                            },
                        }
                    },
                },
                None,
            )

        started_prompts = []
        started_gate = threading.Event()
        started_lock = threading.Lock()

        def invoke_side_effect(payload, upload=None):
            prompt = str(payload.get("prompt") or "").strip()
            instance_id = str(payload.get("instance_id") or "").strip()
            with started_lock:
                started_prompts.append((prompt, instance_id))
                if len(started_prompts) == 2:
                    started_gate.set()
            self.assertTrue(
                started_gate.wait(0.5),
                "Direct batch branches did not start in parallel before the first one completed.",
            )
            if prompt == "wide dream lake":
                time.sleep(0.05)
            return (
                {
                    "instance_id": instance_id,
                    "capability": "image_generation",
                    "mode": "image_generation",
                    "content": "Image generated.",
                    "saved_image_path": f"/tmp/artifacts/images/{prompt.replace(' ', '-')}.png",
                },
                200,
            )

        mock_resolve_ghost_route.side_effect = resolve_route_side_effect
        mock_invoke.side_effect = invoke_side_effect

        response = self.client.post(
            "/api/responses",
            json={
                "ghost_route": True,
                "prompt": "Generate two surreal dream images.",
                "input": "Generate two surreal dream images.",
                "conversation_id": "responses-workbench",
                "batch_prompts": [
                    "wide dream lake",
                    "tower above clouds",
                ],
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(resolve_calls, [[], ["flux-1"]])
        self.assertEqual(mock_invoke.call_count, 2)
        self.assertEqual(
            started_prompts,
            [
                ("wide dream lake", "flux-1"),
                ("tower above clouds", "flux-2"),
            ],
        )
        self.assertEqual(
            [item["prompt"] for item in payload["results"]],
            ["wide dream lake", "tower above clouds"],
        )
        self.assertEqual(
            [item["batch_index"] for item in payload["artifacts"]],
            [1, 2],
        )
        self.assertEqual(
            [item["batch_index"] for item in payload["outputs"]],
            [1, 2],
        )
        self.assertEqual(
            [item["artifact_ref"] for item in payload["outputs"]],
            [item["artifact_ref"] for item in payload["artifacts"]],
        )

    @patch("ollmo_webserver._invoke_internal_api_json_route")
    @patch("ollmo_webserver._resolve_ghost_auto_route")
    def test_canonical_responses_direct_batch_reuses_instances_after_exhausting_image_candidates(
        self,
        mock_resolve_ghost_route,
        mock_invoke,
    ):
        resolve_calls = []
        invoked = []
        available_instance_ids = ["flux-1", "flux-2"]

        def resolve_route_side_effect(data, upload=None, excluded_instance_ids=None, **kwargs):
            excluded = list(excluded_instance_ids or [])
            resolve_calls.append(excluded)
            instance_id = next(
                (
                    candidate_id
                    for candidate_id in available_instance_ids
                    if candidate_id not in excluded
                ),
                "",
            )
            if not instance_id:
                return (
                    None,
                    "No non-excluded running instance found for capability 'image_generation'.",
                )
            return (
                {
                    "instance_id": instance_id,
                    "instance": {
                        "instance_id": instance_id,
                        "model": f"x/{instance_id}:latest",
                        "backend": "ollama",
                        "capability": "image_generation",
                        "port": 11435 if instance_id == "flux-1" else 11436,
                    },
                    "capability": "image_generation",
                    "route_source": "ghost_carried",
                    "route_reason": "image-generation cue",
                    "route_confidence": 0.92,
                    "route_reuse_last_artifact": False,
                    "route_artifact_path": None,
                    "route_runtime": {
                        "request_phase_graph": {
                            "current_phase_capability": "image_generation",
                            "downstream_branch_ids": [],
                            "prompt_intent": {
                                "requests_visual_output": True,
                                "requested_visual_output_count": 3,
                            },
                        }
                    },
                },
                None,
            )

        def invoke_side_effect(payload, upload=None):
            prompt = str(payload.get("prompt") or "").strip()
            instance_id = str(payload.get("instance_id") or "").strip()
            invoked.append((prompt, instance_id))
            return (
                {
                    "instance_id": instance_id,
                    "capability": "image_generation",
                    "mode": "image_generation",
                    "content": "Image generated.",
                    "saved_image_path": f"/tmp/artifacts/images/{prompt.replace(' ', '-')}.png",
                },
                200,
            )

        mock_resolve_ghost_route.side_effect = resolve_route_side_effect
        mock_invoke.side_effect = invoke_side_effect

        response = self.client.post(
            "/api/responses",
            json={
                "ghost_route": True,
                "prompt": "Generate three surreal dream images.",
                "input": "Generate three surreal dream images.",
                "conversation_id": "responses-workbench",
                "batch_prompts": [
                    "wide dream lake",
                    "tower above clouds",
                    "neon bridge at dusk",
                ],
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(
            resolve_calls,
            [
                [],
                ["flux-1"],
                ["flux-1", "flux-2"],
                [],
            ],
        )
        self.assertEqual(mock_invoke.call_count, 3)
        self.assertEqual(
            [item["prompt"] for item in payload["results"]],
            ["wide dream lake", "tower above clouds", "neon bridge at dusk"],
        )
        self.assertCountEqual(
            invoked,
            [
                ("wide dream lake", "flux-1"),
                ("tower above clouds", "flux-2"),
                ("neon bridge at dusk", "flux-1"),
            ],
        )
        self.assertEqual(
            [item["batch_index"] for item in payload["outputs"]],
            [1, 2, 3],
        )

    @patch("ollmo_webserver._invoke_internal_api_json_route")
    @patch("ollmo_webserver._lookup_instance")
    def test_canonical_responses_direct_batch_serializes_when_pinned_to_one_instance(
        self,
        mock_lookup,
        mock_invoke,
    ):
        mock_lookup.return_value = {
            "instance_id": "flux-1",
            "model": "x/flux2-klein:latest",
            "backend": "ollama",
            "capability": "image_generation",
            "port": 11435,
        }
        in_flight = {"active": 0, "max": 0}
        concurrency_lock = threading.Lock()

        def invoke_side_effect(payload, upload=None):
            with concurrency_lock:
                in_flight["active"] += 1
                in_flight["max"] = max(in_flight["max"], in_flight["active"])
            time.sleep(0.05)
            with concurrency_lock:
                in_flight["active"] -= 1
            prompt = str(payload.get("prompt") or "").strip()
            return (
                {
                    "instance_id": "flux-1",
                    "capability": "image_generation",
                    "mode": "image_generation",
                    "content": "Image generated.",
                    "saved_image_path": f"/tmp/artifacts/images/{prompt.replace(' ', '-')}.png",
                },
                200,
            )

        mock_invoke.side_effect = invoke_side_effect

        response = self.client.post(
            "/api/responses",
            json={
                "instance_id": "flux-1",
                "batch_prompts": [
                    "storm over Zurich",
                    "foggy neon diner",
                ],
            },
        )

        self.assertEqual(response.status_code, 200)
        self.assertEqual(mock_invoke.call_count, 2)
        self.assertEqual(in_flight["max"], 1)

