    @patch("ollmo_webserver._execute_chat_backend_request")
    @patch("ollmo_webserver._resolve_responses_target_instance")
    def test_canonical_responses_text_only_selected_mlx_vlm_rebounds_to_chat_and_falls_back(
        self,
        mock_resolve_target,
        mock_execute,
    ):
        selected_vlm = {
            "instance_id": "mlx-vlm-1",
            "model": "mlx-community/gemma-4-e4b-8bit",
            "backend": "mlx",
            "capability": "vision_analysis",
            "supported_capabilities": ["chat", "vision_analysis"],
            "provider_capabilities": ["chat", "vision_analysis"],
            "backend_package": "mlx_vlm",
            "backend_contract": "mlx_vlm.server",
            "request_model": "/tmp/mlx-gemma4-old",
            "port": 11501,
        }
        fallback_chat = {
            "instance_id": "ollama-chat-1",
            "model": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "supported_capabilities": ["chat"],
            "provider_capabilities": ["chat"],
            "port": 11437,
        }

        def resolve_side_effect(payload, **kwargs):
            if kwargs.get("excluded_instance_ids"):
                self.assertEqual(kwargs["excluded_instance_ids"], ["mlx-vlm-1"])
                self.assertEqual(payload.get("capability"), "chat")
                self.assertNotIn("instance_id", payload)
                return "ollama-chat-1", fallback_chat, "chat", None
            if payload.get("instance_id") == "ollama-chat-1":
                return "ollama-chat-1", fallback_chat, None, None
            return "mlx-vlm-1", selected_vlm, None, None

        def execute_side_effect(**kwargs):
            if kwargs["target_port"] == 11501:
                self.assertEqual(kwargs["capability"], "chat")
                raise requests.exceptions.HTTPError("500 Server Error: Internal Server Error")
            self.assertEqual(kwargs["target_port"], 11437)
            return "Fallback hello."

        mock_resolve_target.side_effect = resolve_side_effect
        mock_execute.side_effect = execute_side_effect

        response = self.client.post(
            "/api/responses",
            json={
                "instance_id": "mlx-vlm-1",
                "capability": "vision_analysis",
                "input": "hi",
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["instance_id"], "ollama-chat-1")
        self.assertEqual(payload["capability"], "chat")
        self.assertEqual(payload["output_text"], "Fallback hello.")
        self.assertEqual(mock_execute.call_count, 2)
        self.assertEqual(mock_resolve_target.call_count, 3)

