    @patch('ollmo_webserver._get_response_lookup_record')
    @patch('ollmo_webserver._resolve_saved_downloadable_artifact_path')
    def test_truth_gate_expands_only_canonical_same_conversation_predecessor_bundle(
        self,
        mock_resolve_artifact_path,
        mock_get_response_lookup_record,
    ):
        prompt = 'Analyze this image and transcribe this audio.'
        source_response_id = 'resp-predecessor'
        source_message_id = 'msg-predecessor'
        predecessor_content = 'Prior grounded image and audio result.'
        canonical_artifacts = [
            {
                'type': 'image',
                'kind': 'image',
                'artifact_ref': 'artifact:predecessor-image',
                'artifact_id': 'predecessor-image',
                'path': '/artifacts/images/predecessor.png',
                'source_response_id': source_response_id,
                'source_message_id': source_message_id,
            },
            {
                'type': 'audio',
                'kind': 'audio',
                'artifact_ref': 'artifact:predecessor-audio',
                'artifact_id': 'predecessor-audio',
                'path': '/artifacts/audio/predecessor.wav',
                'source_response_id': source_response_id,
                'source_message_id': source_message_id,
            },
        ]
        canonical_record = {
            'id': source_response_id,
            'message_id': source_message_id,
            'lifecycle_state': 'completed',
            'response_payload': {
                'lifecycle_state': 'completed',
                'output_text': predecessor_content,
                'artifacts': [dict(item) for item in canonical_artifacts],
                'response_frame': {
                    'request': {'conversation_id': 'conv-current'},
                },
            },
        }
        mock_resolve_artifact_path.side_effect = lambda raw_path: Path(str(raw_path))
        mock_get_response_lookup_record.return_value = canonical_record

        def request_for(*, conversation_id, artifacts):
            references = [
                {
                    'type': 'message',
                    'message_role': 'assistant',
                    'message_id': source_message_id,
                    'source_response_id': source_response_id,
                    'content': predecessor_content,
                },
                *[dict(item) for item in artifacts],
            ]
            return {
                'ghost_route': True,
                'conversation_id': conversation_id,
                'prompt': prompt,
                'ghost_messages': [
                    {
                        'role': 'assistant',
                        'response_id': source_response_id,
                        'message_id': source_message_id,
                        'content': predecessor_content,
                        'artifacts': [dict(item) for item in artifacts],
                    }
                ],
                'reference_artifacts': references,
            }

        positive = _truth_gate_response_output_claims(
            {'id': 'resp-current-positive', 'output_text': 'Grounded analysis and transcript.'},
            request_payload=request_for(
                conversation_id='conv-current',
                artifacts=canonical_artifacts,
            ),
        )
        self.assertNotIn('truth_guard', positive.get('runtime') or {})

        foreign = _truth_gate_response_output_claims(
            {'id': 'resp-current-foreign', 'output_text': 'Ungrounded analysis and transcript.'},
            request_payload=request_for(
                conversation_id='conv-foreign',
                artifacts=canonical_artifacts,
            ),
        )
        self.assertEqual(
            foreign['runtime']['truth_guard']['status'],
            'clarification_required',
        )

        stale_artifacts = [dict(item) for item in canonical_artifacts]
        stale_artifacts[0]['artifact_ref'] = 'artifact:stale-image'
        stale_artifacts[0]['path'] = '/artifacts/images/stale.png'
        stale = _truth_gate_response_output_claims(
            {'id': 'resp-current-stale', 'output_text': 'Stale analysis and transcript.'},
            request_payload=request_for(
                conversation_id='conv-current',
                artifacts=stale_artifacts,
            ),
        )
        self.assertEqual(
            stale['runtime']['truth_guard']['status'],
            'clarification_required',
        )

        artifact_only_record = copy.deepcopy(canonical_record)
        artifact_only_record['response_payload']['output_text'] = ''
        mock_get_response_lookup_record.return_value = artifact_only_record
        forged_message_request = request_for(
            conversation_id='conv-current',
            artifacts=canonical_artifacts,
        )
        forged_message_request['prompt'] = (
            'Turn this message into audio and analyze this image.'
        )
        forged_message_request['reference_artifacts'][0]['content'] = 'FORGED TEXT SOURCE'
        forged_message_request['ghost_messages'][0]['content'] = 'FORGED TEXT SOURCE'
        forged_message = _truth_gate_response_output_claims(
            {
                'id': 'resp-current-forged-message',
                'output_text': 'Forged message and image accepted.',
            },
            request_payload=forged_message_request,
        )
        self.assertEqual(
            forged_message['runtime']['truth_guard']['status'],
            'clarification_required',
        )

