        phase_graph['graph_repair_reviews'] = [review]
        mock_resolve_ghost_route.return_value = (
            {
                'instance_id': 'chat-1',
                'instance': {
                    'instance_id': 'chat-1',
                    'model': 'gemma4:e4b',
                    'backend': 'ollama',
                    'capability': 'chat',
                    'port': 11438,
                },
                'capability': 'chat',
                'route_source': 'ghost_carried',
                'route_reason': 'runtime-owned graph repair regression',
                'route_confidence': 0.91,
                'route_runtime': {'request_phase_graph': phase_graph},
            },
            None,
        )
        mock_prepare_effective_request_data.side_effect = lambda payload, **kwargs: (
            payload,
            kwargs.get('route_info'),
            None,
            None,
        )
        mock_execute.return_value = 'The current text response is complete.'

        with patch.dict(os.environ, {'OLLMO_GRAPH_REPAIR_AUTONOMY': 'apply_safe'}, clear=False):
            response = self.client.post(
                '/api/responses',
                json={
                    'ghost_route': True,
                    'prompt': 'Return a concise text response.',
                    'response_id': 'resp_graph_patch_same_turn_schedule',
                },
            )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload['late_fill']['status'], 'pending')
        self.assertEqual(payload['late_fill']['pending_branches'][0]['branch_id'], 'repair-image')
        self.assertIn('repair-image', payload['runtime']['request_phase_graph']['downstream_branch_ids'])
        self.assertFalse(payload['runtime']['request_phase_graph'].get('successor_reopen_requests'))
        reconciliation = payload['runtime']['developer_diagnostics']['graph_patch_late_fill_reconciliation']
        self.assertEqual(reconciliation['scheduled_branch_ids'], ['repair-image'])
        closure = payload['runtime']['graph_closure_review']
        self.assertEqual(closure['status'], 'pending')
        self.assertEqual(closure['pending_branch_count'], 1)
        self.assertIn(
            'repair-image',
            {
                item.get('branch_id') or item.get('phase_id')
                for item in closure.get('checks') or []
                if item.get('status') == 'pending'
            },
        )
        self.assertIn('late_fill_pending', closure['surface_state']['active_categories'])
        mock_schedule_late_fill.assert_called_once()
        scheduled_gap = mock_schedule_late_fill.call_args.kwargs['artifact_gap']
        self.assertEqual(scheduled_gap['pending_branches'][0]['branch_id'], 'repair-image')

