        self.assertEqual(payload["late_fill"]["status"], "pending")
        self.assertEqual(payload["late_fill"]["code"], "deferred_follow_up_fill")
        self.assertEqual(payload["late_fill"]["trigger"], "execution_planner_deferred_follow_up")
        self.assertEqual(payload["late_fill"]["expected_capability"], "text_to_speech")
        self.assertEqual(payload["late_fill"]["missing_artifact_type"], "audio")
        self.assertEqual(payload["late_fill"]["content_payload"], story_text)
        self.assertEqual(payload["late_fill"]["stage_direction"], "(Reading the story aloud)")
        payload = self._canonical_truth_for_payload(payload)
        self.assertEqual(payload["late_fill"]["content_payload_source"], "stage_direction_prefix")
        output_slots = payload["response_frame"]["planning"]["artifact_flow"]["output_slots"]
        audio_slot = next(slot for slot in output_slots if slot["type"] == "audio")
        self.assertEqual(audio_slot["status"], "pending")
        self.assertEqual(audio_slot["lifecycle"], "deferred_output")
        outputs = payload["outputs"]
        text_output = next(output for output in outputs if output["type"] == "text")
        self.assertEqual(text_output["value"], story_text)
        audio_output = next(output for output in outputs if output["type"] == "audio")
        self.assertEqual(audio_output["status"], "pending")
        mock_schedule_late_fill.assert_called_once()

