    @patch("ollmo_webserver._execute_chat_backend_request")
    @patch("ollmo_webserver._resolve_responses_target_instance")
    @patch("ollmo_webserver._invoke_internal_api_json_route")
    @patch("ollmo_webserver._plan_compound_execution_payload")
    @patch("ollmo_webserver._resolve_ghost_auto_route")
    def test_canonical_responses_applies_translation_follow_up_after_speech_to_text(
        self,
        mock_resolve_ghost_route,
        mock_plan_compound_execution_payload,
        mock_invoke_internal_api_json_route,
        mock_resolve_responses_target_instance,
        mock_execute_chat_backend_request,
    ):
        prompt = "thank you. now please transcribe this audio. then translate it to german AND french"
        mock_resolve_ghost_route.return_value = (
            {
                "instance_id": "whisper-1",
                "instance": {
                    "instance_id": "whisper-1",
                    "model": "mlx-community/whisper-large-v3-mlx",
                    "backend": "mlx",
                    "capability": "speech_to_text",
                    "port": 11505,
                },
                "capability": "speech_to_text",
                "route_source": "ghost_carried",
                "route_reason": "prompt refers to the latest audio artifact",
                "route_confidence": 0.82,
                "route_reuse_last_artifact": True,
                "route_artifact_path": "/tmp/latest-audio.wav",
            },
            None,
        )
        mock_plan_compound_execution_payload.side_effect = (
            lambda payload, route_info: (
                payload,
                {"attempted": False, "applied": False, "reason": "not_a_compound_request"},
            )
        )
        mock_invoke_internal_api_json_route.return_value = (
            {
                "instance_id": "whisper-1",
                "capability": "speech_to_text",
                "mode": "speech_to_text",
                "content": "Petra is a testament to human ingenuity.",
                "saved_text_path": "/tmp/transcript.md",
            },
            200,
        )
        def _resolve_target(payload, **_kwargs):
            requested_capability = str((payload or {}).get("capability") or "").strip()
            if requested_capability == "chat":
                return (
                    "chat-1",
                    {
                        "instance_id": "chat-1",
                        "model": "mlx-community/Qwen3.8-27B-8bit",
                        "backend": "mlx",
                        "capability": "chat",
                        "port": 11437,
                        "reasoning_efforts": ["low", "medium", "xhigh"],
                        "session_controls": {
                            "fields": {
                                "reasoning_effort": {
                                    "options": ["off", "low", "medium", "xhigh"],
                                    "default_value": "xhigh",
                                },
                            },
                        },
                    },
                    None,
                    None,
                )
            return (
                "whisper-1",
                {
                    "instance_id": "whisper-1",
                    "model": "mlx-community/whisper-large-v3-mlx",
                    "backend": "mlx",
                    "capability": "speech_to_text",
                    "port": 11505,
                },
                None,
                None,
            )

        mock_resolve_responses_target_instance.side_effect = _resolve_target
        mock_execute_chat_backend_request.return_value = (
            "Transcript:\nPetra is a testament to human ingenuity.\n\n"
            "German:\nPetra ist ein Zeugnis menschlicher Genialitaet.\n\n"
            "French:\nPetra est un temoignage de l'ingeniosite humaine."
        )

        response = self.client.post(
            "/api/responses",
            json={
                "ghost_route": True,
                "input": prompt,
                "response_id": "resp_stt_translation_follow_up",
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertIn("Transcript:\nPetra is a testament to human ingenuity.", payload["output_text"])
        self.assertIn("German:\nPetra ist ein Zeugnis menschlicher Genialitaet.", payload["output_text"])
        self.assertIn("French:\nPetra est un temoignage de l'ingeniosite humaine.", payload["output_text"])
        payload = self._canonical_truth_for_payload(payload)
        self.assertEqual(
            payload["runtime"]["speech_to_text_translation_follow_up"]["status"],
            "applied",
        )
        self.assertEqual(
            payload["runtime"]["speech_to_text_translation_follow_up"]["target_languages"],
            ["de", "fr"],
        )
        mock_execute_chat_backend_request.assert_called_once()
        self.assertEqual(
            mock_execute_chat_backend_request.call_args.kwargs["max_tokens"],
            512,
        )
        self.assertEqual(
            mock_execute_chat_backend_request.call_args.kwargs["reasoning_effort"],
            "xhigh",
        )

