    def test_iter_ollama_stream_deltas_skips_invalid_chunks(self):
        response = self._FakeStreamResponse([
            '',
            'data: not-json',
            '{"message":{"content":"Hello"},"done":false}',
            '{"message":{"content":" world"},"done":true}',
        ])

        deltas = list(_iter_ollama_stream_deltas(response))

        self.assertEqual(deltas, ['Hello', ' world'])
        self.assertTrue(response.closed)

    def test_iter_ollama_stream_deltas_accepts_byte_chunks(self):
        response = self._FakeStreamResponse([
            b'{"message":{"content":"Hello"},"done":false}',
            b'{"message":{"content":" world"},"done":true}',
        ])

        deltas = list(_iter_ollama_stream_deltas(response))

        self.assertEqual(deltas, ['Hello', ' world'])
        self.assertTrue(response.closed)

    def test_iter_mlx_stream_deltas_skips_invalid_chunks(self):
        response = self._FakeStreamResponse([
            'event: message',
            'data: not-json',
            'data: {"choices":[{"delta":{"content":"Hello"}}]}',
            'data: {"choices":[{"delta":{"content":" world"}}]}',
            'data: [DONE]',
        ])

        deltas = list(_iter_mlx_stream_deltas(response))

        self.assertEqual(deltas, ['Hello', ' world'])
        self.assertTrue(response.closed)

    def test_iter_mlx_stream_deltas_accepts_byte_chunks(self):
        response = self._FakeStreamResponse([
            b'data: {"choices":[{"delta":{"content":"Hello"}}]}',
            b'data: {"choices":[{"delta":{"content":" world"}}]}',
            b'data: [DONE]',
        ])

        deltas = list(_iter_mlx_stream_deltas(response))

        self.assertEqual(deltas, ['Hello', ' world'])
        self.assertTrue(response.closed)

    def test_iter_mlx_stream_deltas_ignores_reasoning_only_chunks(self):
        response = self._FakeStreamResponse([
            'data: {"choices":[{"delta":{"reasoning":"The user is asking..."}}]}',
            'data: {"choices":[{"delta":{"content":"Final answer"}}]}',
            'data: [DONE]',
        ])

        deltas = list(_iter_mlx_stream_deltas(response))

        self.assertEqual(deltas, ['Final answer'])
        self.assertTrue(response.closed)

