    @patch("ollmo_webserver._schedule_response_late_fill", return_value=True)
    @patch("ollmo_webserver._execute_chat_backend_request")
    @patch("ollmo_webserver.record_instance_success")
    @patch("ollmo_webserver.record_instance_activity")
    def test_prepare_stream_buffers_control_envelope_and_emits_only_retry_content(
        self,
        mock_activity,
        mock_success,
        mock_execute_chat_backend_request,
        mock_schedule_late_fill,
    ):
        mock_activity.return_value = ({}, {"readiness": "ready"})
        mock_success.return_value = ({"readiness": "ready"}, {"readiness": "ready"})
        control_envelope = json.dumps(
            {
                "decision_contract": {"status": "ready"},
                "request_ir": {"output_obligations": []},
                "user_facing_response": "I will prepare the audio content next.",
            }
        )
        substantive_text = "Die Glocke klingt einmal durch den stillen Hafen."
        mock_execute_chat_backend_request.return_value = substantive_text

        with patch(
            "ollmo_webserver._open_ollama_chat_stream",
            return_value=(
                self._FakeStreamResponse(
                    [
                        json.dumps({"message": {"content": control_envelope[:40]}}),
                        json.dumps({"message": {"content": control_envelope[40:]}}),
                        '{"done":true}',
                    ]
                ),
                11435,
            ),
        ):
            with app.test_request_context("/api/responses", method="POST"):
                response = _stream_chat_backend_as_responses(
                    instance_id="chat-1",
                    target_port=11435,
                    model_name="gemma4:26b",
                    backend="ollama",
                    capability="chat",
                    messages=[
                        {"role": "user", "content": "Write a story and then read it aloud."}
                    ],
                    request_payload={
                        "input": "Write a story and then read it aloud.",
                    },
                    response_id="resp_prepare_stream_control_retry",
                )

        body = response.get_data(as_text=True)
        self.assertNotIn("I will prepare the audio content next", body)
        self.assertIn(substantive_text, body)
        self.assertEqual(mock_execute_chat_backend_request.call_count, 1)
        retry_messages = mock_execute_chat_backend_request.call_args.kwargs["messages"]
        self.assertIn("phase-output repair", retry_messages[-1]["content"])
        mock_schedule_late_fill.assert_called_once()

        lookup = self.client.get("/api/responses/resp_prepare_stream_control_retry?view=truth")
        self.assertEqual(lookup.status_code, 200)
        payload = lookup.get_json()
        self.assertEqual(payload.get("output_text"), substantive_text, payload)
        self.assertEqual(
            payload["runtime"]["phase_output_acceptance"]["status"],
            "accepted_after_retry",
        )
        self.assertNotIn("I will prepare the audio content next", json.dumps(payload))
        self.assertNotIn(
            "I will prepare the audio content next",
            json.dumps(payload["response_frame"]["output"]),
        )

