        mock_activity.return_value = ({}, {"readiness": "ready"})
        mock_success.return_value = ({"readiness": "ready"}, {"readiness": "ready"})
        control_envelope = json.dumps(
            {
                "decision_contract": {"status": "ready"},
                "request_ir": {"output_obligations": []},
                "user_facing_response": "RAW_STREAM_CONTROL_MARKER",
            }
        )
        mock_execute_chat_backend_request.return_value = control_envelope

        with patch(
            "ollmo_webserver._open_ollama_chat_stream",
            return_value=(
                self._FakeStreamResponse(
                    [
                        json.dumps({"message": {"content": control_envelope}}),
                        '{"done":true}',
                    ]
                ),
                11435,
            ),
        ):
            with app.test_request_context("/api/responses", method="POST"):
                response = _stream_chat_backend_as_responses(
                    instance_id="chat-1",
                    target_port=11435,
                    model_name="gemma4:26b",
                    backend="ollama",
                    capability="chat",
                    messages=[
                        {"role": "user", "content": "Write a story and then read it aloud."}
                    ],
                    request_payload={
                        "input": "Write a story and then read it aloud.",
                    },
                    response_id="resp_prepare_stream_control_blocked",
                )

        body = response.get_data(as_text=True)
        self.assertIn("Downstream materialization is blocked", body)
        self.assertNotIn("RAW_STREAM_CONTROL_MARKER", body)
        mock_schedule_late_fill.assert_not_called()

        lookup = self.client.get("/api/responses/resp_prepare_stream_control_blocked?view=truth")
        payload = lookup.get_json()
        self.assertEqual(payload["lifecycle_state"], "repair_needed")
        self.assertEqual(payload["runtime"]["truth_guard"]["status"], "repair_required")
        self.assertNotIn("RAW_STREAM_CONTROL_MARKER", json.dumps(payload))
        acceptance = payload["runtime"]["phase_output_acceptance"]
        self.assertEqual(acceptance["status"], "repair_required")
        self.assertNotIn("RAW_STREAM_CONTROL_MARKER", json.dumps(acceptance))
        checks = payload["runtime"]["graph_closure_review"]["checks"]
        acceptance_check = next(
            check
            for check in checks
            if check.get("check_kind") == "prepared_substantive_text_accepted"
        )
        self.assertEqual(acceptance_check["status"], "blocked")
        self.assertEqual(acceptance_check["acceptance_status"], "repair_required")
        self.assertEqual(acceptance_check["evidence"], "control_envelope_not_speakable")
        self.assertEqual(acceptance_check["repair_action"], "repair_branch_contract")

