        self.assertEqual(artifact_gap["text_artifact_extension"], "md")
        self.assertEqual(
            [branch["branch_id"] for branch in artifact_gap["pending_branches"]],
            ["branch-text_artifact-1", "branch-text_artifact-2", "branch-text_artifact-3"],
        )

        payload = self.client.get(f"/api/responses/{response_id}?view=truth").get_json()
        self.assertEqual(payload["late_fill"]["status"], "pending")
        self.assertEqual(len(payload["late_fill"]["pending_branches"]), 3)
        output_slots = payload["response_frame"]["planning"]["artifact_flow"]["output_slots"]
        pending_text_artifact_slots = [
            slot
            for slot in output_slots
            if str(slot.get("branch_id") or "").startswith("branch-text_artifact-")
        ]
        self.assertEqual(len(pending_text_artifact_slots), 3)
        self.assertTrue(all(slot["status"] == "pending" for slot in pending_text_artifact_slots))

