    def test_canonical_responses_late_fill_updates_lookup_with_audio_artifact_from_planner_deferred_follow_up(
        self,
        mock_resolve_ghost_route,
        mock_load_running_instances,
        mock_merge_instances,
        mock_execute,
        mock_plan_compound_execution_payload,
        mock_schedule_late_fill,
        mock_invoke,
    ):
        story_text = "A harbor bell rings once through the fog, and the sleeping town remembers its name."
        story_display_text = f"{story_text}\n\n***\n\n**(Reading the story aloud)**"
        mock_resolve_ghost_route.side_effect = [
            (
                {
                    "instance_id": "chat-1",
                    "instance": {
                        "instance_id": "chat-1",
                        "model": "gemma4:e4b",
                        "backend": "ollama",
                        "capability": "chat",
                        "port": 11438,
                    },
                    "capability": "chat",
                    "route_source": "heuristic",
                    "route_reason": "text preparation required before audio output",
                    "route_confidence": 0.86,
                    "route_reuse_last_artifact": False,
                    "route_artifact_path": None,
                },
                None,
            )
        ]
        tts_instance = {
            "instance_id": "tts-1",
            "model": "mlx-community/Qwen3-TTS-12Hz-1.7B-VoiceDesign-bf16",
            "backend": "mlx",
            "capability": "text_to_speech",
            "port": 11507,
            "tts_model_type": "voice_design",
            "session_controls": {
                "enabled": True,
                "fields": {
                    "tts_instruct": {
                        "visible": True,
                        "required": True,
                        "label": "Style / Instruct",
                        "required_message": "VoiceDesign models require a voice description in Style / Instruct.",
                    }
                },
            },
            "runtime_status": {"readiness": "ready", "activity": "idle"},
        }
        mock_load_running_instances.return_value = [tts_instance]
        mock_merge_instances.return_value = [tts_instance]

        def plan_side_effect(payload, *, route_info):
            capability = route_info.get("capability")
            if capability == "chat":
                return (
                    payload,
                    {
                        "attempted": True,
                        "applied": True,
                        "capability": "chat",
                        "reason": "text_preparation_required_before_audio_output",
                        "trigger": "text_first_tts_follow_up",
                        "deferred_capability": "text_to_speech",
                    },
            )

            self.assertEqual(capability, "text_to_speech")
            self.assertEqual(payload["prompt"], story_text)
            self.assertEqual(payload["content_payload"], story_text)
            self.assertEqual(payload["stage_direction"], "(Reading the story aloud)")
            ghost_messages = payload.get("ghost_messages")
            self.assertTrue(isinstance(ghost_messages, list) and ghost_messages)
            self.assertEqual(ghost_messages[-1]["role"], "assistant")
            self.assertEqual(ghost_messages[-1]["content"], story_display_text)
            updated_payload = dict(payload)
            updated_payload["prompt"] = payload["content_payload"]
            updated_payload["instruct"] = "Use a calm, conversational voice."
            return (
                updated_payload,
                {
                    "attempted": True,
                    "applied": True,
                    "capability": "text_to_speech",
                    "planned_prompt": story_text,
                    "applied_fields": ["prompt", "instruct"],
                    "reason": "referenced_reply_readaloud",
                    "trigger": "tts_reference_read",
                },
            )

        mock_plan_compound_execution_payload.side_effect = plan_side_effect
        mock_execute.return_value = story_display_text
        mock_invoke.return_value = (
            {
                "instance_id": "tts-1",
                "capability": "text_to_speech",
                "mode": "text_to_speech",
                "content": "Audio generated.",
                "saved_audio_path": "/tmp/generated/story.wav",
                "lang_code": "en",
                "lang_code_source": "explicit",
                "response_format": "wav",
                "output_format": "wav",
                "tts_audio_integrity_evidence": (
                    _passed_tts_audio_integrity_evidence(
                        story_text,
                        "/tmp/generated/story.wav",
                    )
                ),
            },
            200,
        )

        def run_late_fill(**kwargs):
            _complete_response_late_fill(**kwargs)
            return True

        mock_schedule_late_fill.side_effect = run_late_fill

        response = self.client.post(
            "/api/responses",
            json={
                "ghost_route": True,
                "input": "Write a short mystical story and then give me something I can listen to.",
                "response_id": "resp_late_fill_audio_lookup",
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["late_fill"]["status"], "pending")

        lookup = self.client.get("/api/responses/resp_late_fill_audio_lookup")
        self.assertEqual(lookup.status_code, 200)
        lookup_payload = lookup.get_json()
        self.assertEqual(lookup_payload["status"], "completed")
        self.assertEqual(lookup_payload["late_fill"]["status"], "completed")
        self.assertEqual(lookup_payload["late_fill"]["fill_instance_id"], "tts-1")
        self.assertEqual(lookup_payload["late_fill"]["content_payload"], story_text)
        self.assertEqual(lookup_payload["late_fill"]["stage_direction"], "(Reading the story aloud)")
        self.assertEqual(lookup_payload["saved_audio_path"], "/tmp/generated/story.wav")
        self.assertEqual(lookup_payload["lang_code"], "en")
        self.assertEqual(lookup_payload["response_format"], "wav")
        audio_fill = next(
            item
            for item in lookup_payload["late_fill"]["fill_results"]
            if item["capability"] == "text_to_speech"
        )
        self.assertEqual(audio_fill["lang_code"], "en")
        self.assertEqual(audio_fill["lang_code_source"], "explicit")
        self.assertEqual(audio_fill["response_format"], "wav")
        self.assertEqual(audio_fill["output_format"], "wav")
        output_slots = lookup_payload["response_frame"]["planning"]["artifact_flow"]["output_slots"]
        audio_slot = next(slot for slot in output_slots if slot["type"] == "audio")
        self.assertEqual(audio_slot["status"], "fulfilled")
        infer_payload = mock_invoke.call_args.kwargs["payload"]
        self.assertEqual(infer_payload["prompt"], story_text)
        self.assertEqual(infer_payload["instruct"], "Use a calm, conversational voice.")

