    @patch("ollmo_webserver._prepare_effective_request_data")
    @patch("ollmo_webserver._resolve_late_fill_route")
    def test_complete_response_late_fill_materializes_multiple_downstream_branches(
        self,
        mock_resolve_late_fill_route,
        mock_prepare_effective_request_data,
        _mock_missing_session_controls,
        mock_build_infer_payload,
        mock_invoke_internal_api_json_route,
        _mock_filter_infer_result,
    ):
        response_id = "resp_parallel_follow_ups"
        request_prompt = (
            "Write a short mystical story in 2 short paragraphs, then read it aloud and show it to me as an image."
        )
        story_text = (
            "The lantern garden drifted between two quiet moons.\n\n"
            "Its roots hummed softly through the silver water below."
        )
        phase_graph = build_request_phase_graph(
            request_prompt,
            request_payload={"prompt": request_prompt},
            route_payload={"capability": "chat", "route_source": "ghost_carried"},
        )
        phase_graph["phases"][0]["status"] = "completed"
        barrier = threading.Barrier(2, timeout=0.5)

        def resolve_late_fill_route_side_effect(payload, *, expected_capability, **_kwargs):
            capability = str(expected_capability)
            route_info = {
                "capability": capability,
                "instance_id": f"{capability}-1",
                "route_source": "phase_continuation",
                "route_reason": f"continue into {capability}",
                "instance": {
                    "instance_id": f"{capability}-1",
                    "model": f"{capability}-model",
                    "backend": "ollama",
                    "capability": capability,
                },
            }
            return payload, route_info, None

        def prepare_effective_request_data_side_effect(payload, *, route_info, instance):
            capability = str(route_info.get("capability") or "")
            effective = dict(payload)
            effective["capability"] = capability
            if capability == "image_generation":
                effective["prompt"] = payload.get("artifact_prompt") or story_text
            elif capability == "text_to_speech":
                effective["prompt"] = payload.get("content_payload") or story_text
            return effective, route_info, {}, {}

        def build_infer_payload_side_effect(
            effective_data,
            *,
            route_info,
            instance,
            instance_id,
            backend,
            capability,
            request_model_override,
            upload_present,
        ):
            infer_payload = {
                "capability": capability,
                "prompt": effective_data.get("prompt"),
            }
            return infer_payload, route_info, False, False

        def invoke_internal_api_side_effect(*, payload, upload=None):
            capability = str(payload.get("capability") or "")
            barrier.wait()
            if capability == "text_to_speech":
                return {
                    "mode": "text_to_speech",
                    "saved_audio_path": "/tmp/story.wav",
                    "audio_mimetype": "audio/wav",
                    "tts_audio_integrity_evidence": (
                        _passed_tts_audio_integrity_evidence(
                            str(payload.get("prompt") or ""),
                            "/tmp/story.wav",
                        )
                    ),
                }, 200
            if capability == "image_generation":
                return {
                    "mode": "image_generation",
                    "saved_image_path": "/tmp/story.png",
                    "artifact_id": "image_registry_story",
                    "artifact_ref": "artifact:image_registry_story",
                    "provenance_id": "generated_image_story",
                }, 200
            return {"error": "unexpected capability"}, 400

        mock_resolve_late_fill_route.side_effect = resolve_late_fill_route_side_effect
        mock_prepare_effective_request_data.side_effect = prepare_effective_request_data_side_effect
        mock_build_infer_payload.side_effect = build_infer_payload_side_effect
        mock_invoke_internal_api_json_route.side_effect = invoke_internal_api_side_effect

        response_payload = {
            "id": response_id,
            "mode": "chat",
            "output_text": story_text,
            "status": "completed",
            "artifacts": [],
            "runtime": {
                "request_phase_graph": phase_graph,
            },
            "late_fill": {
                "status": "pending",
                "expected_capability": "text_to_speech",
                "pending_capabilities": ["text_to_speech", "image_generation"],
                "content_payload": story_text,
                "artifact_prompt": story_text,
            },
        }
        source_route_payload = {
            "route_source": "ghost_carried",
            "route_runtime": {
                "request_phase_graph": phase_graph,
            },
        }
        artifact_gap = {
            "trigger": "execution_planner_deferred_follow_up",
            "expected_capability": "text_to_speech",
            "pending_capabilities": ["text_to_speech", "image_generation"],
            "content_payload": story_text,
            "artifact_prompt": story_text,
        }

        with tempfile.TemporaryDirectory() as tmpdir:
            with patch("ollmo_webserver.RESPONSE_FRAMES_DIR", Path(tmpdir)):
                _complete_response_late_fill(
                    response_payload=response_payload,
                    request_payload={"prompt": request_prompt},
                    assistant_message=story_text,
                    artifact_gap=artifact_gap,
                    source_route_payload=source_route_payload,
                )

        lookup_payload = _RESPONSE_LOOKUP[response_id]["response_payload"]
        late_fill = lookup_payload["late_fill"]
        self.assertEqual(late_fill["status"], "completed")
        self.assertEqual(set(late_fill["completed_capabilities"]), {"text_to_speech", "image_generation"})
        self.assertEqual(late_fill["pending_capabilities"], [])
        self.assertEqual(len(late_fill["fill_results"]), 2)
        artifact_types = {item.get("type") for item in lookup_payload.get("artifacts") or []}
        self.assertIn("audio", artifact_types)
        self.assertIn("image", artifact_types)
        fill_by_capability = {
            item["capability"]: item
            for item in late_fill["fill_results"]
        }
        image_fill = fill_by_capability["image_generation"]
        audio_fill = fill_by_capability["text_to_speech"]
        self.assertEqual(image_fill["artifact_ref"], "artifact:image_registry_story")
        self.assertEqual(image_fill["provenance_id"], "generated_image_story")
        self.assertTrue(audio_fill["artifact_id"].startswith("audio_"))
        self.assertEqual(audio_fill["artifact_ref"], f'artifact:{audio_fill["artifact_id"]}')
        self.assertEqual(audio_fill["ref"], audio_fill["artifact_ref"])
        self.assertEqual(audio_fill["artifacts"][0]["artifact_ref"], audio_fill["artifact_ref"])
        self.assertNotIn("provenance_id", audio_fill)
        self.assertNotEqual(audio_fill["artifact_ref"], image_fill["artifact_ref"])
        artifacts_by_path = {
            item["path"]: item
            for item in lookup_payload.get("artifacts") or []
        }
        self.assertEqual(
            artifacts_by_path["/tmp/story.wav"]["artifact_ref"],
            audio_fill["artifact_ref"],
        )
        self.assertNotIn("provenance_id", artifacts_by_path["/tmp/story.wav"])

    @patch("ollmo_webserver._execute_prepared_late_fill_branch")
    @patch("ollmo_webserver._prepare_late_fill_branch_plan")
    def test_runtime_scheduling_guard_avoids_concurrent_image_and_large_chat_helpers(
        self,
        mock_prepare_late_fill_branch_plan,
        mock_execute_prepared_late_fill_branch,
    ):
        response_id = "resp_runtime_scheduling_guard_image_text_files"
        request_prompt = (
            "Create exactly three image assets plus exactly two local files: index.html and styles.css. "
            "The images are a glass observatory exterior, a moss-lit archive hall, and a copper music pool."
        )
        branches = [
            {
                "branch_id": f"branch-image_generation-{index}",
                "phase_id": f"phase-image-{index}",
                "capability": "image_generation",
                "output_type": "image",
                "depends_on": ["phase-1"],
                "queue_index": index,
            }
            for index in range(1, 4)
        ] + [
            {
                "branch_id": "branch-chat-index",
                "phase_id": "phase-index",
                "capability": "chat",
                "output_type": "text",
                "depends_on": ["phase-1"],
                "stage_direction": "materialize_requested_text_artifact",
                "requires_artifact": True,
                "text_artifact_extension": "html",
                "text_artifact_source_name": "index",
                "artifact_request": {
                    "extension": "html",
                    "source": "explicit_filename",
                    "source_name": "index",
                    "target_path": "/tmp/runtime-scheduling-guard/index.html",
                },
            },
            {
                "branch_id": "branch-chat-styles",
                "phase_id": "phase-styles",
                "capability": "chat",
                "output_type": "text",
                "depends_on": ["phase-1"],
                "stage_direction": "materialize_requested_text_artifact",
                "requires_artifact": True,
                "text_artifact_extension": "css",
                "text_artifact_source_name": "styles",
                "artifact_request": {
                    "extension": "css",
                    "source": "explicit_filename",
                    "source_name": "styles",
                    "target_path": "/tmp/runtime-scheduling-guard/styles.css",
                },
            },
        ]
        running: list[tuple[str, str, str]] = []
        executed_branch_ids: list[str] = []
        overlap_violations: list[list[tuple[str, str, str]]] = []
        running_lock = threading.Lock()

        def prepare_plan_side_effect(
            *,
            expected_capability,
            artifact_gap,
            current_payload,
            request_payload,
            assistant_message,
            source_route_payload,
            failed_instance_id,
            excluded_instance_ids=None,
        ):
            branch_id = str(artifact_gap.get("branch_id") or "").strip()
            capability = str(expected_capability or "").strip()
            if capability == "image_generation":
                instance_id = branch_id.replace("branch-", "img-")
                model = "x/z-image-turbo:latest"
            else:
                instance_id = branch_id.replace("branch-", "chat-")
                model = "gemma4:26b"
            return {
                "capability": capability,
                "branch_id": branch_id,
                "phase_id": str(artifact_gap.get("phase_id") or branch_id),
                "route_info": {
                    "capability": capability,
                    "instance_id": instance_id,
                    "route_source": "phase_continuation",
                    "route_reason": f"continue {capability}",
                },
                "instance": {
                    "instance_id": instance_id,
                    "model": model,
                    "backend": "ollama",
                    "capability": capability,
                },
                "effective_data": {
                    "capability": capability,
                    "prompt": artifact_gap.get("artifact_prompt") or artifact_gap.get("content_payload") or request_prompt,
                    "artifact_prompt": artifact_gap.get("artifact_prompt"),
                    "artifact_request": artifact_gap.get("artifact_request"),
                    "text_artifact_extension": artifact_gap.get("text_artifact_extension"),
                    "text_artifact_source_name": artifact_gap.get("text_artifact_source_name"),
                    "text_artifact_requests": artifact_gap.get("text_artifact_requests"),
                },
                "infer_payload": {
                    "capability": capability,
                    "prompt": artifact_gap.get("artifact_prompt") or artifact_gap.get("content_payload") or request_prompt,
                },
                "expose_input_artifacts": False,
            }

        def execute_plan_side_effect(plan):
            capability = str(plan.get("capability") or "").strip()
            branch_id = str(plan.get("branch_id") or "").strip()
            model = str(((plan.get("instance") or {}).get("model") or "")).strip()
            with running_lock:
                executed_branch_ids.append(branch_id)
                running.append((branch_id, capability, model))
                has_image = any(item[1] == "image_generation" for item in running)
                has_large_chat = any(item[1] == "chat" and item[2] == "gemma4:26b" for item in running)
                chat_count = sum(1 for item in running if item[1] == "chat")
                if has_image and (has_large_chat or chat_count > 1):
                    overlap_violations.append(list(running))
            time.sleep(0.04)
            with running_lock:
                running.remove((branch_id, capability, model))
            if capability == "image_generation":
                suffix = branch_id.rsplit("-", 1)[-1]
                image_names = {
                    "1": "glass-observatory-exterior.png",
                    "2": "moss-lit-archive-hall.png",
                    "3": "copper-music-pool.png",
                }
                image_path = Path(f"/tmp/runtime-scheduling-guard/{image_names.get(suffix, f'asset-{suffix}.png')}")
                image_path.parent.mkdir(parents=True, exist_ok=True)
                image_path.write_bytes(b"\x89PNG\r\n\x1a\n")
                return {
                    "capability": capability,
                    "branch_id": branch_id,
                    "phase_id": str(plan.get("phase_id") or branch_id),
                    "route_info": dict(plan.get("route_info") or {}),
                    "instance": dict(plan.get("instance") or {}),
                    "effective_data": dict(plan.get("effective_data") or {}),
                    "infer_result": {
                        "mode": "image_generation",
                        "saved_image_path": str(image_path),
                        "artifacts": [{"type": "image", "path": str(image_path)}],
                    },
                }
            effective_data = plan.get("effective_data") or {}
            requests = [
                dict(item)
                for item in (effective_data.get("text_artifact_requests") or [])
                if isinstance(item, dict)
            ]
            if not requests:
                requests = [
                    {
                        "extension": str(effective_data.get("text_artifact_extension") or "txt").strip(),
                        "source_name": str(effective_data.get("text_artifact_source_name") or branch_id).strip(),
                    }
                ]
            saved_text_artifacts = []
            output_chunks = []
            text_artifacts = []
            for request in requests:
                extension = str(request.get("extension") or "txt").strip()
                source_name = str(request.get("source_name") or f"{branch_id}-{extension}").strip()
                text_path = Path(f"/tmp/runtime-scheduling-guard/{source_name}.{extension}")
                text_path.parent.mkdir(parents=True, exist_ok=True)
                if extension == "html":
                    artifact_text = (
                        "<!doctype html><html><body>"
                        '<link rel="stylesheet" href="/tmp/runtime-scheduling-guard/styles.css">'
                        '<img src="/tmp/runtime-scheduling-guard/glass-observatory-exterior.png" alt="glass observatory exterior">'
                        '<img src="/tmp/runtime-scheduling-guard/moss-lit-archive-hall.png" alt="moss-lit archive hall">'
                        '<img src="/tmp/runtime-scheduling-guard/copper-music-pool.png" alt="copper music pool">'
                        "</body></html>"
                    )
                elif extension == "css":
                    artifact_text = "body { margin: 0; font-family: sans-serif; } img { display: block; max-width: 100%; }"
                else:
                    artifact_text = f"{source_name} artifact saved."
                text_path.write_text(artifact_text, encoding="utf-8")
                output_chunks.append(artifact_text)
                saved_text_artifacts.append(
                    {
                        "path": str(text_path),
                        "text_artifact_request": {"extension": extension, "source_name": source_name},
                    }
                )
                text_artifacts.append(
                    {
                        "type": "text",
                        "path": str(text_path),
                        "name": source_name,
                    }
                )
            return {
                "capability": capability,
                "branch_id": branch_id,
                "phase_id": str(plan.get("phase_id") or branch_id),
                "route_info": dict(plan.get("route_info") or {}),
                "instance": dict(plan.get("instance") or {}),
                "effective_data": dict(plan.get("effective_data") or {}),
                "infer_result": {
                    "mode": "chat",
                    "output_text": "\n\n".join(output_chunks),
                    "saved_text_path": saved_text_artifacts[0]["path"],
                    "saved_text_artifacts": saved_text_artifacts,
                    "text_artifact_request": dict(requests[0]),
                    "text_artifact_requests": requests,
                    "artifacts": text_artifacts,
                },
            }

        mock_prepare_late_fill_branch_plan.side_effect = prepare_plan_side_effect
        mock_execute_prepared_late_fill_branch.side_effect = execute_plan_side_effect
        response_payload = {
            "id": response_id,
            "mode": "chat",
            "status": "completed",
            "output_text": "HTML and CSS draft plus three image slots are ready.",
            "artifacts": [],
            "runtime": {
                "request_phase_graph": {
                    "current_phase_id": "phase-1",
                    "current_phase_resolution": "graph_resolved",
                    "phases": [{"phase_id": "phase-1", "capability": "chat", "status": "completed"}, *branches],
                },
            },
            "late_fill": {
                "status": "pending",
                "expected_capability": "image_generation",
                "pending_branches": list(branches),
                "batch_prompts": [
                    "Cinematic glass observatory exterior at dawn, mountain ridge, reflective panels, architectural photography.",
                    "Moss-lit archive hall with copper shelves, rain-gloss stone, cinematic interior lighting.",
                    "Copper music pool chamber with rippling acoustic sculptures, warm reflections, cinematic composition.",
                ],
            },
        }

        _complete_response_late_fill(
            response_payload=response_payload,
            request_payload={"prompt": request_prompt},
            assistant_message=response_payload["output_text"],
            artifact_gap={
                "trigger": "execution_planner_deferred_follow_up",
                "expected_capability": "image_generation",
                "pending_branches": list(branches),
                "batch_prompts": list(response_payload["late_fill"]["batch_prompts"]),
            },
            source_route_payload={"route_runtime": response_payload["runtime"]},
        )

        self.assertEqual(overlap_violations, [])
        self.assertEqual(
            {
                "branch-image_generation-1",
                "branch-image_generation-2",
                "branch-image_generation-3",
            },
            {branch_id for branch_id in executed_branch_ids if branch_id.startswith("branch-image_generation-")},
        )
        self.assertEqual(
            1,
            sum(branch_id.startswith("coalesced-text-artifacts-") for branch_id in executed_branch_ids),
        )
        late_fill = _RESPONSE_LOOKUP[response_id]["response_payload"]["late_fill"]
        completed_ids = {item.get("branch_id") for item in late_fill.get("completed_branches") or []}
        self.assertEqual({branch["branch_id"] for branch in branches}, completed_ids)
        history = late_fill.get("materialization_concurrency_history")
        self.assertIsInstance(history, list)
        self.assertTrue(history)
        self.assertEqual(late_fill.get("materialization_concurrency_policy"), history[-1])
        self.assertTrue(
            any(
                item.get("distinct_instance_count") == 3
                and item.get("worker_count") == 3
                and item.get("gpu_heavy_guard") == "not_serialized"
                for item in history
            )
        )
        self.assertTrue(
            any(
                item.get("distinct_instance_count") == 1
                and item.get("worker_count") == 1
                and item.get("gpu_heavy_guard") == "not_serialized"
                and {
                    branch_id
                    for branch_ids in (item.get("instance_branch_groups") or {}).values()
                    for branch_id in branch_ids
                }
                == {
                    branch_id
                    for branch_id in executed_branch_ids
                    if branch_id.startswith("coalesced-text-artifacts-")
                }
                for item in history
            )
        )
        self.assertTrue(
            all(item.get("branch_timings") and item.get("prepare_timings") for item in history)
        )

    def test_coalesced_required_text_artifact_materialization_expands_to_original_branches(self):
        def branch_spec(branch_id, phase_id, extension, source_name):
            branch = {
                "branch_id": branch_id,
                "phase_id": phase_id,
                "capability": "chat",
                "output_type": "text",
                "task_id": f"task-{branch_id}",
                "obligation_id": f"obligation-{branch_id}",
                "stage_direction": "materialize_requested_text_artifact",
                "requires_artifact": True,
                "text_artifact_extension": extension,
                "text_artifact_source_name": source_name,
                "artifact_request": {
                    "extension": extension,
                    "source_name": source_name,
                    "source": "explicit_filename",
                },
            }
            return {
                "branch_id": branch_id,
                "phase_id": phase_id,
                "capability": "chat",
                "reservation_group": "chat",
                "branch": branch,
                "prepare_args": {
                    "expected_capability": "chat",
                    "artifact_gap": dict(branch),
                },
            }

        coalesced_specs = _LATE_FILL_RUNTIME._coalesce_required_text_artifact_branch_specs(
            [
                branch_spec("branch-chat-index", "phase-index", "html", "index"),
                branch_spec(
                    "branch-chat-configurator",
                    "phase-configurator",
                    "html",
                    "configurator",
                ),
                branch_spec("branch-chat-styles", "phase-styles", "css", "styles"),
            ]
        )
        self.assertEqual(len(coalesced_specs), 1)
        coalesced_spec = coalesced_specs[0]
        self.assertTrue(coalesced_spec["coalesced_text_artifact_wave"])
        self.assertEqual(
            [item["branch_id"] for item in coalesced_spec["coalesced_text_artifact_branches"]],
            [
                "branch-chat-index",
                "branch-chat-configurator",
                "branch-chat-styles",
            ],
        )

        with tempfile.TemporaryDirectory() as tmpdir:
            html_path = Path(tmpdir) / "index.html"
            configurator_path = Path(tmpdir) / "configurator.html"
            css_path = Path(tmpdir) / "styles.css"
            html_path.write_text("<!doctype html><h1>Hello</h1>", encoding="utf-8")
            configurator_path.write_text(
                "<!doctype html><h1>Configure</h1>",
                encoding="utf-8",
            )
            css_path.write_text("body { color: red; }", encoding="utf-8")
            coalesced_branch_id = coalesced_spec["branch_id"]
            expanded = _LATE_FILL_RUNTIME._expand_coalesced_text_artifact_materialization(
                {
                    "prepared_branch_plans": [
                        {
                            "branch_id": coalesced_branch_id,
                            "phase_id": coalesced_branch_id,
                            "capability": "chat",
                            "branch": coalesced_spec,
                        }
                    ],
                    "branch_results": {
                        coalesced_branch_id: {
                            "branch_id": coalesced_branch_id,
                            "phase_id": coalesced_branch_id,
                            "capability": "chat",
                            "infer_result": {
                                "mode": "chat",
                                "saved_text_path": str(html_path),
                                "saved_text_artifacts": [
                                    {
                                        "path": str(html_path),
                                        "text_artifact_request": {
                                            "extension": "html",
                                            "source_name": "index",
                                        },
                                    },
                                    {
                                        "path": str(configurator_path),
                                        "text_artifact_request": {
                                            "extension": "html",
                                            "source_name": "configurator",
                                        },
                                    },
                                    {
                                        "path": str(css_path),
                                        "text_artifact_request": {
                                            "extension": "css",
                                            "source_name": "styles",
                                        },
                                    },
                                ],
                            },
                        }
                    },
                    "branch_errors": {},
                }
            )

        self.assertEqual(
            set(expanded["branch_results"]),
            {
                "branch-chat-index",
                "branch-chat-configurator",
                "branch-chat-styles",
            },
        )
        self.assertEqual(
            [item["branch_id"] for item in expanded["prepared_branch_plans"]],
            [
                "branch-chat-index",
                "branch-chat-configurator",
                "branch-chat-styles",
            ],
        )
        self.assertEqual(
            expanded["branch_results"]["branch-chat-index"]["infer_result"]["saved_text_path"],
            str(html_path),
        )
        self.assertEqual(
            expanded["branch_results"]["branch-chat-configurator"][
                "infer_result"
            ]["saved_text_path"],
            str(configurator_path),
        )
        self.assertEqual(
            expanded["branch_results"]["branch-chat-styles"]["infer_result"]["saved_text_path"],
            str(css_path),
        )
        for branch_id in (
            "branch-chat-index",
            "branch-chat-configurator",
            "branch-chat-styles",
        ):
            contract = expanded["branch_results"][branch_id]["execution_contract"]
            self.assertEqual(contract["branch_id"], branch_id)
            self.assertEqual(contract["workload_task_ref"]["task_id"], f"task-{branch_id}")
            self.assertEqual(
                contract["output_obligation_ref"]["obligation_id"],
                f"obligation-{branch_id}",
            )

        blocked_expanded = (
            _LATE_FILL_RUNTIME._expand_coalesced_text_artifact_materialization(
                {
                    'prepared_branch_plans': [
                        {
                            'branch_id': coalesced_branch_id,
                            'phase_id': coalesced_branch_id,
                            'capability': 'chat',
                            'branch': coalesced_spec,
                        }
                    ],
                    'branch_results': {
                        coalesced_branch_id: {
                            'branch_id': coalesced_branch_id,
                            'capability': 'chat',
                            'infer_result': {
                                'external_provider_block': {
                                    'code': 'EXTERNAL_PROVIDER_BLOCKED',
                                    'reason': 'Bounded provider block.',
                                }
                            },
                        }
                    },
                    'branch_errors': {},
                }
            )
        )
        self.assertEqual(blocked_expanded['branch_errors'], {})
        self.assertEqual(
            set(blocked_expanded['branch_results']),
            {
                'branch-chat-index',
                'branch-chat-configurator',
                'branch-chat-styles',
            },
        )
        self.assertTrue(
            all(
                item['infer_result']['external_provider_block']['code']
                == 'EXTERNAL_PROVIDER_BLOCKED'
                for item in blocked_expanded['branch_results'].values()
            )
        )

    def test_text_recovery_authority_survives_normalization_and_disables_coalescing(
        self,
    ):
        raw_recovery_branch = {
            'branch_id': 'branch-chat-recovery',
            'phase_id': 'phase-chat-recovery',
            'capability': 'chat',
            'output_type': 'text',
            'stage_direction': 'materialize_requested_text_artifact',
            'requires_artifact': True,
            'text_artifact_extension': 'html',
            'text_artifact_source_name': 'index',
            'artifact_request': {
                'extension': 'html',
                'source_name': 'index',
            },
            'exclude_instance_ids': ['chat-failed'],
            'auto_execute': True,
            'repair_work_available': True,
            'auto_executable_repair_retry_count': 1,
            'auto_executable_repair_max_attempts': 3,
            'recovery_state': {
                'kind': 'ollmo.late_fill_recovery_state',
                'status': 'attempting',
                'failed_instance_id': 'chat-failed',
                'exclude_instance_ids': ['chat-failed'],
            },
        }
        normalized = _normalize_late_fill_branches(
            [raw_recovery_branch]
        )[0]
        self.assertEqual(
            normalized['excluded_instance_ids'],
            ['chat-failed'],
        )
        self.assertTrue(normalized['auto_execute'])
        self.assertTrue(normalized['repair_work_available'])
        self.assertEqual(
            normalized['auto_executable_repair_retry_count'],
            1,
        )
        self.assertEqual(
            normalized['auto_executable_repair_max_attempts'],
            3,
        )
        normalized_image = _normalize_late_fill_branches(
            [
                {
                    'branch_id': 'branch-image-recovery',
                    'capability': 'image_generation',
                    'autoExecute': True,
                    'repairWorkAvailable': False,
                    'autoExecutableRepairRetryCount': 1,
                    'autoExecutableRepairMaxAttempts': 2,
                }
            ]
        )[0]
        self.assertTrue(normalized_image['auto_execute'])
        self.assertFalse(normalized_image['repair_work_available'])
        self.assertEqual(
            normalized_image['auto_executable_repair_retry_count'],
            1,
        )
        self.assertEqual(
            normalized_image['auto_executable_repair_max_attempts'],
            2,
        )

        def branch_spec(branch):
            return {
                'branch_id': branch['branch_id'],
                'phase_id': branch['phase_id'],
                'capability': 'chat',
                'reservation_group': 'chat',
                'branch': branch,
                'prepare_args': {
                    'expected_capability': 'chat',
                    'artifact_gap': dict(branch),
                },
            }

        fresh_branch = {
            **raw_recovery_branch,
            'branch_id': 'branch-chat-fresh',
            'phase_id': 'phase-chat-fresh',
            'text_artifact_source_name': 'configurator',
            'artifact_request': {
                'extension': 'html',
                'source_name': 'configurator',
            },
        }
        for key in (
            'exclude_instance_ids',
            'auto_execute',
            'repair_work_available',
            'auto_executable_repair_retry_count',
            'auto_executable_repair_max_attempts',
            'recovery_state',
        ):
            fresh_branch.pop(key, None)
        coalesced = (
            _LATE_FILL_RUNTIME._coalesce_required_text_artifact_branch_specs(
                [branch_spec(normalized), branch_spec(fresh_branch)]
            )
        )
        self.assertEqual(len(coalesced), 2)
        self.assertFalse(
            any(
                item.get('coalesced_text_artifact_wave') is True
                for item in coalesced
            )
        )

