    def test_late_fill_branch_progress_updates_response_lookup_before_wave_terminal(self):
        response_id = "resp_live_branch_progress"
        prompt = "Generate two image artifacts."
        branches = [
            {
                "branch_id": "branch-image-1",
                "phase_id": "phase-image-1",
                "capability": "image_generation",
                "output_type": "image",
                "stage_direction": "materialize_image_artifact",
                "artifact_prompt": "Generate image artifact 1.",
            },
            {
                "branch_id": "branch-image-2",
                "phase_id": "phase-image-2",
                "capability": "image_generation",
                "output_type": "image",
                "stage_direction": "materialize_image_artifact",
                "artifact_prompt": "Generate image artifact 2.",
            },
        ]
        response_payload = {
            "id": response_id,
            "mode": "chat",
            "status": "completed",
            "output_text": "Image generation is running.",
            "runtime": {
                "request_phase_graph": {
                    "current_phase_id": "phase-1",
                    "current_phase_resolution": "graph_resolved",
                    "phases": [
                        {"phase_id": "phase-1", "capability": "chat", "status": "completed"},
                        *branches,
                    ],
                },
            },
            "late_fill": {
                "status": "pending",
                "expected_capability": "image_generation",
                "pending_branches": list(branches),
            },
        }
        live_snapshots = []

        def execute_materialization_branches(_branch_specs, **kwargs):
            self.assertTrue(kwargs.get("async_branch_progress"))
            kwargs["on_branch_progress"](
                {
                    "branch_id": "branch-image-1",
                    "phase_id": "phase-image-1",
                    "capability": "image_generation",
                    "status": "completed",
                    "progress_stage": "branch_execution",
                    "instance_id": "img-1",
                    "timing": {"elapsed_ms": 12.5},
                }
            )
            live_payload = _RESPONSE_LOOKUP[response_id]["response_payload"]
            live_late_fill = live_payload["late_fill"]
            live_status = _build_response_status_lookup_payload(_RESPONSE_LOOKUP[response_id])
            live_snapshots.append(
                {
                    "late_fill": live_late_fill,
                    "status_lookup": live_status,
                }
            )
            return {
                "branch_results": {
                    "branch-image-1": {
                        "route_info": {"instance_id": "img-1"},
                        "instance": {"model": "image-model", "backend": "local"},
                        "infer_result": {
                            "mode": "image_generation",
                            "saved_image_path": "/tmp/branch-image-1.png",
                        },
                    },
                    "branch-image-2": {
                        "route_info": {"instance_id": "img-2"},
                        "instance": {"model": "image-model", "backend": "local"},
                        "infer_result": {
                            "mode": "image_generation",
                            "saved_image_path": "/tmp/branch-image-2.png",
                        },
                    },
                },
                "branch_errors": {},
                "prepared_branch_plans": [],
                "concurrency_policy": {"scheduler": "test"},
            }

        with patch.object(
            _LATE_FILL_RUNTIME,
            "execute_materialization_branches",
            side_effect=execute_materialization_branches,
        ):
            _complete_response_late_fill(
                response_payload=response_payload,
                request_payload={"prompt": prompt},
                assistant_message=response_payload["output_text"],
                artifact_gap={
                    "expected_capability": "image_generation",
                    "pending_branches": list(branches),
                },
                source_route_payload={"route_runtime": response_payload["runtime"]},
            )

        self.assertTrue(live_snapshots)
        live_late_fill = live_snapshots[0]["late_fill"]
        self.assertEqual(live_late_fill["status"], "running")
        self.assertEqual(
            [item["branch_id"] for item in live_late_fill.get("branch_progress") or []],
            ["branch-image-1"],
        )
        self.assertEqual(
            [item["branch_id"] for item in live_late_fill.get("active_branches") or []],
            ["branch-image-2"],
        )
        self.assertNotIn("final_materialization_contract_status", live_late_fill)
        compact_late_fill = live_snapshots[0]["status_lookup"]["late_fill"]
        self.assertEqual(compact_late_fill["branch_progress_count"], 1)
        self.assertEqual(compact_late_fill["branch_progress"][0]["branch_id"], "branch-image-1")
        self.assertEqual(compact_late_fill["branch_progress_status_counts"], {"completed": 1})
        terminal_late_fill = _RESPONSE_LOOKUP[response_id]["response_payload"]["late_fill"]
        self.assertNotIn("branch_progress", terminal_late_fill)
        self.assertEqual(
            {item["branch_id"] for item in terminal_late_fill.get("completed_branches") or []},
            {"branch-image-1", "branch-image-2"},
        )

    def test_coalesced_required_text_artifact_subset_leaves_repair_branch_separate(self):
        def branch_spec(branch_id, phase_id, extension, source_name):
            branch = {
                "branch_id": branch_id,
                "phase_id": phase_id,
                "capability": "chat",
                "output_type": "text",
                "stage_direction": "materialize_requested_text_artifact",
                "requires_artifact": True,
                "text_artifact_extension": extension,
                "text_artifact_source_name": source_name,
                "artifact_request": {
                    "extension": extension,
                    "source_name": source_name,
                    "source": "explicit_filename",
                },
            }
            return {
                "branch_id": branch_id,
                "phase_id": phase_id,
                "capability": "chat",
                "reservation_group": "chat",
                "branch": branch,
                "prepare_args": {
                    "expected_capability": "chat",
                    "artifact_gap": dict(branch),
                },
            }

        repair_branch = {
            "branch_id": "repair-chat",
            "phase_id": "repair-chat",
            "capability": "chat",
            "reservation_group": "chat",
            "branch": {
                "branch_id": "repair-chat",
                "phase_id": "repair-chat",
                "capability": "chat",
                "output_type": "text",
                "stage_direction": "repair_terminal_response",
            },
            "prepare_args": {
                "expected_capability": "chat",
                "artifact_gap": {
                    "branch_id": "repair-chat",
                    "phase_id": "repair-chat",
                    "stage_direction": "repair_terminal_response",
                },
            },
        }

        coalesced_specs = _LATE_FILL_RUNTIME._coalesce_required_text_artifact_branch_specs(
            [
                branch_spec("branch-chat-index", "phase-index", "html", "index"),
                branch_spec("branch-chat-styles", "phase-styles", "css", "styles"),
                repair_branch,
            ]
        )

        self.assertEqual(len(coalesced_specs), 2)
        self.assertTrue(coalesced_specs[0]["coalesced_text_artifact_wave"])
        self.assertEqual(coalesced_specs[1]["branch_id"], "repair-chat")
        self.assertEqual(
            [item["branch_id"] for item in coalesced_specs[0]["coalesced_text_artifact_branches"]],
            ["branch-chat-index", "branch-chat-styles"],
        )

