    @patch("ollmo_webserver._prepare_late_fill_branch_plan")
    def test_text_artifact_persistence_required_branch_without_saved_path_is_repairable(
        self,
        mock_prepare_late_fill_branch_plan,
        mock_execute_prepared_late_fill_branch,
    ):
        response_id = "resp_text_artifact_persistence_missing_saved_path"
        request_prompt = "Create exactly one local file artifact: index.html."
        branch = {
            "branch_id": "branch-text_artifact-1",
            "phase_id": "phase-2",
            "capability": "chat",
            "output_type": "text",
            "depends_on": ["phase-1"],
            "stage_direction": "materialize_requested_text_artifact",
            "requires_artifact": True,
            "text_artifact_extension": "html",
            "text_artifact_source_name": "index",
            "artifact_request": {
                "extension": "html",
                "source": "explicit_filename",
                "source_name": "index",
            },
        }
        phase_graph = {
            "current_phase_id": "phase-1",
            "current_phase_resolution": "graph_resolved",
            "phases": [
                {"phase_id": "phase-1", "capability": "chat", "status": "completed"},
                branch,
            ],
        }

        def prepare_plan_side_effect(
            *,
            expected_capability,
            artifact_gap,
            current_payload,
            request_payload,
            assistant_message,
            source_route_payload,
            failed_instance_id,
            excluded_instance_ids=None,
        ):
            return {
                "capability": expected_capability,
                "branch_id": artifact_gap.get("branch_id"),
                "phase_id": artifact_gap.get("phase_id"),
                "route_info": {
                    "capability": expected_capability,
                    "instance_id": "chat-1",
                    "route_source": "phase_continuation",
                },
                "instance": {
                    "instance_id": "chat-1",
                    "model": "gemma4:26b",
                    "backend": "ollama",
                    "capability": "chat",
                },
                "effective_data": {
                    "capability": expected_capability,
                    "prompt": artifact_gap.get("content_payload") or request_prompt,
                    "artifact_request": artifact_gap.get("artifact_request"),
                    "text_artifact_extension": artifact_gap.get("text_artifact_extension"),
                    "text_artifact_source_name": artifact_gap.get("text_artifact_source_name"),
                },
                "infer_payload": {"capability": expected_capability, "prompt": request_prompt},
                "expose_input_artifacts": False,
            }

        def execute_plan_side_effect(plan):
            return {
                "capability": "chat",
                "branch_id": "branch-text_artifact-1",
                "phase_id": "phase-2",
                "route_info": dict(plan.get("route_info") or {}),
                "instance": dict(plan.get("instance") or {}),
                "effective_data": dict(plan.get("effective_data") or {}),
                "infer_result": {
                    "mode": "chat",
                    "output_text": "<!doctype html><h1>Hello</h1>",
                    "text_artifact_extension": "html",
                    "text_artifact_source_name": "index",
                },
            }

        mock_prepare_late_fill_branch_plan.side_effect = prepare_plan_side_effect
        mock_execute_prepared_late_fill_branch.side_effect = execute_plan_side_effect
        response_payload = {
            "id": response_id,
            "mode": "chat",
            "status": "completed",
            "output_text": "HTML file payload is ready.",
            "runtime": {"request_phase_graph": phase_graph},
            "late_fill": {
                "status": "pending",
                "expected_capability": "chat",
                "pending_branches": [dict(branch)],
            },
        }

        _complete_response_late_fill(
            response_payload=response_payload,
            request_payload={"ghost_route": True, "prompt": request_prompt},
            assistant_message=response_payload["output_text"],
            artifact_gap={
                "trigger": "execution_planner_deferred_follow_up",
                "expected_capability": "chat",
                "pending_branches": [dict(branch)],
            },
            source_route_payload={"route_runtime": {"request_phase_graph": phase_graph}},
        )

        lookup_payload = _RESPONSE_LOOKUP[response_id]["response_payload"]
        late_fill = lookup_payload["late_fill"]
        completed_ids = [item.get("branch_id") for item in late_fill.get("completed_branches") or []]
        failed = late_fill.get("failed_branches") or []

        self.assertNotIn("branch-text_artifact-1", completed_ids)
        self.assertEqual([item.get("branch_id") for item in failed], ["branch-text_artifact-1"])
        self.assertEqual(failed[0]["error"]["code"], "TEXT_ARTIFACT_NOT_PERSISTED")
        self.assertTrue(failed[0]["recovery_context"]["can_retry"])

