    def test_prepared_manifest_structural_hero_asset_expands_counted_image_branches(self):
        manifest_items = [
            '1. **hero-bg.jpg**: A panoramic sunny dog park hero background with multiple happy pets, '
            'vibrant landing-page photography.',
        ]
        manifest_items.extend(
            f'{index + 1}. **selfie-{index}.jpg**: Ultra realistic animal selfie number {index}, '
            'curiously close to a wide-angle camera lens with cinematic lighting.'
            for index in range(1, 17)
        )
        output_text = (
            '### image_generation_manifest (for downstream phase)\n\n'
            '*Note to Image Generation Phase: Generate these image assets for the landing page.*\n\n'
            + '\n'.join(manifest_items)
        )
        image_phases = [
            {
                "phase_id": f"phase-{index + 1}",
                "branch_id": f"branch-image_generation-{index}",
                "obligation_id": f"obligation-phase-{index + 1}",
                "capability": "image_generation",
                "output_type": "image",
                "status": "pending",
                "depends_on": ["phase-1"],
                "queue_index": index,
            }
            for index in range(1, 17)
        ]
        response_payload = {
            "id": "resp_prepared_manifest_structural_hero_expands_counted_images",
            "mode": "chat",
            "output_text": output_text,
            "status": "completed",
            "artifacts": [],
            "runtime": {
                "request_phase_graph": {
                    "current_phase_id": "phase-1",
                    "current_phase_resolution": "graph_resolved",
                    "prompt_intent": {
                        "requests_visual_output": True,
                        "requested_visual_output_count": 16,
                    },
                    "phases": [
                        {"phase_id": "phase-1", "capability": "chat", "status": "completed"},
                        *image_phases,
                    ],
                },
            },
        }
        source_route_payload = {
            "route_source": "ghost_carried",
            "route_runtime": response_payload["runtime"],
        }

        artifact_gap = _build_pre_freeze_closure_review_gap(
            output_text,
            route_payload=source_route_payload,
            request_payload={"prompt": "Create a pet landing page with sixteen animal selfies."},
            artifact_payload=response_payload,
        )

        self.assertIsNotNone(artifact_gap)
        self.assertEqual(len(artifact_gap["batch_prompts"]), 17)
        self.assertEqual(len(artifact_gap["pending_branches"]), 17)
        self.assertEqual(
            artifact_gap["prepared_image_prompt_branch_expansion"]["added_branch_count"],
            1,
        )
        self.assertEqual(
            artifact_gap["prepared_image_prompt_branch_expansion"]["prepared_prompt_count"],
            17,
        )
        self.assertEqual(artifact_gap["pending_branches"][-1]["queue_index"], 17)
        self.assertEqual(
            artifact_gap["batch_prompts"][0],
            'A panoramic sunny dog park hero background with multiple happy pets, '
            'vibrant landing-page photography.',
        )
        self.assertNotIn('hero-bg.jpg', artifact_gap["batch_prompts"][0])

