    def test_late_fill_image_batch_prompt_normalization_strips_social_manifest_records(self):
        normalized = _LATE_FILL_RUNTIME._normalize_late_fill_image_batch_prompts(
            [
                '@Sloth_Slowmo` | "Nap time in Costa Rica" | Soft bokeh, dappled sunlight through leaves, cinematic jungle atmosphere.',
                '@Toucan_Toni` | "Morning breakfast in the Amazon" | Extreme macro, vibrant tropical colors, shallow depth of field, raindrops on beak.',
                '@Orchid_Orangutan` | "Swingin through Borneo" | Soft forest light, motion blur on edges, heavy foliage depth.',
                '@Lemur_Lens` | "Big eyes, big dreams, Madagascar" | Soft focus background, cute eye-reflections, warm sunbeams. **Category: Deep Blue Wonders',
            ],
            expected_count=4,
            request_payload={
                "prompt": (
                    'Build the ultimate "Petsie Global Snout Gallery" with exactly 48 distinct image assets. '
                    'For each image, invent a username, location-specific caption, and distinct visual style.'
                )
            },
        )

        self.assertEqual(
            normalized,
            [
                'Sloth Slowmo, Soft bokeh, dappled sunlight through leaves, cinematic jungle atmosphere.',
                'Toucan Toni, Extreme macro, vibrant tropical colors, shallow depth of field, raindrops on beak.',
                'Orchid Orangutan, Soft forest light, motion blur on edges, heavy foliage depth.',
                'Lemur Lens, Soft focus background, cute eye-reflections, warm sunbeams.',
            ],
        )
        for prompt in normalized:
            self.assertNotIn('@', prompt)
            self.assertNotIn('|', prompt)
            self.assertNotIn('`', prompt)
            self.assertNotIn('"', prompt)
            self.assertNotIn('Category', prompt)

    def test_late_fill_image_batch_prompt_normalization_uses_request_requirements_for_weak_labels(self):
        normalized = _LATE_FILL_RUNTIME._normalize_late_fill_image_batch_prompts(
            [
                "Interior Telescope Detail",
                "Guest Lounge Interior",
                "Cinematic wide-angle architectural photography of Nocturne Atlas observatory at dusk, snow capped mountain, violet sky, warm dome light.",
            ],
            expected_count=3,
            request_payload={
                "prompt": (
                    'Build a cinematic one-page landing page for a realistic mountain observatory called "Nocturne Atlas".\n'
                    "The images should be:\n"
                    "1. A wide hero exterior at dusk\n"
                    "2. A detailed interior telescope scene\n"
                    "3. A quiet guest lounge with mountain light\n"
                )
            },
        )

        self.assertEqual(
            normalized,
            [
                "A wide hero exterior at dusk",
                "A detailed interior telescope scene",
                "A quiet guest lounge with mountain light",
            ],
        )

