        message = next(item for item in payload["messages"] if item.get("response_id") == response_id)
        self.assertEqual(message["late_fill"]["status"], "partial_failed")
        stt_slot = next(slot for slot in message["output_slots"] if slot.get("branch_id") == "branch-speech_to_text-1")
        self.assertEqual(stt_slot["status"], "blocked")
        self.assertEqual(stt_slot["error_ref"]["code"], "ORPHANED_RETRY_ATTEMPT")
        self.assertTrue(stt_slot["recovery_context"]["can_retry"])
        stt_branch = next(
            branch for branch in message["output_branches"]
            if branch.get("branch_id") == "branch-speech_to_text-1"
        )
        self.assertEqual(stt_branch["status"], "blocked")
        self.assertTrue(stt_branch["recovery_context"]["can_retry"])

