    def test_response_lookup_refreshes_stale_live_record_from_newer_frame_without_restart(self):
        response_id = "resp_lookup_live_frame_refresh"
        text_slot = {
            "slot_id": "slot-text-1",
            "type": "text",
            "status": "fulfilled",
            "value": "Four prompts ready.",
        }
        pending_image_slots = [
            {
                "slot_id": f"slot-image-{index}",
                "branch_id": f"branch-image-{index}",
                "type": "image",
                "status": "pending",
                "placeholder_ref": f"placeholder:image:{index}",
            }
            for index in range(1, 5)
        ]
        image_artifacts = [
            {
                "type": "image",
                "kind": "image",
                "path": f"/tmp/animal-selfie-{index}.png",
                "artifact_ref": f"artifact:image_{index}",
                "ref": f"artifact:image_{index}",
                "prompt": f"Animal selfie {index}",
            }
            for index in range(1, 5)
        ]
        fulfilled_image_slots = [
            {
                **pending_slot,
                "status": "fulfilled",
                "artifact_ref": artifact["artifact_ref"],
                "path": artifact["path"],
            }
            for pending_slot, artifact in zip(pending_image_slots, image_artifacts)
        ]

        with tempfile.TemporaryDirectory() as tmpdir:
            frames_dir = Path(tmpdir)
            persist_response_frame(
                build_response_frame(
                    {
                        "id": response_id,
                        "object": "response",
                        "status": "completed",
                        "lifecycle_state": "late_fill_running",
                        "mode": "chat",
                        "model": "gemma4:26b",
                        "backend": "ollama",
                        "capability": "chat",
                        "output_text": "Four prompts ready.",
                        "output_slots": [text_slot, *pending_image_slots],
                        "late_fill": {"status": "running", "pending_branch_count": 4},
                    },
                    request_payload={"prompt": "create four images"},
                ),
                frames_dir=frames_dir,
            )
            stale_payload = load_latest_response_state(response_id, frames_dir=frames_dir)["response_payload"]
            persist_response_frame(
                build_response_frame(
                    {
                        "id": response_id,
                        "object": "response",
                        "status": "completed",
                        "lifecycle_state": "completed",
                        "mode": "chat",
                        "model": "gemma4:26b",
                        "backend": "ollama",
                        "capability": "chat",
                        "output_text": "Four prompts ready.",
                        "artifacts": image_artifacts,
                        "output_slots": [text_slot, *fulfilled_image_slots],
                        "late_fill": {
                            "status": "completed",
                            "completed_branch_count": 4,
                            "completed_capabilities": ["image_generation"],
                        },
                    },
                    request_payload={"prompt": "create four images"},
                ),
                frames_dir=frames_dir,
            )
            latest_payload = load_latest_response_state(response_id, frames_dir=frames_dir)["response_payload"]
            self.assertGreater(
                latest_payload["response_frame"]["frame_sequence"],
                stale_payload["response_frame"]["frame_sequence"],
            )
            _RESPONSE_LOOKUP[response_id] = {
                "id": response_id,
                "message_id": "msg_live_frame_refresh",
                "instance_id": "chat-1",
                "model_name": "gemma4:26b",
                "backend": "ollama",
                "capability": "chat",
                "mode": "chat",
                "status": "completed",
                "lifecycle_state": "late_fill_running",
                "output_text": "Four prompts ready.",
                "response_payload": stale_payload,
                "route_payload": {},
                "created_at": "2026-06-10T20:30:00Z",
                "updated_at": "2026-06-10T20:30:00Z",
                "expires_at_ts": time.time() + 60,
            }

            with patch("ollmo_webserver.RESPONSE_FRAMES_DIR", frames_dir):
                response = self.client.get(f"/api/responses/{response_id}?view=ui")
                status_response = self.client.get(f"/api/responses/{response_id}?view=status")

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(len(payload["artifacts"]), 4)
        self.assertEqual(len(payload["output_slots"]), 5)
        self.assertEqual(payload["status_lookup"]["output_counts"]["artifact_count"], 4)
        self.assertEqual(
            payload["status_lookup"]["output_counts"]["output_slot_status_counts"]["fulfilled"],
            5,
        )
        self.assertEqual(status_response.status_code, 200)
        status_payload = status_response.get_json()
        self.assertEqual(status_payload["output_counts"]["artifact_count"], 4)
        self.assertEqual(status_payload["output_counts"]["output_slot_status_counts"]["fulfilled"], 5)

    def test_response_lookup_recovery_rejects_stale_current_index(self):
        response_id = "resp_lookup_stale_index_recovery"
        with tempfile.TemporaryDirectory() as tmpdir:
            frames_dir = Path(tmpdir)
            persist_response_frame(
                build_response_frame(
                    {
                        "id": response_id,
                        "object": "response",
                        "status": "completed",
                        "mode": "chat",
                        "model": "gemma4:26b",
                        "backend": "ollama",
                        "capability": "chat",
                        "output_text": "Initial lookup text.",
                    },
                    request_payload={"prompt": "describe then image"},
                ),
                frames_dir=frames_dir,
            )
            stale_index = (frames_dir / "current_index.json").read_text(encoding="utf-8")
            persist_response_frame(
                build_response_frame(
                    {
                        "id": response_id,
                        "object": "response",
                        "status": "completed",
                        "mode": "chat",
                        "model": "gemma4:26b",
                        "backend": "ollama",
                        "capability": "chat",
                        "output_text": "Initial lookup text.",
                        "late_fill": {"status": "completed"},
                        "artifacts": [{"type": "image", "path": "/tmp/generated/lookup-stale-index.png"}],
                    },
                    request_payload={"prompt": "describe then image"},
                ),
                frames_dir=frames_dir,
            )
            (frames_dir / "current_index.json").write_text(stale_index, encoding="utf-8")
            _RESPONSE_LOOKUP.clear()

            with patch("ollmo_webserver.RESPONSE_FRAMES_DIR", frames_dir):
                response = self.client.get(f"/api/responses/{response_id}?view=debug")

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["response_frame"]["frame_sequence"], 2)
        self.assertEqual(payload["response_frame"]["frame_relation"]["kind"], "late_fill_successor")
        self.assertEqual(payload["artifacts"][0]["path"], "/tmp/generated/lookup-stale-index.png")

