    def test_response_status_semantics_uses_explicit_lifecycle_categories(self):
        def payload_for(lifecycle_state, late_fill=None):
            response_id = f"resp_status_semantics_{str(lifecycle_state).replace('-', '_')}"
            return _build_response_lookup_payload(
                {
                    "id": response_id,
                    "message_id": f"msg_{response_id}",
                    "status": "completed",
                    "lifecycle_state": lifecycle_state,
                    "response_payload": {
                        "id": response_id,
                        "object": "response",
                        "status": "completed",
                        "lifecycle_state": lifecycle_state,
                        "output_text": "Status semantics.",
                        "late_fill": late_fill or {},
                    },
                }
            )["status_semantics"]

        running = payload_for("late_fill_running", {"status": "running"})
        pending = payload_for("late_fill_pending", {"status": "pending"})
        late_failed = payload_for("late_fill_failed", {"status": "failed"})
        late_completed = payload_for("late_fill_completed", {"status": "completed"})
        blocked = payload_for("blocked", {"status": "blocked"})
        repair_needed = payload_for(
            "repair_needed",
            {
                "status": "failed",
                "recovery_candidates": [{"suggested_action": "repair_branch_contract"}],
            },
        )

        self.assertTrue(running["has_open_continuation"])
        self.assertFalse(running["has_actionable_repair"])
        self.assertFalse(running["is_terminal"])
        self.assertTrue(pending["has_open_continuation"])
        self.assertFalse(late_failed["has_open_continuation"])
        self.assertTrue(late_failed["is_terminal"])
        self.assertFalse(late_completed["has_open_continuation"])
        self.assertTrue(late_completed["is_terminal"])
        self.assertFalse(blocked["has_open_continuation"])
        self.assertTrue(blocked["has_actionable_repair"])
        self.assertFalse(repair_needed["has_open_continuation"])
        self.assertTrue(repair_needed["has_actionable_repair"])

