    def test_terminal_successor_handoff_persists_before_rescheduling_and_skips_hygiene(self):
        response_id = "resp_terminal_successor_handoff"
        call_order = []
        _register_response_lookup(
            response_id=response_id,
            message_id="",
            instance_id="chat-1",
            model_name="chat-model",
            backend="ollama",
            capability="chat",
            mode="chat",
            route_payload=None,
        )

        def prepare_successor(parent_payload):
            parent_frame = parent_payload["response_frame"]
            successor_payload = copy.deepcopy(parent_payload)
            successor_payload["lifecycle_state"] = "late_fill_pending"
            successor_payload["frame_relation"] = {
                "kind": "graph_patch_reopen_successor",
                "reason": "graph_patch_reopen",
                "parent_response_id": response_id,
                "parent_frame_id": parent_frame["frame_id"],
                "parent_frame_sequence": parent_frame["frame_sequence"],
                "successor_reopen_depth": 1,
            }
            successor_payload["late_fill"] = {
                "status": "pending",
                "successor_reopen_execution": {
                    "status": "queued",
                    "successor_execution_key": "successor-exec-test",
                },
                "pending_branches": [
                    {
                        "branch_id": "repair-image",
                        "phase_id": "repair-image",
                        "capability": "image_generation",
                        "output_type": "image",
                        "status": "pending",
                        "artifact_prompt": "A bounded successor image.",
                    }
                ],
                "pending_capabilities": ["image_generation"],
            }
            return {
                "status": "queued",
                "response_payload": successor_payload,
                "artifact_gap": {
                    "code": "graph_patch_late_fill",
                    "trigger": "graph_patch_successor_reopen",
                    "authoritative_pending_branches": True,
                    "pending_branch_scope": "exact_successor_reopen",
                    "pending_branches": successor_payload["late_fill"]["pending_branches"],
                    "pending_capabilities": ["image_generation"],
                    "successor_reopen_execution": {
                        "successor_execution_key": "successor-exec-test",
                    },
                },
                "execution": {
                    "successor_execution_key": "successor-exec-test",
                    "scheduled_branch_ids": ["repair-image"],
                },
            }

        def release_claim(value):
            self.assertEqual(value, response_id)
            call_order.append("release")

        def schedule_successor(**kwargs):
            call_order.append("schedule")
            self.assertEqual(kwargs["response_payload"]["response_frame"]["frame_relation"]["kind"], "graph_patch_reopen_successor")
            self.assertEqual(kwargs["artifact_gap"]["pending_branch_scope"], "exact_successor_reopen")
            return True

        with patch.object(
            _LATE_FILL_RUNTIME,
            "prepare_terminal_graph_patch_successor",
            side_effect=prepare_successor,
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "finalize_terminal_materialization_contract",
            side_effect=lambda payload, **kwargs: (payload, "completed"),
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "release_response_late_fill",
            side_effect=release_claim,
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "schedule_response_late_fill",
            side_effect=schedule_successor,
        ) as mock_schedule, patch.object(
            _LATE_FILL_RUNTIME,
            "schedule_terminal_substrate_hygiene",
        ) as mock_hygiene:
            _complete_response_late_fill(
                response_payload={
                    "id": response_id,
                    "object": "response",
                    "status": "completed",
                    "mode": "chat",
                    "capability": "chat",
                    "output_text": "Frozen parent output.",
                },
                request_payload={"prompt": "finish only the proven missing branch"},
                assistant_message="Frozen parent output.",
                artifact_gap={},
                source_route_payload=None,
            )

        self.assertEqual(call_order, ["release", "schedule"])
        mock_schedule.assert_called_once()
        mock_hygiene.assert_not_called()
        queued_payload = _RESPONSE_LOOKUP[response_id]["response_payload"]
        self.assertEqual(queued_payload["lifecycle_state"], "late_fill_pending")
        self.assertEqual(
            queued_payload["response_frame"]["frame_relation"]["kind"],
            "graph_patch_reopen_successor",
        )

