    def test_terminal_policy_denial_audit_requires_exact_enforced_contract(self):
        probes = {
            "apply_safe": lambda lifecycle, prepared: lifecycle.update(
                autonomy_level="apply_safe"
            ),
            "missing_autonomy": lambda lifecycle, prepared: lifecycle.pop(
                "autonomy_level", None
            ),
            "missing_policy_review": lambda lifecycle, prepared: lifecycle.pop(
                "enforced_policy_review", None
            ),
            "wrong_policy_kind": lambda lifecycle, prepared: lifecycle[
                "enforced_policy_review"
            ].update(kind="ollmo.not_enforced_policy_review"),
            "wrong_policy_id": lambda lifecycle, prepared: lifecycle[
                "enforced_policy_review"
            ].update(policy_id="unsafe-policy"),
            "wrong_policy_mode": lambda lifecycle, prepared: lifecycle[
                "enforced_policy_review"
            ].update(policy_mode="audit", mode="audit"),
            "prepared_blocked_not_no_safe": lambda lifecycle, prepared: prepared.update(
                status="blocked", reason="different_terminal_block"
            ),
        }
        for label, mutate in probes.items():
            with self.subTest(label=label):
                parent, prepared = self._terminal_policy_denial_fixture(
                    f"resp_terminal_policy_probe_{label}"
                )
                lifecycle = prepared["response_payload"]["runtime"][
                    "request_phase_graph"
                ]["graph_patch_lifecycle"][0]
                mutate(lifecycle, prepared)
                finalizer = Mock()
                durable_loader = Mock()
                with patch.object(
                    _LATE_FILL_RUNTIME,
                    "prepare_terminal_graph_patch_successor",
                    return_value=prepared,
                ), patch.object(
                    _LATE_FILL_RUNTIME,
                    "finalize_response_frame_payload",
                    finalizer,
                ), patch.object(
                    _LATE_FILL_RUNTIME,
                    "load_latest_response_state",
                    durable_loader,
                ):
                    result, handoff = (
                        _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                            copy.deepcopy(parent),
                            request_payload={"prompt": "ROOT MUST NOT REPLAY"},
                            assistant_message="Frozen parent.",
                            artifact_gap={},
                            source_route_payload=None,
                        )
                    )
                self.assertEqual(result, parent)
                self.assertIsNone(handoff)
                finalizer.assert_not_called()
                durable_loader.assert_not_called()

    def test_terminal_policy_denial_audit_rejects_malformed_shapes_and_sequences(self):
        sequence_probes = [True, 0, -1, 1.5, "1"]
        for sequence in sequence_probes:
            with self.subTest(frame_sequence=sequence):
                parent, prepared = self._terminal_policy_denial_fixture(
                    f"resp_terminal_policy_sequence_{str(sequence).replace('.', '_')}"
                )
                parent["response_frame"]["frame_sequence"] = sequence
                prepared["response_payload"]["response_frame"][
                    "frame_sequence"
                ] = sequence
                durable_loader = Mock()
                with patch.object(
                    _LATE_FILL_RUNTIME,
                    "prepare_terminal_graph_patch_successor",
                    return_value=prepared,
                ), patch.object(
                    _LATE_FILL_RUNTIME,
                    "load_latest_response_state",
                    durable_loader,
                ):
                    result, handoff = (
                        _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                            copy.deepcopy(parent),
                            request_payload={"prompt": "ROOT MUST NOT REPLAY"},
                            assistant_message="Frozen parent.",
                            artifact_gap={},
                            source_route_payload=None,
                        )
                    )
                self.assertEqual(result, parent)
                self.assertIsNone(handoff)
                durable_loader.assert_not_called()

        malformed_parent, malformed_prepared = self._terminal_policy_denial_fixture(
            "resp_terminal_policy_malformed_graph"
        )
        malformed_parent["runtime"]["request_phase_graph"] = [{"bad": "graph"}]
        malformed_prepared["response_payload"]["runtime"][
            "request_phase_graph"
        ] = [{"bad": "graph"}]
        with patch.object(
            _LATE_FILL_RUNTIME,
            "prepare_terminal_graph_patch_successor",
            return_value=malformed_prepared,
        ):
            malformed_result, malformed_handoff = (
                _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                    copy.deepcopy(malformed_parent),
                    request_payload={"prompt": "ROOT MUST NOT REPLAY"},
                    assistant_message="Frozen parent.",
                    artifact_gap={},
                    source_route_payload=None,
                )
            )
        self.assertEqual(malformed_result, malformed_parent)
        self.assertIsNone(malformed_handoff)

