        event_log = Mock()
        with patch.dict(app.config, {"TESTING": False}), patch(
            "ollmo_webserver._persist_output_artifact_registry_records"
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "log_unified_event",
            event_log,
        ):
            parent = _finalize_response_frame_payload(
                parent_source,
                request_payload=request_payload,
                persist=True,
            )
            parent_before = copy.deepcopy(parent)
            ledger_path = self._response_frames_dir / "responses.jsonl"
            parent_ledger_line = ledger_path.read_bytes().splitlines(keepends=True)[0]
            _register_response_lookup(
                response_id=response_id,
                message_id="",
                instance_id="chat-1",
                model_name="chat-model",
                backend="ollama",
                capability="chat",
                mode="chat",
                route_payload=None,
            )
            _touch_response_lookup(
                response_id,
                status="completed",
                response_payload=parent,
            )

            def prepare_policy_denial(parent_payload):
                reviewed = copy.deepcopy(parent_payload)
                graph = reviewed["runtime"]["request_phase_graph"]
                prior_rejection = copy.deepcopy(graph["graph_patch_lifecycle"][0])
                prior_rejection["before_graph_digest"] = "graph-refreshed-at-terminal-review"
                prior_rejection["status"] = "blocked"
                prior_rejection["blocked_reasons"] = [
                    "proposal_review_not_accepted",
                    "terminal_frame_requires_successor_reopen",
                ]
                additional_blocked_rejection = {
                    "kind": "ollmo.graph_patch_lifecycle",
                    "patch_id": "graph-patch-additional-terminal-rejection",
                    "proposal_id": "graph-repair-additional-terminal-rejection",
                    "review_id": "graph-repair-review-additional-terminal-rejection",
                    "status": "blocked",
                    "blocked_reasons": [
                        "proposal_review_not_accepted",
                        "terminal_frame_requires_successor_reopen",
                    ],
                }
                graph["graph_patch_lifecycle"] = [
                    prior_rejection,
                    copy.deepcopy(blocked_lifecycle),
                    additional_blocked_rejection,
                    {
                        "kind": "ollmo.graph_patch_lifecycle",
                        "patch_id": "graph-patch-reviewed-validated-must-not-copy",
                        "proposal_id": "graph-repair-reviewed-validated-must-not-copy",
                        "status": "validated",
                    },
                ]
                graph.setdefault("graph_repair_proposals", []).append(
                    {
                        "kind": "ollmo.graph_repair_proposal",
                        "proposal_id": "reviewed-proposal-must-not-copy",
                    }
                )
                graph.setdefault("graph_repair_reviews", []).append(
                    {
                        "kind": "ollmo.graph_repair_proposal_review",
                        "proposal_id": "reviewed-proposal-must-not-copy",
                        "review_id": "reviewed-accepted-must-not-copy",
                        "status": "accepted",
                    }
                )
                graph["successor_reopen_requests"] = [
                    {
                        "kind": "ollmo.graph_patch_successor_reopen_request",
                        "patch_id": "reviewed-candidate-must-not-copy",
                        "status": "candidate",
                    }
                ]
                reviewed["runtime"].setdefault("developer_diagnostics", {})[
                    "graph_patch_lifecycle"
                ] = copy.deepcopy(graph["graph_patch_lifecycle"])
                return {
                    "status": "not_applicable",
                    "reason": "no_safe_terminal_graph_patch_successor",
                    "response_payload": reviewed,
                }

            with patch.object(
                _LATE_FILL_RUNTIME,
                "prepare_terminal_graph_patch_successor",
                side_effect=prepare_policy_denial,
            ):
                audited, handoff = (
                    _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                        copy.deepcopy(parent),
                        request_payload=request_payload,
                        assistant_message="Frozen parent output.",
                        artifact_gap={},
                        source_route_payload=None,
                    )
                )
                replayed, replay_handoff = (
                    _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                        copy.deepcopy(parent),
                        request_payload=request_payload,
                        assistant_message="Frozen parent output.",
                        artifact_gap={},
                        source_route_payload=None,
                    )
                )

        ledger_lines = ledger_path.read_bytes().splitlines(keepends=True)
        latest = load_latest_response_state(
            response_id,
            frames_dir=self._response_frames_dir,
        )
        latest_payload = latest["response_payload"]
        latest_graph = latest_payload["runtime"]["request_phase_graph"]
        latest_lifecycle = next(
            item
            for item in latest_graph["graph_patch_lifecycle"]
            if item["patch_id"] == blocked_lifecycle["patch_id"]
        )
        relation = latest_payload["response_frame"]["frame_relation"]
        tampered_replay = copy.deepcopy(latest_payload)
        tampered_replay["response_frame"]["response_id"] = "resp_unrelated_replay"
        tampered_replay["response_frame"]["frame_id"] = "resp_unrelated_replay:frame-999"
        tampered_replay["response_frame"]["frame_sequence"] = 999
        tampered_replay["response_frame"]["frame_relation"][
            "response_id"
        ] = "resp_unrelated_replay"
        tampered_replay["response_frame"]["frame_relation"]["executable"] = True
        replay_finalizer = Mock()
        with patch.object(
            _LATE_FILL_RUNTIME,
            "prepare_terminal_graph_patch_successor",
            side_effect=prepare_policy_denial,
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "load_latest_response_state",
            return_value={"ok": True, "response_payload": tampered_replay},
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "finalize_response_frame_payload",
            replay_finalizer,
        ):
            tampered_result, tampered_handoff = (
                _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                    copy.deepcopy(parent),
                    request_payload=request_payload,
                    assistant_message="Frozen parent output.",
                    artifact_gap={},
                    source_route_payload=None,
                )
            )

        self.assertIsNone(handoff)
        self.assertIsNone(replay_handoff)
        self.assertEqual(tampered_result, parent)
        self.assertIsNone(tampered_handoff)
        replay_finalizer.assert_not_called()
        self.assertEqual(parent, parent_before)
        self.assertEqual(ledger_lines[0], parent_ledger_line)
        self.assertEqual(len(ledger_lines), 2)
        self.assertEqual(relation["kind"], "graph_patch_terminal_review")
        self.assertEqual(
            relation["parent_frame_id"],
            parent["response_frame"]["frame_id"],
        )
        self.assertEqual(
            relation["parent_frame_sequence"],
            parent["response_frame"]["frame_sequence"],
        )
        self.assertTrue(relation["audit_only"])
        self.assertFalse(relation["executable"])
        self.assertEqual(relation["runtime_effect"], "audit_only_no_execution")
        self.assertEqual(relation["owed_work"], "none")
        self.assertEqual(relation.get("scheduled_branch_ids", []), [])
        self.assertEqual(
            set(relation),
            {
                "audit_key",
                "audit_only",
                "executable",
                "kind",
                "owed_work",
                "parent_frame_id",
                "parent_frame_sequence",
                "parent_response_id",
                "patch_id",
                "policy_review_id",
                "proposal_id",
                "reason",
                "response_id",
                "review_id",
                "runtime_effect",
            },
        )
        self.assertEqual(latest_lifecycle["status"], "blocked")
        self.assertIn(policy_block_reason, latest_lifecycle["blocked_reasons"])
        self.assertEqual(
            latest_lifecycle["enforced_class"],
            "safe_additive_missing_branch",
        )
        self.assertFalse(latest_lifecycle["allowed_by_policy"])
        self.assertFalse(latest_lifecycle["enforced_policy_review"]["allowed"])
        self.assertEqual(
            set(latest_lifecycle),
            {
                "allowed_by_policy",
                "audit_only",
                "authority",
                "autonomy_level",
                "blocked_reasons",
                "enforced_class",
                "enforced_policy_id",
                "enforced_policy_review",
                "idempotency_key",
                "kind",
                "outcome",
                "patch_id",
                "policy_mode",
                "proposal_id",
                "repair_class",
                "review_id",
                "risk_level",
                "status",
            },
        )
        self.assertEqual(
            set(latest_lifecycle["enforced_policy_review"]),
            {
                "allowed",
                "authority",
                "blocked_reasons",
                "enforced_class",
                "kind",
                "mode",
                "policy_id",
                "policy_mode",
                "review_id",
                "selected_scope",
                "selected_scope_allowed",
                "status",
            },
        )
        self.assertFalse(latest_graph.get("successor_reopen_requests"))
        self.assertNotIn(
            "reviewed-proposal-must-not-copy",
            {item.get("proposal_id") for item in latest_graph["graph_repair_proposals"]},
        )
        self.assertNotIn(
            "reviewed-accepted-must-not-copy",
            {item.get("review_id") for item in latest_graph["graph_repair_reviews"]},
        )
        self.assertNotIn(
            "graph-patch-reviewed-validated-must-not-copy",
            {item.get("patch_id") for item in latest_graph["graph_patch_lifecycle"]},
        )
        self.assertEqual(
            next(
                item
                for item in latest_graph["graph_patch_lifecycle"]
                if item.get("patch_id") == "graph-patch-prior-rejection"
            )["before_graph_digest"],
            "graph-before-terminal-review",
        )
        self.assertFalse(latest_payload["late_fill"].get("pending_branches"))
        self.assertFalse(latest_payload["late_fill"].get("active_branches"))
        self.assertNotIn("successor_reopen_execution", latest_payload["late_fill"])
        self.assertEqual(
            audited["response_frame"]["frame_id"],
            latest_payload["response_frame"]["frame_id"],
        )
        self.assertEqual(
            replayed["response_frame"]["frame_id"],
            latest_payload["response_frame"]["frame_id"],
        )
        event_log.assert_called_once()
        self.assertEqual(
            event_log.call_args.kwargs["runtime_effect"],
            "audit_only_no_execution",
        )

