    def test_terminal_successor_handoff_deduplicates_replayed_frozen_parent(self):
        response_id = "resp_terminal_successor_stale_parent_replay"
        execution_key = "successor-exec-stale-parent"
        frozen_parent = {
            "id": response_id,
            "response_id": response_id,
            "status": "completed",
            "lifecycle_state": "completed",
            "output_text": "Frozen parent output.",
            "response_frame": {
                "response_id": response_id,
                "frame_id": f"{response_id}:frame-1",
                "frame_sequence": 1,
                "frame_relation": {"kind": "initial"},
            },
            "runtime": {"request_phase_graph": {}},
            "late_fill": {"status": "partial_failed"},
        }
        _register_response_lookup(
            response_id=response_id,
            message_id="",
            instance_id="chat-1",
            model_name="chat-model",
            backend="ollama",
            capability="chat",
            mode="chat",
            route_payload=None,
        )
        _touch_response_lookup(
            response_id,
            status="completed",
            response_payload=frozen_parent,
        )

        def prepare_successor(parent_payload):
            successor = copy.deepcopy(parent_payload)
            successor["lifecycle_state"] = "late_fill_pending"
            successor["frame_relation"] = {
                "kind": "graph_patch_reopen_successor",
                "reason": "graph_patch_reopen",
                "parent_response_id": response_id,
                "parent_frame_id": frozen_parent["response_frame"]["frame_id"],
                "parent_frame_sequence": 1,
                "successor_reopen_depth": 1,
            }
            successor["late_fill"] = {
                "status": "pending",
                "successor_reopen_execution": {
                    "status": "queued",
                    "successor_execution_key": execution_key,
                },
                "pending_branches": [
                    {
                        "branch_id": "repair-image",
                        "phase_id": "repair-image",
                        "capability": "image_generation",
                        "artifact_prompt": "Only this repaired image branch.",
                    }
                ],
            }
            return {
                "status": "queued",
                "response_payload": successor,
                "artifact_gap": {
                    "code": "graph_patch_late_fill",
                    "trigger": "graph_patch_successor_reopen",
                    "pending_branches": successor["late_fill"]["pending_branches"],
                    "successor_reopen_execution": successor["late_fill"]["successor_reopen_execution"],
                },
                "execution": {
                    "successor_execution_key": execution_key,
                    "scheduled_branch_ids": ["repair-image"],
                },
            }

        finalizer = Mock(
            side_effect=lambda payload, **kwargs: {
                **copy.deepcopy(payload),
                "response_frame": {
                    **copy.deepcopy(payload["response_frame"]),
                    "frame_id": f"{response_id}:frame-2",
                    "frame_sequence": 2,
                    "frame_relation": copy.deepcopy(payload["frame_relation"]),
                },
            }
        )
        with patch.object(
            _LATE_FILL_RUNTIME,
            "prepare_terminal_graph_patch_successor",
            side_effect=prepare_successor,
        ), patch.object(
            _LATE_FILL_RUNTIME,
            "finalize_response_frame_payload",
            finalizer,
        ):
            first_payload, first_handoff = (
                _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                    copy.deepcopy(frozen_parent),
                    request_payload={"prompt": "ROOT MUST NOT REPLAY"},
                    assistant_message="Frozen parent output.",
                    artifact_gap={},
                    source_route_payload=None,
                )
            )
            replay_payload, replay_handoff = (
                _LATE_FILL_RUNTIME._prepare_terminal_graph_patch_successor_handoff(
                    copy.deepcopy(frozen_parent),
                    request_payload={"prompt": "ROOT MUST NOT REPLAY"},
                    assistant_message="Frozen parent output.",
                    artifact_gap={},
                    source_route_payload=None,
                )
            )

        self.assertIsNotNone(first_handoff)
        self.assertEqual(replay_handoff["status"], "already_recorded")
        self.assertTrue(replay_handoff["skip_schedule"])
        self.assertEqual(finalizer.call_count, 1)
        self.assertEqual(first_payload["response_frame"]["frame_sequence"], 2)
        self.assertEqual(replay_payload["response_frame"]["frame_sequence"], 2)
        self.assertEqual(
            replay_payload["late_fill"]["successor_reopen_execution"]["successor_execution_key"],
            execution_key,
        )

