    @patch("ollmo_webserver._execute_chat_backend_request")
    @patch("ollmo_webserver._lookup_instance")
    def test_prepare_phase_control_envelope_retries_once_and_uses_only_substantive_text(
        self,
        mock_lookup,
        mock_execute,
        mock_schedule_late_fill,
    ):
        mock_lookup.return_value = {
            "instance_id": "chat-1",
            "model": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "port": 11435,
        }
        control_envelope = json.dumps(
            {
                "decision_contract": {"status": "ready"},
                "request_phase_graph": {"current_phase_id": "phase-1"},
                "request_ir": {"output_obligations": []},
                "user_facing_response": "I will prepare the story and then invoke TTS.",
            }
        )
        substantive_text = "Der Leuchtturm schwieg, bis die Morgenflut seinen Namen trug."
        mock_execute.side_effect = [control_envelope, substantive_text]

        response = self.client.post(
            "/api/responses",
            json={
                "instance_id": "chat-1",
                "input": "Write a short story and then read it aloud.",
                "response_id": "resp_phase_output_retry_success",
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["output_text"], substantive_text)
        self.assertNotIn("I will prepare the story", payload["output_text"])
        truth = self._canonical_truth_for_payload(payload)
        acceptance = truth["runtime"]["phase_output_acceptance"]
        self.assertEqual(acceptance["status"], "accepted_after_retry")
        self.assertEqual(acceptance["attempt_count"], 2)
        self.assertEqual(
            acceptance["accepted_sha256"],
            hashlib.sha256(substantive_text.encode("utf-8")).hexdigest(),
        )
        self.assertEqual(mock_execute.call_count, 2)
        retry_messages = mock_execute.call_args.kwargs["messages"]
        self.assertIn("phase-output repair", retry_messages[-1]["content"])
        mock_schedule_late_fill.assert_called_once()
        self.assertEqual(
            mock_schedule_late_fill.call_args.kwargs["assistant_message"],
            substantive_text,
        )

