    @patch("ollmo_webserver._execute_chat_backend_request")
    @patch("ollmo_webserver._lookup_instance")
    def test_prepare_phase_second_control_envelope_is_repair_needed_without_late_fill(
        self,
        mock_lookup,
        mock_execute,
        mock_schedule_late_fill,
    ):
        mock_lookup.return_value = {
            "instance_id": "chat-1",
            "model": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "port": 11435,
        }
        control_envelope = json.dumps(
            {
                "decision_contract": {"status": "ready"},
                "request_ir": {"output_obligations": []},
                "user_facing_response": "I will prepare the story next.",
            }
        )
        truncated_control_envelope = (
            '{"decision_contract":{"status":"ready"},'
            '"request_ir":{"output_obligations":['
        )
        mock_execute.side_effect = [control_envelope, truncated_control_envelope]

        response = self.client.post(
            "/api/responses",
            json={
                "instance_id": "chat-1",
                "input": "Write a short story and then read it aloud.",
                "response_id": "resp_phase_output_retry_blocked",
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.get_json()
        self.assertEqual(payload["lifecycle_state"], "repair_needed")
        self.assertNotIn("I will prepare the story", payload["output_text"])
        self.assertNotIn(truncated_control_envelope, payload["output_text"])
        truth = self._canonical_truth_for_payload(payload)
        self.assertEqual(
            truth["runtime"]["truth_guard"]["status"],
            "repair_required",
        )
        acceptance = truth["runtime"]["phase_output_acceptance"]
        self.assertEqual(acceptance["status"], "repair_required")
        self.assertEqual(acceptance["attempt_count"], 2)
        closure_checks = truth["runtime"]["graph_closure_review"]["checks"]
        self.assertTrue(
            any(
                check.get("check_kind") == "prepared_substantive_text_accepted"
                and check.get("evidence") == "control_envelope_not_speakable"
                for check in closure_checks
            )
        )
        self.assertEqual(mock_execute.call_count, 2)
        mock_schedule_late_fill.assert_not_called()

