    def test_request_phase_graph_promotes_update_artifacts_from_prior_fenced_source_blocks(self):
        prompt = (
            'Ändere das Kontrollzentrum auf ein helles Eisblau/Weiss-Notfall-Design, '
            'behalte die Struktur bei, und speichere die aktualisierten Artefakte wieder als echte Dateien.'
        )
        previous_assistant = (
            '```html\n'
            '<!-- index.html -->\n'
            '<!doctype html><html><head><link rel="stylesheet" href="style.css"></head><body></body></html>\n'
            '```\n\n'
            '```css\n'
            '/* style.css */\n'
            'body { color: orange; background: black; }\n'
            '```'
        )

        graph = build_request_phase_graph(
            prompt,
            request_payload={
                'ghost_route': True,
                'input': [
                    {
                        'role': 'assistant',
                        'content': [{'type': 'input_text', 'text': previous_assistant}],
                    },
                    {
                        'role': 'user',
                        'content': [{'type': 'input_text', 'text': prompt}],
                    },
                ],
            },
            route_payload={'route_source': 'ghost_carried', 'capability': 'chat'},
        )

        artifact_branches = [
            branch for branch in graph['downstream_branches']
            if branch.get('role') == 'text_artifact_output'
        ]

        self.assertEqual(
            [(branch['text_artifact_extension'], branch['text_artifact_source_name']) for branch in artifact_branches],
            [('html', 'index'), ('css', 'style')],
        )

