    def test_terminal_linked_artifact_contract_blocks_duplicate_substitution_without_prior_check(self):
        prompt = (
            'Create local linked artifacts: index.html plus four generated image artifacts. '
            'The final HTML must link every saved generated artifact.'
        )
        graph = build_request_phase_graph(
            prompt,
            request_payload={'ghost_route': True, 'prompt': prompt},
            route_payload={'capability': 'chat', 'route_source': 'ghost_carried'},
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            documents = root / 'documents'
            images = root / 'images'
            documents.mkdir()
            images.mkdir()
            html_path = documents / 'index.html'
            image_paths = [images / f'owed-artifact-{index}.png' for index in range(1, 5)]
            for image_path in image_paths:
                image_path.write_bytes(b'png')
            duplicate_html = (
                '<!doctype html><html><body>'
                + ''.join(f'<img src="../images/{image_paths[0].name}">' for _index in range(4))
                + '</body></html>'
            )
            html_path.write_text(duplicate_html, encoding='utf-8')
            payload = {
                'id': 'resp_duplicate_substitution_contract',
                'status': 'completed',
                'output_text': 'Artifacts generated.',
                'runtime': {'request_phase_graph': graph},
                'artifacts': [
                    {
                        'type': 'text',
                        'path': str(html_path),
                        'name': 'index',
                        'mime_type': 'text/html',
                        'artifact_ref': 'artifact:index',
                    },
                    *[
                        {
                            'type': 'image',
                            'path': str(image_path),
                            'artifact_ref': f'artifact:image-{index}',
                        }
                        for index, image_path in enumerate(image_paths, start=1)
                    ],
                ],
                'late_fill': {
                    'status': 'completed',
                    'completed_branches': [
                        *[
                            {
                                'branch_id': f'branch-image_generation-{index}',
                                'phase_id': f'phase-{index + 1}',
                                'capability': 'image_generation',
                                'output_type': 'image',
                                'status': 'fulfilled',
                            }
                            for index in range(1, 5)
                        ],
                        {
                            'branch_id': 'branch-text_artifact-1',
                            'phase_id': 'phase-6',
                            'capability': 'chat',
                            'output_type': 'text',
                            'status': 'fulfilled',
                        },
                    ],
                    'pending_branches': [],
                    'failed_branches': [],
                    'fill_results': [
                        *[
                            {
                                'branch_id': f'branch-image_generation-{index}',
                                'phase_id': f'phase-{index + 1}',
                                'capability': 'image_generation',
                                'saved_image_path': str(image_path),
                            }
                            for index, image_path in enumerate(image_paths, start=1)
                        ],
                        {
                            'branch_id': 'branch-text_artifact-1',
                            'phase_id': 'phase-6',
                            'capability': 'chat',
                            'saved_text_path': str(html_path),
                            'text_artifact_extension': 'html',
                            'text_artifact_source_name': 'index',
                        },
                    ],
                },
            }

            updated, effective_status = _LATE_FILL_RUNTIME.finalize_terminal_materialization_contract(
                payload,
                request_payload={'ghost_route': True, 'prompt': prompt},
                route_payload={'route_runtime': {'request_phase_graph': graph}},
                artifact_gap={'expected_capability': 'chat'},
                terminal_status='completed',
            )
            late_fill = updated['late_fill']
            self.assertEqual(effective_status, 'partial_failed')
            self.assertEqual(late_fill['final_materialization_contract_status'], 'unmet')
            self.assertTrue(late_fill['materialization_contract_unmet'])
            self.assertEqual(html_path.read_text(encoding='utf-8'), duplicate_html)
            self.assertNotIn('composed_page_image_representation_repair_status', late_fill)
            self.assertTrue(
                any(
                    item.get('check_kind') == 'linked_artifact_binding'
                    and item.get('evidence') == 'unresolved_linked_artifact_binding'
                    for item in late_fill['materialization_contract_open_checks']
                )
            )

    def test_terminal_materialization_contract_blocks_missing_local_stylesheet_link(self):
        prompt = (
            'Create local linked web artifacts: index.html and style.css. '
            'The final HTML must link the saved CSS file.'
        )
        graph = build_request_phase_graph(
            prompt,
            request_payload={'ghost_route': True, 'prompt': prompt},
            route_payload={'capability': 'chat', 'route_source': 'ghost_carried'},
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            documents = root / 'documents'
            documents.mkdir()
            html_path = documents / 'index.html'
            missing_styles_path = documents / 'style.css'
            html_path.write_text(
                '<!doctype html><html><head>'
                '<link rel="stylesheet" href="style.css">'
                '</head><body><main class="hero"><h1>Pure Thread</h1></main></body></html>',
                encoding='utf-8',
            )
            payload = {
                'id': 'resp_missing_local_stylesheet_link',
                'status': 'completed',
                'output_text': 'Artifacts generated.',
                'runtime': {'request_phase_graph': graph},
                'artifacts': [
                    {
                        'type': 'text',
                        'path': str(html_path),
                        'name': 'index',
                        'mime_type': 'text/html',
                        'artifact_ref': 'artifact:index',
                        'branch_id': 'branch-text_artifact-1',
                        'phase_id': 'phase-1',
                        'text_artifact_extension': 'html',
                        'text_artifact_source_name': 'index',
                    },
                ],
                'late_fill': {
                    'status': 'completed',
                    'completed_branches': [
                        {
                            'branch_id': 'branch-text_artifact-1',
                            'phase_id': 'phase-1',
                            'capability': 'chat',
                            'output_type': 'text',
                            'status': 'fulfilled',
                            'artifact_request': {'extension': 'html', 'source_name': 'index'},
                        },
                        {
                            'branch_id': 'branch-text_artifact-2',
                            'phase_id': 'phase-2',
                            'capability': 'chat',
                            'output_type': 'text',
                            'status': 'fulfilled',
                            'artifact_request': {
                                'extension': 'css',
                                'source_name': 'style',
                                'target_path': str(missing_styles_path),
                            },
                        },
                    ],
                    'pending_branches': [],
                    'failed_branches': [],
                    'fill_results': [
                        {
                            'branch_id': 'branch-text_artifact-1',
                            'phase_id': 'phase-1',
                            'capability': 'chat',
                            'saved_text_path': str(html_path),
                            'text_artifact_extension': 'html',
                            'text_artifact_source_name': 'index',
                        },
                    ],
                },
            }

            updated, effective_status = _LATE_FILL_RUNTIME.finalize_terminal_materialization_contract(
                payload,
                request_payload={'ghost_route': True, 'prompt': prompt},
                route_payload={'route_runtime': {'request_phase_graph': graph}},
                artifact_gap={'expected_capability': 'chat'},
                terminal_status='completed',
            )

            late_fill = updated['late_fill']
            expected_styles_target = str(missing_styles_path.resolve(strict=False))
            self.assertEqual(effective_status, 'partial_failed')
            self.assertEqual(late_fill['final_materialization_contract_status'], 'unmet')
            self.assertTrue(late_fill['materialization_contract_unmet'])
            self.assertFalse(missing_styles_path.exists())
            open_checks = late_fill['materialization_contract_open_checks']
            self.assertTrue(
                any(
                    item.get('check_kind') == 'linked_artifact_binding'
                    and item.get('evidence') == 'unresolved_local_dependency_link'
                    and item.get('text_artifact_extension') == 'css'
                    and item.get('text_artifact_target_path') == expected_styles_target
                    for item in open_checks
                )
            )
            pending_css = [
                item
                for item in late_fill['pending_branches']
                if item.get('text_artifact_extension') == 'css'
            ]
            self.assertEqual(len(pending_css), 1)
            self.assertEqual(pending_css[0]['content_payload_source'], 'closure_local_dependency_link_review')
            self.assertEqual(pending_css[0]['artifact_request']['target_path'], expected_styles_target)

