    def test_terminal_materialization_contract_blocks_malformed_structured_dependency_join(self):
        prompt = (
            'Erzeuge genau drei unterschiedliche lokale Bilder: '
            'A – ein roter Leuchtturm; B – eine grüne Bibliothek; '
            'C – ein blaues Gewächshaus. Analysiere danach jedes Bild separat. '
            'Gib abschließend genau eine JSON-Liste mit den Feldern '
            'label, artifact_ref und visible_evidence für A, B und C aus.'
        )
        image_paths = {
            'A': '/tmp/materialization-structured-a.png',
            'B': '/tmp/materialization-structured-b.png',
            'C': '/tmp/materialization-structured-c.png',
        }
        phases = [
            {
                'phase_id': 'phase-1',
                'capability': 'chat',
                'output_type': 'text',
                'role': 'text_preparation',
                'status': 'completed',
            },
            *[
                {
                    'phase_id': f'phase-{index + 1}',
                    'branch_id': f'branch-image_generation-{index}',
                    'capability': 'image_generation',
                    'output_type': 'image',
                    'depends_on': ['phase-1'],
                    'queue_index': index,
                    'status': 'completed',
                }
                for index in range(1, 4)
            ],
            *[
                {
                    'phase_id': f'phase-{index + 4}',
                    'branch_id': f'branch-vision_analysis-{index}',
                    'capability': 'vision_analysis',
                    'output_type': 'text',
                    'depends_on': [f'phase-{index + 1}'],
                    'queue_index': index,
                    'status': 'completed',
                }
                for index in range(1, 4)
            ],
            {
                'phase_id': 'phase-8',
                'branch_id': 'branch-chat-1',
                'capability': 'chat',
                'output_type': 'text',
                'role': 'post_artifact_text_follow_up',
                'stage_direction': 'write_text_after_artifact_generation',
                'depends_on': ['phase-5', 'phase-6', 'phase-7'],
                'status': 'completed',
            },
        ]
        graph = {
            'kind': 'ollmo.request_phase_graph',
            'mode': 'phase_chain',
            'prompt': prompt,
            'current_phase_id': 'phase-1',
            'current_phase_capability': 'chat',
            'phases': phases,
        }
        correct_rows = [
            {
                'label': label,
                'artifact_ref': image_paths[label],
                'visible_evidence': f'Visible evidence for {label}.',
            }
            for label in ('A', 'B', 'C')
        ]
        malformed_rows = [
            correct_rows[0],
            {**correct_rows[0], 'artifact_ref': image_paths['B']},
            correct_rows[1],
            {**correct_rows[2], 'artifact_ref': image_paths['B']},
            correct_rows[2],
        ]

        def payload_for(rows):
            terminal_text = json.dumps(rows, ensure_ascii=False)
            completed_branches = [
                {
                    'phase_id': phase['phase_id'],
                    'branch_id': phase.get('branch_id', phase['phase_id']),
                    'capability': phase['capability'],
                    'output_type': phase.get('output_type'),
                    'status': 'fulfilled',
                }
                for phase in phases[1:]
            ]
            fill_results = [
                {
                    'phase_id': f'phase-{index + 1}',
                    'branch_id': f'branch-image_generation-{index}',
                    'capability': 'image_generation',
                    'saved_image_path': image_paths[label],
                }
                for index, label in enumerate(('A', 'B', 'C'), start=1)
            ]
            fill_results.extend(
                {
                    'phase_id': f'phase-{index + 4}',
                    'branch_id': f'branch-vision_analysis-{index}',
                    'capability': 'vision_analysis',
                    'result_text': json.dumps([correct_rows[index - 1]], ensure_ascii=False),
                }
                for index in range(1, 4)
            )
            fill_results.append(
                {
                    'phase_id': 'phase-8',
                    'branch_id': 'branch-chat-1',
                    'capability': 'chat',
                    'result_text': terminal_text,
                    'content_payload_source': (
                        'late_fill_results:branch-vision_analysis-1,'
                        'branch-vision_analysis-2,branch-vision_analysis-3'
                    ),
                }
            )
            return {
                'id': 'resp_terminal_structured_dependency_join',
                'status': 'completed',
                'output_text': terminal_text,
                'runtime': {'request_phase_graph': graph},
                'artifacts': [
                    {
                        'type': 'image',
                        'path': image_paths[label],
                        'artifact_ref': f'artifact:image-{label.lower()}',
                        'phase_id': f'phase-{index + 1}',
                        'branch_id': f'branch-image_generation-{index}',
                    }
                    for index, label in enumerate(('A', 'B', 'C'), start=1)
                ],
                'late_fill': {
                    'status': 'completed',
                    'completed_capabilities': ['image_generation', 'vision_analysis', 'chat'],
                    'completed_branches': completed_branches,
                    'pending_branches': [],
                    'active_branches': [],
                    'failed_branches': [],
                    'fill_results': fill_results,
                },
            }

        valid, valid_status = _LATE_FILL_RUNTIME.finalize_terminal_materialization_contract(
            payload_for(correct_rows),
            request_payload={'ghost_route': True, 'prompt': prompt},
            route_payload={'route_runtime': {'request_phase_graph': graph}},
            artifact_gap={'expected_capability': 'chat'},
            terminal_status='completed',
        )
        self.assertEqual(valid_status, 'completed')
        self.assertEqual(valid['late_fill']['final_materialization_contract_status'], 'fulfilled')
        self.assertFalse(valid['late_fill'].get('materialization_contract_open_checks'))

        updated, effective_status = _LATE_FILL_RUNTIME.finalize_terminal_materialization_contract(
            payload_for(malformed_rows),
            request_payload={'ghost_route': True, 'prompt': prompt},
            route_payload={'route_runtime': {'request_phase_graph': graph}},
            artifact_gap={'expected_capability': 'chat'},
            terminal_status='completed',
        )

        late_fill = updated['late_fill']
        self.assertEqual(effective_status, 'partial_failed')
        self.assertEqual(late_fill['status'], 'partial_failed')
        self.assertEqual(late_fill['final_materialization_contract_status'], 'unmet')
        self.assertEqual(
            late_fill['final_materialization_contract_reason'],
            'terminal structured dependency join violates its explicit output contract',
        )
        check = next(
            item
            for item in late_fill['materialization_contract_open_checks']
            if item.get('check_kind') == 'structured_dependency_join'
        )
        self.assertEqual(check['branch_id'], 'branch-chat-1')
        self.assertEqual(check['phase_id'], 'phase-8')
        self.assertEqual(check['expected_count'], 3)
        self.assertEqual(check['actual_count'], 5)
        self.assertTrue(
            {
                'exact_count_mismatch',
                'duplicate_label',
                'duplicate_artifact_ref',
                'label_ref_dependency_mismatch',
            }.issubset(set(check['issue_codes']))
        )
        self.assertFalse(
            any(
                branch.get('branch_id') == 'branch-chat-1'
                for branch in late_fill.get('completed_branches', [])
                if isinstance(branch, dict)
            )
        )

