    def _inline_html_with_generated_images_payload(
        self,
        root: Path,
        *,
        inline_text: str,
        image_count: int = 2,
    ):
        prompt = (
            'Create a funny colorful landing page about animal selfies, use proper CSS, '
            'and create generated animal selfie image artifacts.'
        )
        images = root / 'images'
        images.mkdir()
        image_paths = [images / f'animal-selfie-{index}.png' for index in range(1, image_count + 1)]
        for index, image_path in enumerate(image_paths, start=1):
            image_path.write_bytes(f'png-{index}'.encode('utf-8'))
        artifacts = [
            {
                'type': 'image',
                'path': str(image_path),
                'artifact_ref': f'artifact:image-{index}',
                'branch_id': f'branch-image_generation-{index}',
                'phase_id': f'phase-{index + 1}',
            }
            for index, image_path in enumerate(image_paths, start=1)
        ]
        outputs = [
            {
                'slot_id': 'output-phase-1',
                'branch_id': 'phase-1',
                'phase_id': 'phase-1',
                'type': 'text',
                'status': 'fulfilled',
                'value': inline_text,
            },
            *[
                {
                    'slot_id': f'output-image-{index}',
                    'branch_id': f'branch-image_generation-{index}',
                    'phase_id': f'phase-{index + 1}',
                    'type': 'image',
                    'status': 'fulfilled',
                    'artifact_ref': f'artifact:image-{index}',
                }
                for index in range(1, image_count + 1)
            ],
        ]
        payload = {
            'id': 'resp_inline_html_generated_images',
            'status': 'completed',
            'output_text': inline_text,
            'outputs': outputs,
            'artifacts': artifacts,
            'late_fill': {
                'status': 'completed',
                'completed_branches': [
                    {
                        'branch_id': f'branch-image_generation-{index}',
                        'phase_id': f'phase-{index + 1}',
                        'capability': 'image_generation',
                        'output_type': 'image',
                        'status': 'fulfilled',
                    }
                    for index in range(1, image_count + 1)
                ],
                'pending_branches': [],
                'failed_branches': [],
                'fill_results': [
                    {
                        'branch_id': f'branch-image_generation-{index}',
                        'phase_id': f'phase-{index + 1}',
                        'capability': 'image_generation',
                        'saved_image_path': str(image_path),
                        'artifact_prompt': f'funny animal selfie {index}',
                    }
                    for index, image_path in enumerate(image_paths, start=1)
                ],
            },
        }
        return prompt, payload, image_paths

    def test_inline_html_with_generated_images_requires_durable_text_artifact(self):
        inline_text = (
            '<!doctype html><html><head><title>Animal Selfies</title></head>'
            '<body><img src="animal-selfie-1.png"><img src="animal-selfie-2.png"></body></html>'
        )
