    def test_responses_runtime_materializes_upload_before_ghost_route(self):
        upload = FileStorage(
            stream=io.BytesIO(b'RIFF....WAVEfmt '),
            filename='sample.wav',
            content_type='audio/wav',
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            persisted_input_root = root / 'inputs'
            registry_path = root / 'artifact_registry.jsonl'

            def persist_input_to_test_root(
                source_path,
                *,
                source_name,
                file_kind,
                **_kwargs,
            ):
                return _persist_input_file_locally(
                    source_path,
                    source_name=source_name,
                    file_kind=file_kind,
                    output_root=persisted_input_root,
                )

            with (
                patch(
                    'ollmo_webserver._persist_input_file_locally',
                    side_effect=persist_input_to_test_root,
                ),
                patch('ollmo_webserver.ARTIFACT_REGISTRY_LEDGER', registry_path),
            ):
                payload, remaining_upload = (
                    _RESPONSES_REQUEST_RUNTIME.materialize_upload_input_artifacts(
                        {'prompt': 'Transkribiere diese Datei.', 'ghost_route': True},
                        upload,
                    )
                )

            self.assertIsNone(remaining_upload)
            self.assertTrue(payload['upload_materialized_as_input_artifact'])
            self.assertEqual(payload['file_kind'], 'audio')
            self.assertTrue(str(payload.get('file_path') or '').endswith('.wav'))
            persisted_path = Path(payload['file_path']).resolve()
            self.assertTrue(persisted_path.exists())
            self.assertIn(persisted_input_root.resolve(), persisted_path.parents)
            self.assertTrue(registry_path.exists())
            self.assertEqual(payload['input_artifacts'][0]['kind'], 'audio')
            self.assertEqual(payload['input_artifacts'][0]['path'], payload['file_path'])

