    def test_late_fill_partial_retry_preserves_original_plain_alpha_batch_cardinality(self):
        scene_prompts = [
            'A red lighthouse surrounded by snow in bright daylight.',
            'A green library at night with warm reading lamps.',
            'A blue glass greenhouse during a heavy rainstorm.',
        ]
        prepared_text = (
            f'A: {scene_prompts[0]}\n'
            f'B: {scene_prompts[1]}\n'
            f'C: {scene_prompts[2]}\n\n'
            'For each generated image, perform a separate visual analysis.\n\n'
            'Output exactly one JSON list with label, artifact_ref, and visible_evidence.'
        )
        corrupt_batch = [
            ' '.join(
                [
                    f'A: {scene_prompts[0]}',
                    f'B: {scene_prompts[1]}',
                    f'C: {scene_prompts[2]}',
                ]
            ),
            'For each generated image, perform a separate visual analysis.',
            'Output exactly one JSON list with label, artifact_ref, and visible_evidence.',
        ]
        branches = [
            {
                'branch_id': f'branch-image-{label}',
                'phase_id': f'phase-image-{label}',
                'capability': 'image_generation',
                'output_type': 'image',
                'depends_on': ['phase-prepare'],
                'queue_index': index,
            }
            for index, label in enumerate(('alpha', 'beta', 'gamma'), start=1)
        ]
        phase_graph = {
            'current_phase_id': 'phase-prepare',
            'current_phase_capability': 'chat',
            'prompt_intent': {'requested_visual_output_count': 3},
            'phases': [
                {
                    'phase_id': 'phase-prepare',
                    'capability': 'chat',
                    'kind': 'prepare',
                    'role': 'text_preparation',
                    'status': 'completed',
                },
                *branches,
            ],
        }

        for retry_index, retry_branch in enumerate(branches, start=1):
            completed_branches = [
                {**branch, 'status': 'fulfilled'}
                for branch in branches
                if branch['branch_id'] != retry_branch['branch_id']
            ]
            artifact_gap = {
                'trigger': 'phase_continuation',
                'pending_branches': [retry_branch],
                'completed_branches': completed_branches,
                'batch_prompts': list(corrupt_batch),
                'artifact_prompt': corrupt_batch[0],
                'artifact_prompt_source': 'phase_prepare_text',
                'content_payload': prepared_text,
            }
            current_payload = {
                'output_text': prepared_text,
                'runtime': {'request_phase_graph': phase_graph},
                'late_fill': {
                    'pending_branches': [retry_branch],
                    'completed_branches': completed_branches,
                    'batch_prompts': list(corrupt_batch),
                },
            }

            with self.subTest(retry_index=retry_index):
                spec = _LATE_FILL_RUNTIME.build_late_fill_materialization_branch_spec(
                    branch=retry_branch,
                    artifact_gap=artifact_gap,
                    current_payload=current_payload,
                    request_payload={'prompt': 'Generate and inspect three labeled images.'},
                    assistant_message=prepared_text,
                    source_route_payload=None,
                    failed_instance_id=None,
                )

                branch_gap = spec['prepare_args']['artifact_gap']
                self.assertEqual(branch_gap['artifact_prompt'], scene_prompts[retry_index - 1])
                self.assertEqual(branch_gap['artifact_prompt_source'], 'semantic_batch_prompt')
                self.assertEqual(branch_gap['image_prompt_selection_index'], retry_index)

