        current_payload = {
            'runtime': {
                'request_phase_graph': {
                    'prompt_intent': {'requested_visual_output_count': 1},
                    'phases': [expanded_branches[0]],
                },
            },
            'late_fill': dict(branch_gap),
        }

        count = _LATE_FILL_RUNTIME._image_prompt_batch_expected_count(
            branch=expanded_branches[-1],
            branch_gap=branch_gap,
            current_payload=current_payload,
        )

        self.assertEqual(count, 5)

