    def test_late_fill_retry_uses_durable_batch_authority_without_graph(self):
        scene_prompts = [
            'A red lighthouse surrounded by snow in bright daylight.',
            'A green library at night with warm reading lamps.',
            'A blue glass greenhouse during a heavy rainstorm.',
        ]
        prepared_text = (
            f'A: {scene_prompts[0]}\n'
            f'B: {scene_prompts[1]}\n'
            f'C: {scene_prompts[2]}\n\n'
            'For each generated image, perform a separate visual analysis.\n\n'
            'Output exactly one JSON list with label, artifact_ref, and visible_evidence.'
        )
        corrupt_batch = [
            ' '.join(
                [
                    f'A: {scene_prompts[0]}',
                    f'B: {scene_prompts[1]}',
                    f'C: {scene_prompts[2]}',
                ]
            ),
            'For each generated image, perform a separate visual analysis.',
            'Output exactly one JSON list with label, artifact_ref, and visible_evidence.',
        ]
        retry_branch = {
            'branch_id': 'branch-image-gamma',
            'phase_id': 'phase-image-gamma',
            'capability': 'image_generation',
            'output_type': 'image',
            'depends_on': ['phase-prepare'],
            'queue_index': 3,
        }
        state = _build_late_fill_state(
            {
                'expected_capability': 'image_generation',
                'batch_prompts': list(corrupt_batch),
                'batch_prompts_source': 'semantic_prepare_phase_output',
                'batch_prompt_source_phase_id': 'phase-prepare',
                'batch_prompt_expected_count': 3,
                'content_payload': prepared_text,
                'artifact_prompt': corrupt_batch[0],
                'artifact_prompt_source': 'phase_prepare_text',
                'pending_branches': [retry_branch],
            },
            status='pending',
        )

        spec = _LATE_FILL_RUNTIME.build_late_fill_materialization_branch_spec(
            branch=state['pending_branches'][0],
            artifact_gap=state,
            current_payload={'output_text': prepared_text, 'late_fill': state},
            request_payload={'prompt': 'Generate and inspect three labeled images.'},
            assistant_message=prepared_text,
            source_route_payload=None,
            failed_instance_id=None,
        )

        branch_gap = spec['prepare_args']['artifact_gap']
        self.assertEqual(branch_gap['artifact_prompt'], scene_prompts[2])
        self.assertEqual(branch_gap['artifact_prompt_source'], 'semantic_prepare_phase_output')
        self.assertEqual(branch_gap['image_prompt_selection_index'], 3)

    def test_late_fill_image_branches_use_root_prompt_image_slots_when_phase_output_is_html(self):
        request_prompt = (
            'Create a polished landing page for Aetheria Zenith-9. First, create exactly three distinct image assets: '
            '1. A wide cinematic exterior view of a massive sci-fi station suspended inside turbulent glowing orange '
            'and purple clouds of a gas giant, featuring solar stabilizers and glowing observation domes. Octane render style. '
            '2. An interior view of a massive zero-gravity greenhouse biome filled with lush alien bioluminescent plants, '
            'with roots suspended in nutrient mists. Cinematic lighting style. '
            '3. A high-tech atmospheric analysis laboratory equipped with holographic data screens, telemetry displays, '
            'and pressurized containment chambers containing swirling gases. '
            'Then create exactly two local file artifacts: 1. index.html 2. styles.css'
        )
        html_phase_output = (
            "<section class=\"split-section\" style=\"background-image: url('greenhouse.png');\">"
            '<div class="image-overlay"></div><h2>The Biosphere</h2></section>'
            "<section class=\"split-section reverse\" style=\"background-image: url('laboratory.png');\">"
            '<h2>The Laboratory</h2></section>'
        )
        expected = [
            'A wide cinematic exterior view of a massive sci-fi station suspended inside turbulent glowing orange '
            'and purple clouds of a gas giant, featuring solar stabilizers and glowing observation domes. Octane render style.',
            'An interior view of a massive zero-gravity greenhouse biome filled with lush alien bioluminescent plants, '
            'with roots suspended in nutrient mists. Cinematic lighting style.',
            'A high-tech atmospheric analysis laboratory equipped with holographic data screens, telemetry displays, '
            'and pressurized containment chambers containing swirling gases.',
        ]

        for index, expected_prompt in enumerate(expected, start=1):
            spec = _LATE_FILL_RUNTIME.build_late_fill_materialization_branch_spec(
                branch={
                    'branch_id': f'branch-image_generation-{index}',
                    'phase_id': f'phase-{index + 1}',
                    'capability': 'image_generation',
                    'output_type': 'image',
                    'depends_on': ['phase-1'],
                    'queue_index': index,
                },
                artifact_gap={'trigger': 'phase_continuation'},
                current_payload={
                    'output_text': html_phase_output,
                    'runtime': {
                        'request_phase_graph': {
                            'current_phase_capability': 'chat',
                        },
                    },
                },
                request_payload={'prompt': request_prompt},
                assistant_message='HTML and CSS drafted.',
                source_route_payload=None,
                failed_instance_id=None,
            )

            artifact_gap = spec['prepare_args']['artifact_gap']
            self.assertEqual(artifact_gap['artifact_prompt'], expected_prompt)
            self.assertEqual(artifact_gap['artifact_prompt_source'], 'request_prompt_image_slots')
            self.assertNotIn('url(', artifact_gap['artifact_prompt'])
            self.assertNotIn('<section', artifact_gap['artifact_prompt'])

