    def test_late_fill_branch_spec_builds_execution_contract(self):
        spec = _LATE_FILL_RUNTIME.build_late_fill_materialization_branch_spec(
            branch={
                'branch_id': 'branch-text_artifact-1',
                'phase_id': 'phase-2',
                'task_id': 'task-phase-2',
                'obligation_id': 'obligation-phase-2',
                'capability': 'chat',
                'output_type': 'text',
                'depends_on': ['phase-1'],
                'input_refs': [{'kind': 'phase_output', 'phase_id': 'phase-1', 'role': 'dependency'}],
                'stage_direction': 'materialize_requested_text_artifact',
                'requires_artifact': True,
                'text_artifact_extension': 'md',
                'text_artifact_source_name': 'rescue-plan',
                'text_artifact_source': 'runtime_contract',
            },
            artifact_gap={'trigger': 'phase_continuation'},
            current_payload={
                'output_text': '# Rescue plan\n',
                'runtime': {
                    'request_phase_graph': {
                        'current_phase_capability': 'chat',
                    },
                },
            },
            request_payload={'prompt': 'Create a markdown rescue plan artifact.'},
            assistant_message='Preparing artifact.',
            source_route_payload=None,
            failed_instance_id=None,
        )

        artifact_gap = spec['prepare_args']['artifact_gap']
        contract = artifact_gap['execution_contract']
        self.assertEqual(contract['kind'], 'ollmo.execution_contract')
        self.assertEqual(contract['branch_id'], 'branch-text_artifact-1')
        self.assertEqual(contract['phase_id'], 'phase-2')
        self.assertEqual(contract['workload_task_ref']['task_id'], 'task-phase-2')
        self.assertEqual(contract['output_obligation_ref']['obligation_id'], 'obligation-phase-2')
        self.assertEqual(contract['output_contract']['output_type'], 'text')
        self.assertEqual(contract['output_contract']['fulfillment_policy'], 'materialized_artifact_required')
        self.assertEqual(contract['depends_on'], ['phase-1'])
        self.assertEqual(artifact_gap['workload_task_ref']['task_id'], 'task-phase-2')
        self.assertEqual(artifact_gap['output_obligation_ref']['obligation_id'], 'obligation-phase-2')

