    def test_late_fill_chat_branch_carries_exact_producer_identity_through_evidence_consumer(self):
        cases = (
            {
                'name': 'vision_image',
                'producer_capability': 'image_generation',
                'producer_branch': 'branch-image_generation-1',
                'consumer_capability': 'vision_analysis',
                'consumer_branch': 'branch-vision_analysis-1',
                'saved_key': 'saved_image_path',
                'artifact_type': 'image',
                'path': '/tmp/identity-image.png',
                'ref': 'artifact:identity-image',
                'result_text': 'A red lighthouse is visible in snow.',
            },
            {
                'name': 'stt_audio',
                'producer_capability': 'text_to_speech',
                'producer_branch': 'branch-text_to_speech-1',
                'consumer_capability': 'speech_to_text',
                'consumer_branch': 'branch-speech_to_text-1',
                'saved_key': 'saved_audio_path',
                'artifact_type': 'audio',
                'path': '/tmp/identity-audio.wav',
                'ref': 'artifact:identity-audio',
                'result_text': 'Leuchtturm im Schnee.',
            },
        )
        for case in cases:
            with self.subTest(case=case['name']):
                producer_result = {
                    'branch_id': case['producer_branch'],
                    'phase_id': 'phase-2',
                    'capability': case['producer_capability'],
                    case['saved_key']: case['path'],
                }
                consumer_result = {
                    'branch_id': case['consumer_branch'],
                    'phase_id': 'phase-3',
                    'capability': case['consumer_capability'],
                    'result_text': case['result_text'],
                    'execution_contract': {
                        'branch_id': case['consumer_branch'],
                        'phase_id': 'phase-3',
                        'capability': case['consumer_capability'],
                        'depends_on': ['phase-2'],
                    },
                }
                payload = _LATE_FILL_RUNTIME.branch_dependency_payload(
                    {
                        'branch_id': 'branch-chat-1',
                        'phase_id': 'phase-4',
                        'capability': 'chat',
                        'depends_on': ['phase-3'],
                    },
                    current_payload={
                        'runtime': {
                            'request_phase_graph': {
                                'prompt': (
                                    'Analyze the generated artifacts and return one JSON list '
                                    'with fields label, artifact_ref, and evidence for A and B.'
                                ),
                                'phases': [
                                    {
                                        'phase_id': 'phase-2',
                                        'branch_id': case['producer_branch'],
                                        'capability': case['producer_capability'],
                                    },
                                    {
                                        'phase_id': 'phase-3',
                                        'branch_id': case['consumer_branch'],
                                        'capability': case['consumer_capability'],
                                        'depends_on': ['phase-2'],
                                    },
                                ],
                            },
                        },
                        'artifacts': [
                            {
                                'type': case['artifact_type'],
                                'kind': case['artifact_type'],
                                'path': case['path'],
                                'artifact_ref': case['ref'],
                                'phase_id': 'phase-2',
                                'branch_id': case['producer_branch'],
                            }
                        ],
                        'late_fill': {
                            'fill_results': [producer_result, consumer_result],
                        },
                    },
                )

                self.assertEqual(
                    payload['content_payload_source'],
                    f"late_fill_result:{case['consumer_branch']}",
                )
                self.assertIn(case['result_text'], payload['content_payload'])
                self.assertIn(f"- artifact_path: {case['path']}", payload['content_payload'])
                self.assertIn('- producer_phase_id: phase-2', payload['content_payload'])
                self.assertIn(
                    f"- producer_branch_id: {case['producer_branch']}",
                    payload['content_payload'],
                )
                artifact_ref_line = next(
                    line
                    for line in payload['content_payload'].splitlines()
                    if line.startswith('- artifact_ref: ')
                )
                carried_ref = artifact_ref_line.split(': ', 1)[1]
                canonical_artifacts = _LATE_FILL_RUNTIME.build_canonical_response_artifacts(
                    {
                        'artifacts': [
                            {
                                'type': case['artifact_type'],
                                'kind': case['artifact_type'],
                                'path': case['path'],
                                'artifact_ref': case['ref'],
                                'phase_id': 'phase-2',
                                'branch_id': case['producer_branch'],
                            }
                        ],
                        'late_fill': {'fill_results': [producer_result, consumer_result]},
                    }
                )
                self.assertTrue(
                    any(
                        str(item.get('path') or '') == case['path']
                        and carried_ref
                        in {
                            str(item.get('artifact_ref') or ''),
                            str(item.get('ref') or ''),
                        }
                        for item in canonical_artifacts
                    )
                )

