    @patch("ollmo_webserver._execute_prepared_late_fill_branch")
    @patch("ollmo_webserver._prepare_late_fill_branch_plan")
    def test_complete_response_late_fill_passes_branch_result_to_dependent_branch(
        self,
        mock_prepare_late_fill_branch_plan,
        mock_execute_prepared_late_fill_branch,
    ):
        response_id = 'resp_dependent_late_fill_chain'
        phase_graph = {
            'graph_version': 3,
            'kind': 'ollmo.request_phase_graph',
            'mode': 'phase_chain',
            'current_phase_id': 'phase-1',
            'current_phase_capability': 'chat',
            'phases': [
                {
                    'phase_id': 'phase-1',
                    'capability': 'chat',
                    'output_type': 'text',
                    'status': 'completed',
                    'depends_on': [],
                },
                {
                    'phase_id': 'phase-2',
                    'branch_id': 'branch-speech_to_text-1',
                    'capability': 'speech_to_text',
                    'output_type': 'text',
                    'status': 'pending',
                    'depends_on': ['phase-1'],
                },
                {
                    'phase_id': 'phase-3',
                    'branch_id': 'branch-text_to_speech-1',
                    'capability': 'text_to_speech',
                    'output_type': 'audio',
                    'status': 'pending',
                    'depends_on': ['phase-2'],
                    'content_payload_source': 'speech_to_text_branch_result',
                },
            ],
            'downstream_branches': [
                {
                    'phase_id': 'phase-2',
                    'branch_id': 'branch-speech_to_text-1',
                    'capability': 'speech_to_text',
                    'output_type': 'text',
                    'depends_on': ['phase-1'],
                },
                {
                    'phase_id': 'phase-3',
                    'branch_id': 'branch-text_to_speech-1',
                    'capability': 'text_to_speech',
                    'output_type': 'audio',
                    'depends_on': ['phase-2'],
                    'content_payload_source': 'speech_to_text_branch_result',
                },
            ],
        }
        prepared_calls = []

        def prepare_plan_side_effect(**kwargs):
            expected_capability = kwargs['expected_capability']
            artifact_gap = kwargs.get('artifact_gap') or {}
            prepared_calls.append(
                (
                    expected_capability,
                    str(artifact_gap.get('content_payload') or ''),
                    str(artifact_gap.get('content_payload_source') or ''),
                )
            )
            return {
                'route_info': {
                    'instance_id': f'{expected_capability}-1',
                    'capability': expected_capability,
                    'route_source': 'phase_continuation',
                    'instance': {
                        'instance_id': f'{expected_capability}-1',
                        'model': f'{expected_capability}-model',
                        'backend': 'ollama',
                        'capability': expected_capability,
                    },
                },
                'instance': {
                    'instance_id': f'{expected_capability}-1',
                    'model': f'{expected_capability}-model',
                    'backend': 'ollama',
                    'capability': expected_capability,
                },
                'effective_data': {'capability': expected_capability},
            }

        def execute_plan_side_effect(plan):
            capability = str(plan.get('capability') or '')
            if capability == 'speech_to_text':
                return {
                    'route_info': plan['route_info'],
                    'instance': plan['instance'],
                    'effective_data': plan['effective_data'],
                    'infer_result': {
                        'mode': 'speech_to_text',
                        'content': 'Light, I am.',
                        'saved_text_path': '/tmp/transcript.md',
                        'artifacts': [{'type': 'text', 'path': '/tmp/transcript.md'}],
                    },
                }
            return {
                'route_info': plan['route_info'],
                'instance': plan['instance'],
                'effective_data': plan['effective_data'],
                'infer_result': {
                    'mode': 'text_to_speech',
                    'saved_audio_path': '/tmp/transcript.wav',
                    'artifacts': [{'type': 'audio', 'path': '/tmp/transcript.wav'}],
                    'tts_semantic_source': {
                        'kind': 'ollmo.tts_semantic_source',
                        'version': 1,
                        'source_authority': 'final_infer_prompt',
                        'tts_source_text': 'Light, I am.',
                        'tts_source_text_sha256': hashlib.sha256(
                            b'Light, I am.'
                        ).hexdigest(),
                    },
                    'tts_generation_budget': {
                        'kind': 'ollmo.tts_generation_budget',
                        'policy_id': 'qwen3_tts_adaptive_audio_tokens_v1',
                        'max_tokens': 192,
                    },
                    'tts_sampling_profile': {
                        'kind': 'ollmo.tts_sampling_profile',
                        'policy_id': 'qwen3_tts_explicit_sampling_v1',
                        'temperature': 0.9,
                    },
                    'tts_audio_integrity_evidence': (
                        _passed_tts_audio_integrity_evidence(
                            'Light, I am.',
                            '/tmp/transcript.wav',
                        )
                    ),
                },
            }

        mock_prepare_late_fill_branch_plan.side_effect = prepare_plan_side_effect
        mock_execute_prepared_late_fill_branch.side_effect = execute_plan_side_effect
        response_payload = {
            'id': response_id,
            'mode': 'chat',
            'output_text': 'Preparing audio work.',
            'status': 'completed',
            'runtime': {'request_phase_graph': phase_graph},
            'late_fill': {
                'status': 'pending',
                'expected_capability': 'speech_to_text',
                'pending_branches': list(phase_graph['downstream_branches']),
                'pending_capabilities': ['speech_to_text', 'text_to_speech'],
            },
        }
        source_route_payload = {
            'route_source': 'ghost_carried',
            'route_runtime': {'request_phase_graph': phase_graph},
        }
        finalize_calls = []
        timing_events = []
        original_finalize_response_frame_payload = _LATE_FILL_RUNTIME.finalize_response_frame_payload

        def tracking_finalize_response_frame_payload(*args, **kwargs):
            finalize_calls.append(dict(kwargs))
            return original_finalize_response_frame_payload(*args, **kwargs)

        def capture_log_unified_event(**event):
            if event.get('action') == 'late_fill_post_wave_backend_timing':
                timing_events.append(dict(event))

        with patch.object(
            _LATE_FILL_RUNTIME,
            'finalize_response_frame_payload',
            side_effect=tracking_finalize_response_frame_payload,
        ), patch.object(
            _LATE_FILL_RUNTIME,
            'log_unified_event',
            side_effect=capture_log_unified_event,
        ):
            _complete_response_late_fill(
                response_payload=response_payload,
                request_payload={'prompt': 'Transcribe this audio and then read the transcript aloud.'},
                assistant_message='Preparing audio work.',
                artifact_gap={
                    'trigger': 'execution_planner_deferred_follow_up',
                    'expected_capability': 'speech_to_text',
                    'pending_branches': list(phase_graph['downstream_branches']),
                    'pending_capabilities': ['speech_to_text', 'text_to_speech'],
                },
                source_route_payload=source_route_payload,
            )

        self.assertEqual(prepared_calls[0][0], 'speech_to_text')
        self.assertEqual(
            prepared_calls[1],
            ('text_to_speech', 'Light, I am.', 'late_fill_result:branch-speech_to_text-1'),
        )
        self.assertEqual(len(finalize_calls), 1)
        self.assertTrue(finalize_calls[0].get('persist'))
        self.assertEqual([event.get('phase') for event in timing_events], ['nonterminal', 'terminal'])
        self.assertEqual(timing_events[0].get('checkpoint_mode'), 'lightweight_nonterminal')
        self.assertTrue(timing_events[0].get('finalize_skipped'))
        self.assertTrue((timing_events[0].get('response_frame_finalize_timing') or {}).get('skipped'))
        self.assertEqual(timing_events[1].get('checkpoint_mode'), 'terminal_full_frame')
        self.assertFalse(timing_events[1].get('finalize_skipped'))
        lookup_payload = _RESPONSE_LOOKUP[response_id]['response_payload']
        late_fill = lookup_payload['late_fill']
        self.assertEqual(late_fill['status'], 'completed')
        self.assertEqual([item['capability'] for item in late_fill['fill_results']], ['speech_to_text', 'text_to_speech'])
        self.assertEqual(late_fill['fill_results'][0]['content_payload'], 'Light, I am.')
        tts_fill = late_fill['fill_results'][1]
        self.assertEqual(tts_fill['tts_generation_budget']['max_tokens'], 192)
        self.assertEqual(
            tts_fill['tts_sampling_profile']['policy_id'],
            'qwen3_tts_explicit_sampling_v1',
        )
        output_slots = lookup_payload['response_frame']['planning']['artifact_flow']['output_slots']
        transcript_slot = next(slot for slot in output_slots if slot.get('branch_id') == 'branch-speech_to_text-1')
        self.assertEqual(transcript_slot.get('value'), 'Light, I am.')

    @patch("ollmo_webserver._execute_prepared_late_fill_branch")
    @patch("ollmo_webserver._prepare_late_fill_branch_plan")
    def test_complete_response_late_fill_blocks_unrelated_tts_transcript_before_join(
        self,
        mock_prepare_late_fill_branch_plan,
        mock_execute_prepared_late_fill_branch,
    ):
        response_id = 'resp_tts_stt_semantic_gate_blocks_join'
        spoken_text = (
            'Lokale KI arbeitet heute sicher direkt auf deinem persönlichen Computer.'
        )
        unrelated_transcript = 'Oh, thank you. Thank you. Thank you.'
        phase_graph = {
            'graph_version': 3,
            'kind': 'ollmo.request_phase_graph',
            'mode': 'phase_chain',
            'current_phase_id': 'phase-1',
            'current_phase_capability': 'chat',
            'phases': [
                {
                    'phase_id': 'phase-1',
                    'capability': 'chat',
                    'output_type': 'text',
                    'status': 'completed',
                    'depends_on': [],
                },
                {
                    'phase_id': 'phase-2',
                    'branch_id': 'branch-text_to_speech-1',
                    'capability': 'text_to_speech',
                    'output_type': 'audio',
                    'status': 'pending',
                    'depends_on': ['phase-1'],
                },
                {
                    'phase_id': 'phase-3',
                    'branch_id': 'branch-speech_to_text-1',
                    'capability': 'speech_to_text',
                    'output_type': 'text',
                    'status': 'pending',
                    'depends_on': ['phase-2'],
                },
                {
                    'phase_id': 'phase-4',
                    'branch_id': 'branch-chat-join-1',
                    'capability': 'chat',
                    'output_type': 'text',
                    'status': 'pending',
                    'depends_on': ['phase-3'],
                },
            ],
        }
        downstream_branches = [
            dict(phase)
            for phase in phase_graph['phases'][1:]
        ]
        phase_graph['downstream_branches'] = downstream_branches
        executed_capabilities = []

        def prepare_plan_side_effect(**kwargs):
            capability = kwargs['expected_capability']
            artifact_gap = dict(kwargs.get('artifact_gap') or {})
            effective_data = {
                'capability': capability,
                'branch_id': artifact_gap.get('branch_id'),
                'phase_id': artifact_gap.get('phase_id'),
            }
            infer_payload = {'capability': capability}
            if capability == 'text_to_speech':
                effective_data.update(
                    {
                        'content_payload': spoken_text,
                        'content_payload_source': 'focused_labeled_speakable_text',
                    }
                )
                infer_payload['prompt'] = spoken_text
            return {
                'route_info': {
                    'instance_id': f'{capability}-1',
                    'capability': capability,
                    'route_source': 'phase_continuation',
                },
                'instance': {
                    'instance_id': f'{capability}-1',
                    'model': f'{capability}-model',
                    'backend': 'deterministic-test-backend',
                    'capability': capability,
                },
                'effective_data': effective_data,
                'infer_payload': infer_payload,
            }

        def execute_plan_side_effect(plan):
            capability = str(plan.get('capability') or '')
            executed_capabilities.append(capability)
            if capability == 'text_to_speech':
                source_evidence = (
                    _LATE_FILL_RUNTIME.tts_source_evidence_from_prepared_plan(plan)
                )
                return {
                    'route_info': plan['route_info'],
                    'instance': plan['instance'],
                    'effective_data': plan['effective_data'],
                    'infer_result': {
                        'mode': 'text_to_speech',
                        'saved_audio_path': '/tmp/semantic-gate-source.wav',
                        'artifacts': [
                            {
                                'type': 'audio',
                                'path': '/tmp/semantic-gate-source.wav',
                            }
                        ],
                        'tts_semantic_source': source_evidence,
                        'tts_audio_integrity_evidence': {
                            'kind': 'ollmo.tts_audio_integrity_evidence',
                            'version': 1,
                            'policy_id': TTS_AUDIO_INTEGRITY_POLICY_ID,
                            'authority': 'runtime_deterministic_audio_verification',
                            'status': 'passed',
                            'reason_code': 'TTS_AUDIO_INTEGRITY_PASSED',
                            'materialization_eligible': True,
                            'artifact_path': '/tmp/semantic-gate-source.wav',
                            'source_sha256': source_evidence[
                                'tts_source_text_sha256'
                            ],
                        },
                    },
                }
            if capability == 'speech_to_text':
                return {
                    'route_info': plan['route_info'],
                    'instance': plan['instance'],
                    'effective_data': plan['effective_data'],
                    'infer_result': {
                        'mode': 'speech_to_text',
                        'content': unrelated_transcript,
                        'saved_text_path': '/tmp/semantic-gate-transcript.md',
                        'artifacts': [
                            {
                                'type': 'text',
                                'path': '/tmp/semantic-gate-transcript.md',
                            }
                        ],
                    },
                }
            self.fail('Downstream join must not execute after the STT evidence gate blocks.')

        mock_prepare_late_fill_branch_plan.side_effect = prepare_plan_side_effect
        mock_execute_prepared_late_fill_branch.side_effect = execute_plan_side_effect
        response_payload = {
            'id': response_id,
            'mode': 'chat',
            'output_text': spoken_text,
            'status': 'completed',
            'runtime': {'request_phase_graph': phase_graph},
            'late_fill': {
                'status': 'pending',
                'expected_capability': 'text_to_speech',
                'pending_branches': list(downstream_branches),
                'pending_capabilities': [
                    'text_to_speech',
                    'speech_to_text',
                    'chat',
                ],
            },
        }

        _complete_response_late_fill(
            response_payload=response_payload,
            request_payload={
                'prompt': (
                    'Lies den deutschen Satz vor, transkribiere das erzeugte Audio '
                    'und vergleiche das echte Transkript mit dem Original.'
                )
            },
            assistant_message=spoken_text,
            artifact_gap={
                'trigger': 'execution_planner_deferred_follow_up',
                'expected_capability': 'text_to_speech',
                'pending_branches': list(downstream_branches),
                'pending_capabilities': [
                    'text_to_speech',
                    'speech_to_text',
                    'chat',
                ],
            },
            source_route_payload={
                'route_source': 'ghost_carried',
                'route_runtime': {'request_phase_graph': phase_graph},
            },
        )

        lookup_payload = _RESPONSE_LOOKUP[response_id]['response_payload']
        late_fill = lookup_payload['late_fill']
        self.assertEqual(
            executed_capabilities,
            ['text_to_speech', 'speech_to_text'],
        )
        self.assertEqual(
            [item['capability'] for item in late_fill['fill_results']],
            ['text_to_speech'],
        )
        tts_fill = late_fill['fill_results'][0]
        self.assertEqual(
            tts_fill['tts_semantic_source']['tts_source_text'],
            spoken_text,
        )
        self.assertEqual(
            tts_fill['tts_semantic_source']['tts_source_text_sha256'],
            hashlib.sha256(spoken_text.encode('utf-8')).hexdigest(),
        )
        stt_failure = next(
            item
            for item in late_fill['failed_branches']
            if item.get('branch_id') == 'branch-speech_to_text-1'
        )
        self.assertEqual(stt_failure['status'], 'failed')
        self.assertEqual(
            stt_failure['error']['code'],
            'DEPENDENCY_CHAIN_REPAIR_REQUIRED',
        )
        self.assertEqual(stt_failure['error']['stage'], 'semantic_evidence_gate')
        self.assertEqual(
            stt_failure['error']['reason_code'],
            'TTS_STT_SEMANTIC_MISMATCH',
        )
        self.assertEqual(
            stt_failure['error']['defect_code'],
            'TTS_STT_SEMANTIC_MISMATCH',
        )
        self.assertIn(
            'does not match the exact text',
            stt_failure['error']['message'],
        )
        self.assertEqual(
            stt_failure['error']['repair_action'],
            'repair_dependency_chain',
        )
        self.assertTrue(stt_failure['error']['materialization_blocked'])
        self.assertEqual(stt_failure['error']['failed_dependency_ids'], ['phase-2'])
        self.assertEqual(
            stt_failure['error']['semantic_evidence']['status'],
            'mismatched',
        )
        self.assertEqual(
            stt_failure['error']['semantic_evidence']['reason_code'],
            'TTS_STT_SEMANTIC_MISMATCH',
        )
        self.assertEqual(late_fill['status'], 'partial_failed')
        self.assertEqual(
            late_fill['final_materialization_contract_status'],
            'unmet',
        )
        self.assertTrue(late_fill['materialization_contract_unmet'])
        self.assertEqual(lookup_payload['lifecycle_state'], 'repair_needed')
        self.assertNotEqual(
            lookup_payload['runtime']['graph_closure_review']['status'],
            'fulfilled',
        )
        completed_branch_ids = {
            item.get('branch_id')
            for item in late_fill['completed_branches']
        }
        self.assertNotIn('branch-speech_to_text-1', completed_branch_ids)
        self.assertNotIn('branch-chat-join-1', completed_branch_ids)
        self.assertFalse(
            any(
                call.kwargs.get('expected_capability') == 'chat'
                for call in mock_prepare_late_fill_branch_plan.call_args_list
            )
        )

