        mock_merge_instances.return_value = instances
        prompt = "Write a short harbor story, then show it to me as an image."
        prompt_analysis = analyze_prompt_intent(prompt)

        def build_phase_graph_side_effect(
            prompt_value,
            *,
            intent_prompt=None,
            request_payload=None,
            route_payload=None,
            response_payload=None,
        ):
            if isinstance(route_payload, dict) and route_payload.get("downstream_branches"):
                return build_request_phase_graph(
                    prompt_value,
                    intent_prompt=intent_prompt,
                    request_payload=request_payload,
                    route_payload=route_payload,
                    response_payload=response_payload,
                )
            graph = build_request_phase_graph(
                "hello",
                request_payload={
                    "ghost_route": True,
                    "prompt": "hello",
                },
            )
            graph["prompt"] = intent_prompt or prompt_value
            graph["prompt_intent"] = {
                "primary_capability": prompt_analysis.get("primary_capability"),
                "requests_audio_output": bool(prompt_analysis.get("requests_audio_output")),
                "requests_visual_output": bool(prompt_analysis.get("requests_visual_output")),
                "requested_visual_output_count": int(prompt_analysis.get("requested_visual_output_count") or 0),
                "text_preparation_before_audio_output": bool(prompt_analysis.get("text_preparation_before_audio_output")),
                "text_preparation_before_visual_output": bool(prompt_analysis.get("text_preparation_before_visual_output")),
            }
            return graph

        mock_build_request_phase_graph.side_effect = build_phase_graph_side_effect

        with app.test_request_context("/api/ghost_route_preview", method="POST"):
            route_info, resolution_error = _resolve_ghost_auto_route(
                {
                    "ghost_route": True,
                    "prompt": prompt,
                },
                preview_mode=True,
            )

        self.assertIsNone(resolution_error)
        self.assertEqual(route_info["route_source"], "ghost_carried")
        self.assertEqual(route_info["instance_id"], "chat-1")
        self.assertEqual(route_info["capability"], "chat")
        self.assertEqual(route_info["route_runtime"]["ghost_resolution"]["status"], "phase_resolved")
        self.assertEqual(route_info["route_runtime"]["request_phase_graph"]["current_phase_capability"], "chat")
        self.assertEqual(route_info["route_runtime"]["request_phase_graph"]["downstream_capabilities"], ["image_generation"])
        self.assertEqual(
            len(route_info["route_runtime"]["request_phase_graph"]["downstream_branch_ids"]),
            1,
        )
        self.assertEqual(
            route_info["route_runtime"]["developer_diagnostics"]["route_graph_consistency"]["status"],
            "accepted",
        )
        self.assertEqual(
            route_info["route_runtime"]["developer_diagnostics"]["route_graph_consistency"]["final_graph_source"],
            "consistency_enforced",
        )

