    def test_resolve_ghost_auto_route_keeps_explicit_batch_prompts_as_direct_image_batch_contract(
        self,
        mock_load_running_instances,
        mock_merge_instances,
    ):
        instances = [
            {
                "instance_id": "flux-1",
                "model": "x/flux2-klein:latest",
                "backend": "ollama",
                "capability": "image_generation",
                "port": 11438,
                "runtime_status": {"readiness": "ready", "activity": "idle"},
            },
            {
                "instance_id": "chat-1",
                "model": "gemma4:e4b",
                "backend": "ollama",
                "capability": "chat",
                "supported_capabilities": ["chat", "vision_analysis"],
                "text_capable": True,
                "port": 11437,
                "runtime_status": {"readiness": "ready", "activity": "idle"},
            },
        ]
        mock_load_running_instances.return_value = instances
        mock_merge_instances.return_value = instances
