    def test_finalize_response_frame_payload_records_backend_timing_diagnostics(self):
        prompt = "Create four images, then write an index.html that uses them."
        graph = build_request_phase_graph(
            prompt,
            request_payload={"ghost_route": True, "prompt": prompt},
            route_payload={"capability": "chat", "route_source": "ghost_carried"},
        )

        payload = _finalize_response_frame_payload(
            {
                "id": "resp_finalize_timing_diagnostics",
                "object": "response",
                "status": "completed",
                "model": "gemma4:26b",
                "backend": "ollama",
                "capability": "chat",
                "output_text": "Preparing downstream image work.",
                "runtime": {"request_phase_graph": graph},
                "late_fill": {
                    "status": "running",
                    "pending_branches": [
                        {
                            "branch_id": "branch-image_generation-1",
                            "phase_id": "phase-2",
                            "capability": "image_generation",
                            "output_type": "image",
                            "status": "pending",
                        }
                    ],
                    "active_branches": [],
                    "completed_branches": [],
                    "failed_branches": [],
                },
            },
            request_payload={"prompt": prompt},
            persist=False,
        )

        diagnostics = payload["runtime"]["developer_diagnostics"]["response_frame_finalize_timing"]
        self.assertEqual(diagnostics["phase"], "nonterminal_late_fill")
        self.assertFalse(diagnostics["persist_requested"])
        self.assertFalse(diagnostics["persist_effective"])
        self.assertEqual(diagnostics["pending_branch_count"], 1)
        self.assertGreaterEqual(diagnostics["total_elapsed_ms"], 0)
        step_names = [step["name"] for step in diagnostics["steps"]]
        self.assertIn("build_working_frame", step_names)
        self.assertIn("attach_response_frame_and_hoist_outputs", step_names)

        frame_diagnostics = payload["response_frame"]["runtime"]["developer_diagnostics"][
            "response_frame_finalize_timing"
        ]
        current_state_diagnostics = payload["response_frame"]["current_state"]["runtime"][
            "developer_diagnostics"
        ]["response_frame_finalize_timing"]
        self.assertEqual(frame_diagnostics["phase"], "nonterminal_late_fill")
        self.assertEqual(current_state_diagnostics["phase"], "nonterminal_late_fill")

