    def test_response_status_lookup_payload_is_compact_and_versioned(self):
        response_id = "resp_compact_status_observer"
        record = {
            "id": response_id,
            "message_id": "msg_compact_status",
            "status": "completed",
            "lifecycle_state": "late_fill_running",
            "response_payload": {
                "id": response_id,
                "object": "response",
                "status": "completed",
                "lifecycle_state": "late_fill_running",
                "output_text": "The first artifact is ready.",
                "artifacts": [
                    {
                        "type": "text",
                        "path": "/Users/example/Projects/ollmo/artifacts/documents/index.html",
                        "content": "<html><body>full artifact content stays out of compact status</body></html>",
                    }
                ],
                "outputs": [
                    {
                        "slot_id": "slot-html",
                        "type": "text",
                        "status": "fulfilled",
                        "artifact_ref": "artifact:html",
                    }
                ],
                "output_slots": [
                    {"slot_id": "slot-html", "type": "text", "status": "fulfilled"},
                    {"slot_id": "slot-image", "type": "image", "status": "pending"},
                ],
                "late_fill": {
                    "status": "running",
                    "pending_branches": [
                        {
                            "branch_id": "branch-image-2",
                            "capability": "image_generation",
                            "status": "pending",
                            "artifact_prompt": "this prompt is intentionally too large for compact status",
                        }
                    ],
                    "active_branches": [
                        {
                            "branch_id": "branch-image-1",
                            "capability": "image_generation",
                            "status": "running",
                            "content_payload": "large branch-local payload must not be mirrored into status",
                        }
                    ],
                    "completed_branches": [
                        {"branch_id": "branch-html", "capability": "chat", "status": "fulfilled"}
                    ],
                },
                "response_frame": {"frame_id": "frame-heavy", "large_contract": {"x": "y"}},
                "working_frame": {"status": "frozen"},
            },
        }

        compact = _build_response_status_lookup_payload(record)
        full = _build_response_lookup_payload(record)

        self.assertEqual(compact["object"], "response.status")
        self.assertTrue(compact["compact"])
        self.assertRegex(compact["state_version"], r"^[0-9a-f]{64}$")
        self.assertEqual(compact["lifecycle_state"], "late_fill_running")
        self.assertEqual(compact["late_fill"]["pending_count"], 1)
        self.assertEqual(compact["late_fill"]["active_count"], 1)
        self.assertEqual(compact["late_fill"]["completed_count"], 1)
        self.assertEqual(compact["output_counts"]["artifact_count"], 1)
        self.assertTrue(compact["status_semantics"]["has_open_continuation"])
        self.assertNotIn("artifacts", compact)
        self.assertNotIn("outputs", compact)
        self.assertNotIn("response_frame", compact)
        self.assertNotIn("working_frame", compact)
        self.assertNotIn("artifact_prompt", json.dumps(compact))
        self.assertNotIn("content_payload", json.dumps(compact))
        self.assertEqual(full["artifacts"][0]["content"], "<html><body>full artifact content stays out of compact status</body></html>")
        self.assertEqual(full["status_lookup"]["state_version"], compact["state_version"])

    def test_response_status_lookup_endpoint_returns_observer_payload(self):
        response_id = "resp_compact_status_endpoint"
        _RESPONSE_LOOKUP[response_id] = {
            "id": response_id,
            "message_id": "msg_compact_status_endpoint",
            "instance_id": "chat-1",
            "model_name": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "mode": "chat",
            "status": "completed",
            "lifecycle_state": "late_fill_pending",
            "output_text": "Initial text.",
            "response_payload": {
                "id": response_id,
                "status": "completed",
                "lifecycle_state": "late_fill_pending",
                "output_text": "Initial text.",
                "artifacts": [
                    {
                        "type": "text",
                        "path": "/Users/example/Projects/ollmo/artifacts/documents/index.html",
                        "content": "<html>full artifact content</html>",
                    }
                ],
                "late_fill": {
                    "status": "pending",
                    "pending_branches": [
                        {"branch_id": "branch-css", "capability": "chat", "status": "pending"}
                    ],
                },
            },
            "route_payload": {},
            "created_at": "2026-05-17T11:20:00Z",
            "updated_at": "2026-05-17T11:20:00Z",
            "expires_at_ts": time.time() + 60,
        }

        compact_response = self.client.get(f"/api/responses/{response_id}?view=status")
        default_response = self.client.get(f"/api/responses/{response_id}")
        debug_response = self.client.get(f"/api/responses/{response_id}?view=debug")

        self.assertEqual(compact_response.status_code, 200)
        compact = compact_response.get_json()
        self.assertEqual(compact["object"], "response.status")
        self.assertTrue(compact["compact"])
        self.assertEqual(compact["late_fill"]["pending_count"], 1)
        self.assertNotIn("artifacts", compact)
        self.assertNotIn("response_frame", compact)
        self.assertEqual(default_response.status_code, 200)
        default_payload = default_response.get_json()
        self.assertTrue(default_payload["ui_compact"])
        self.assertEqual(default_payload["artifacts"][0]["content"], "<html>full artifact content</html>")
        self.assertEqual(default_payload["status_lookup"]["state_version"], compact["state_version"])
        self.assertNotIn("response_frame", default_payload)
        self.assertNotIn("runtime", default_payload)
        self.assertEqual(debug_response.status_code, 200)
        debug_payload = debug_response.get_json()
        self.assertEqual(debug_payload["artifacts"][0]["content"], "<html>full artifact content</html>")
        self.assertEqual(debug_payload["status_lookup"]["state_version"], compact["state_version"])

