    def test_response_post_wire_projection_uses_compact_indexed_frame_without_canonical_hydration(self):
        response_id = "resp_post_wire_projection_bounded"
        bulk = "projection-bulk-" + ("x" * 900_000)
        source_payload = {
            "id": response_id,
            "object": "response",
            "status": "completed",
            "lifecycle_state": "completed",
            "model": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "mode": "chat",
            "instance_id": "chat-1",
            "output_text": "Compact public answer.",
            "outputs": [
                {
                    "slot_id": "slot-text-1",
                    "type": "text",
                    "status": "fulfilled",
                    "value": "Compact public answer.",
                }
            ],
            "artifacts": [
                {
                    "artifact_ref": "artifact:text_wire",
                    "type": "text",
                    "path": "/tmp/wire.txt",
                }
            ],
            "runtime": {
                "request_phase_graph": {
                    "kind": "ollmo.request_phase_graph",
                    "nodes": [{"id": "phase-1", "bulk": bulk}],
                },
                "developer_diagnostics": {"bulk": bulk},
            },
            "working_frame": {"kind": "ollmo.working_frame", "bulk": bulk},
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            frames_dir = Path(tmpdir)
            frozen_frame = build_response_frame(
                source_payload,
                request_payload={"prompt": "Return a compact answer."},
            )
            persist_response_frame(
                frozen_frame,
                frames_dir=frames_dir,
            )
            source_payload["response_frame"] = load_latest_response_state(
                response_id,
                frames_dir=frames_dir,
            )["response_frame"]
            with patch("ollmo_webserver.RESPONSE_FRAMES_DIR", frames_dir), patch(
                "ollmo_webserver._load_latest_response_state",
                side_effect=AssertionError("POST wire projection must not hydrate canonical state"),
            ):
                projected = _project_response_payload_for_wire(source_payload)

        encoded = json.dumps(projected, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.assertLess(len(encoded), 500_000)
        self.assertEqual(projected["output_text"], "Compact public answer.")
        self.assertEqual(projected["artifacts"][0]["artifact_ref"], "artifact:text_wire")
        self.assertNotIn("runtime", projected)
        self.assertNotIn("working_frame", projected)
        self.assertEqual(
            projected["wire_projection"]["source"],
            "current_index_compact_ledger_frame",
        )
        self.assertEqual(projected["wire_projection"]["sidecar_reads"], 0)
        self.assertTrue(projected["response_frame"]["external_snapshots"]["items"])

