    def test_in_memory_wire_fallback_has_hard_byte_ceiling_and_digest_identity(self):
        large_text = "large-public-output-" + ("x" * (9 * 1024 * 1024))
        large_manifest_token = "manifest-field-" + ("m" * 4096)
        source_payload = {
            "id": "resp_large_in_memory_wire_fallback",
            "status": "completed",
            "lifecycle_state": "completed",
            "output_text": large_text,
            "outputs": [
                {
                    "slot_id": "slot-large-text",
                    "type": "text",
                    "status": "fulfilled",
                    "value": large_text,
                }
            ],
            "artifacts": [
                {
                    "artifact_ref": "artifact:large_text",
                    "type": "text",
                    "content": large_text,
                }
            ],
            "response_frame": {
                "frame_id": "frame-large-memory",
                "frame_sequence": [large_text],
                "response_id": "resp_large_in_memory_wire_fallback",
                "external_snapshots": {
                    "kind": "ollmo.response_frame_external_snapshots",
                    "effective_snapshot_count": [large_text],
                    "items": {
                        f"{large_manifest_token}-{index}": {
                            "kind": "ollmo.response_frame_snapshot_ref",
                            "json_path": f"{large_manifest_token}.json_path.{index}",
                            "path": f"{large_manifest_token}.path.{index}",
                            "sha256": "a" * 64,
                            "size_bytes": len(large_text),
                            "source_frame_id": f"{large_manifest_token}.frame.{index}",
                            "source_response_id": f"{large_manifest_token}.response.{index}",
                        }
                        for index in range(512)
                    },
                },
            },
        }
        with patch.dict(app.config, {"TESTING": False}):
            projected = _response_wire_fallback_payload(source_payload)

        encoded = json.dumps(projected, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.assertLessEqual(len(encoded), 8 * 1024 * 1024)
        self.assertTrue(projected["output_text_ref"]["preview_truncated"])
        self.assertEqual(projected["output_text_ref"]["length_chars"], len(large_text))
        self.assertEqual(
            projected["wire_projection"]["source"],
            "in_memory_emergency_bounded_fallback",
        )
        self.assertNotIn(large_text, encoded.decode("utf-8"))

    def test_large_final_error_keeps_bounded_typed_error_identity(self):
        large_message = "ERR-BEGIN-" + ("e" * (9 * 1024 * 1024)) + "-ERR-END"
