    def test_same_frame_stale_completed_lookup_cannot_override_durable_repair(self):
        response_id = "resp_same_frame_durable_repair_convergence"
        closure_review = {
            "status": "pending",
            "continuation_required": True,
            "counts": {"fulfilled": 6, "pending": 1, "blocked": 0},
            "surface_state": {
                "status": "pending",
                "category_counts": {"open": 1, "repair_pending": 1},
            },
        }
        durable_payload = {
            "id": response_id,
            "status": "completed",
            "lifecycle_state": "repair_needed",
            "output_text": "One closure obligation still needs repair.",
            "late_fill": {
                "status": "completed",
                "pending_branches": [],
                "active_branches": [],
                "failed_branches": [],
            },
            "runtime": {"graph_closure_review": closure_review},
        }
        persist_response_frame(
            build_response_frame(
                durable_payload,
                request_payload={"prompt": "Preserve the predecessor image."},
            ),
            frames_dir=self._response_frames_dir,
        )
        durable_frame = load_latest_response_state(
            response_id,
            frames_dir=self._response_frames_dir,
        )["response_frame"]
        stale_live_payload = {
            **durable_payload,
            "lifecycle_state": "completed",
            "runtime": {},
            "response_frame": durable_frame,
        }
        _RESPONSE_LOOKUP[response_id] = {
            "id": response_id,
            "status": "completed",
            "lifecycle_state": "completed",
            "response_payload": stale_live_payload,
            "expires_at_ts": time.time() + 60,
        }

        compact_response = self.client.get(
            f"/api/responses/{response_id}?view=status"
        )
        truth_response = self.client.get(
            f"/api/responses/{response_id}?view=truth"
        )

        self.assertEqual(compact_response.status_code, 200)
        compact = compact_response.get_json()
        self.assertEqual(compact["status"], "completed")
        self.assertEqual(compact["lifecycle_state"], "repair_needed")
        self.assertEqual(
            compact["status_semantics"]["canonical_lifecycle_state"],
            "repair_needed",
        )
        self.assertTrue(compact["status_semantics"]["has_actionable_repair"])
        self.assertEqual(truth_response.status_code, 200)
        truth = truth_response.get_json()
        self.assertEqual(truth["lifecycle_state"], "repair_needed")
        self.assertEqual(_RESPONSE_LOOKUP[response_id]["lifecycle_state"], "repair_needed")

