    def test_response_debug_is_bounded_observation_while_truth_remains_canonical(self):
        response_id = "resp_bounded_debug_explicit_truth"
        bulk = "canonical-only-bulk-" + ("z" * 800_000)
        source_payload = {
            "id": response_id,
            "object": "response",
            "status": "completed",
            "lifecycle_state": "completed",
            "model": "gemma4:26b",
            "backend": "ollama",
            "capability": "chat",
            "mode": "chat",
            "instance_id": "chat-1",
            "output_text": "Developer projection answer.",
            "outputs": [
                {
                    "slot_id": "slot-text-1",
                    "type": "text",
                    "status": "fulfilled",
                    "value": "Developer projection answer.",
                }
            ],
            "runtime": {
                "request_phase_graph": {
                    "kind": "ollmo.request_phase_graph",
                    "redraw_scope_ladder_review": {
                        "review_id": "scope-review-1",
                        "status": "selected",
                        "selected_scope": "repair_artifact_ref_identity",
                    },
                    "graph_rebase_proposals": [],
                    "nodes": [{"id": "phase-1", "bulk": bulk}],
                },
                "developer_diagnostics": {
                    "runtime_graph_rebase_candidate_review": {
                        "status": "not_proposed",
                        "reason": "current_structural_closure_evidence_missing",
                    },
                    "bulk": bulk,
                },
                "graph_closure_review": {
                    "kind": "ollmo.graph_closure_review",
                    "status": "fulfilled",
                    "checks": [{"status": "fulfilled", "bulk": bulk}],
                },
            },
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            frames_dir = Path(tmpdir)
            persist_response_frame(
                build_response_frame(
                    source_payload,
                    request_payload={"prompt": "Inspect bounded developer truth."},
                ),
                frames_dir=frames_dir,
            )
            _RESPONSE_LOOKUP.clear()
            with patch("ollmo_webserver.RESPONSE_FRAMES_DIR", frames_dir):
                debug_response = self.client.get(f"/api/responses/{response_id}?view=debug")
                default_response = self.client.get(f"/api/responses/{response_id}")
                truth_response = self.client.get(f"/api/responses/{response_id}?view=truth")

        self.assertEqual(debug_response.status_code, 200)
        self.assertEqual(default_response.status_code, 200)
        self.assertEqual(truth_response.status_code, 200)
        self.assertLess(len(debug_response.data), 500_000)
        self.assertLess(len(default_response.data), 100_000)
        self.assertGreater(len(truth_response.data), len(debug_response.data) * 3)
        debug_payload = debug_response.get_json()
        self.assertTrue(debug_payload["wire_projection"]["bounded_developer_observation"])
        self.assertEqual(
            debug_payload["runtime"]["request_phase_graph"]["redraw_scope_ladder_review"]["selected_scope"],
            "repair_artifact_ref_identity",
        )
        self.assertEqual(
            debug_payload["runtime"]["developer_diagnostics"]["runtime_graph_rebase_candidate_review"]["status"],
            "not_proposed",
        )
        self.assertEqual(debug_payload["runtime"]["graph_closure_review"]["status"], "fulfilled")
        default_payload = default_response.get_json()
        self.assertTrue(default_payload["ui_compact"])
        self.assertNotIn("response_frame", default_payload)
        self.assertNotIn("runtime", default_payload)
        truth_payload = truth_response.get_json()
        self.assertIn("canonical-only-bulk-", json.dumps(truth_payload))

