    def test_merge_late_fill_result_fields_keeps_media_producer_identity_order_independent(self):
        image_result = {
            'saved_image_path': '/tmp/scene.png',
            'artifact_id': 'image_registry_scene',
            'artifact_ref': 'artifact:image_registry_scene',
            'provenance_id': 'generated_image_scene',
        }
        audio_result = {
            'saved_audio_path': '/tmp/narration.wav',
            'audio_mimetype': 'audio/wav',
        }
        transcript_result = {
            'mode': 'speech_to_text',
            'saved_text_path': '/tmp/narration-transcript.md',
            'content': 'Scene narration transcript.',
        }

        image_then_audio = _merge_late_fill_result_fields(
            _merge_late_fill_result_fields({'id': 'resp_media_order_a'}, image_result),
            audio_result,
        )
        image_then_audio = _merge_late_fill_result_fields(
            image_then_audio,
            transcript_result,
        )
        audio_then_image = _merge_late_fill_result_fields(
            _merge_late_fill_result_fields({'id': 'resp_media_order_b'}, audio_result),
            image_result,
        )
        audio_then_image = _merge_late_fill_result_fields(
            audio_then_image,
            transcript_result,
        )

        for merged in (image_then_audio, audio_then_image):
            by_path = {item['path']: item for item in merged['artifacts']}
            self.assertEqual(
                by_path['/tmp/scene.png']['artifact_ref'],
                'artifact:image_registry_scene',
            )
            self.assertNotIn(
                'generated_image',
                by_path['/tmp/narration.wav']['artifact_ref'],
            )
            self.assertNotEqual(
                by_path['/tmp/scene.png']['artifact_ref'],
                by_path['/tmp/narration.wav']['artifact_ref'],
            )
            self.assertNotIn(
                'provenance_id',
                by_path['/tmp/narration.wav'],
            )

            image_fill = _LATE_FILL_RUNTIME.attach_late_fill_result_artifact_identity(
                {
                    'branch_id': 'branch-image_generation-1',
                    'phase_id': 'phase-2',
                    'capability': 'image_generation',
                },
                merged,
                image_result,
                capability='image_generation',
            )
            audio_fill = _LATE_FILL_RUNTIME.attach_late_fill_result_artifact_identity(
                {
                    'branch_id': 'branch-text_to_speech-1',
                    'phase_id': 'phase-3',
                    'capability': 'text_to_speech',
                },
                merged,
                audio_result,
                capability='text_to_speech',
            )
            self.assertEqual(image_fill['artifact_ref'], 'artifact:image_registry_scene')
            self.assertEqual(image_fill['provenance_id'], 'generated_image_scene')
            self.assertEqual(audio_fill['artifact_ref'], audio_fill['ref'])
            self.assertTrue(audio_fill['artifact_id'].startswith('audio_'))
            self.assertNotIn('provenance_id', audio_fill)
            self.assertEqual(audio_fill['artifacts'][0]['artifact_ref'], audio_fill['artifact_ref'])
            self.assertNotEqual(image_fill['artifact_ref'], audio_fill['artifact_ref'])

